window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0028", [{"word":"recover","ipa_uk":"/rɪˈkʌvə/","ipa_us":"/rɪˈkʌvər/","definition_zh":"恢复；康复；重新获得；找回；挽回（损失）；追回（财物）；使复原；重新利用","definition_en":"to get back something that was lost, to return to a normal state after illness or difficulty, or to bring someone or something back to a healthy condition","core_image":"把手伸出去，把已经掉出掌心的东西重新抓回来","scene":"手术三个月后，他第一次独自走完那段上坡路。His breathing was rough at the bottom of the slope, but it took only a few minutes for him to recover a steady rhythm at the top.","sceneCN":"这里 recover 是「康复」（第 2 个义项：病后恢复健康）；句意：他在坡底时呼吸还很粗重，但只花了几分钟就在坡顶恢复到平稳的节奏。场景要点：康复训练用的缓坡、扶栏杆的手、逐渐均匀的呼吸、腕上的计步器。","pos":[{"tag":"vi.","zh":"恢复；康复；（从困境中）恢复过来"},{"tag":"vt.","zh":"重新获得；找回；挽回；使复原"}],"collocations":[{"phrase":"recover from illness","zh":"从疾病中康复"},{"phrase":"recover consciousness","zh":"恢复知觉"},{"phrase":"recover losses","zh":"挽回损失"},{"phrase":"recover costs","zh":"收回成本"},{"phrase":"recover stolen property","zh":"追回被盗财物"},{"phrase":"recover from a setback","zh":"从挫折中恢复"},{"phrase":"recover data","zh":"恢复数据"}],"forms":[{"label":"三单（he/she/it）","form":"recovers"},{"label":"过去式（已经发生）","form":"recovered"},{"label":"过去分词（完成／被动）","form":"recovered"},{"label":"现在分词（进行体）","form":"recovering"}],"derivatives":[{"word":"recovery","pos":"n.","zh":"恢复；康复；找回；回收"},{"word":"recoverable","pos":"adj.","zh":"可找回的；可恢复的；可挽回的"},{"word":"irrecoverable","pos":"adj.","zh":"无法找回的；不可挽回的"},{"word":"recovering","pos":"adj.","zh":"正在康复的；正在恢复的"},{"word":"recoverer","pos":"n.","zh":"找回者；追回者；恢复者"}],"senses":[{"no":"01","title":"Come back to consciousness","titleCN":"重新回到清醒","definition":"to become conscious again after fainting, injury, or anaesthesia","definitionCN":"在昏厥、受伤或麻醉之后重新恢复知觉","example":"He recovered consciousness before the ambulance reached the hospital.","exampleCN":"救护车到医院之前，他就恢复了知觉。","why":"This is the earliest recorded sense, from about 1300. Consciousness is something a person has and then loses, so coming back to it is the plainest form of getting something back.","whyCN":"这是最早记录的义项，约在 1300 年。意识是人先拥有、随后失去的东西，所以回到清醒就是“把东西拿回来”最朴素的形式。"},{"no":"02","title":"Regain health after illness","titleCN":"病后重新获得健康","definition":"to become healthy or strong again after sickness, injury, or medical treatment","definitionCN":"在患病、受伤或接受治疗之后重新变得健康或强壮","example":"She recovered from the surgery faster than anyone expected.","exampleCN":"她术后恢复得比任何人预想的都快。","why":"Health is treated as a possession that illness takes away. Recovery is the body reaching back for what was taken, which is why the verb so often appears with from.","whyCN":"健康被当作一种会被疾病夺走的拥有物。康复就是身体伸手去拿回被夺走的东西，因此这个动词常与 from 连用。"},{"no":"03","title":"Get back something lost","titleCN":"重新获得失去之物","definition":"to get back possession, control, or use of something that had been lost","definitionCN":"重新获得对已失去之物的占有、控制或使用","example":"The family never recovered the paintings stolen during the war.","exampleCN":"那家人始终没能找回战时被盗的画。","why":"From the mid-14th century the image becomes literal: re- means 'back' and the Latin stem is linked to capere 'to take', so recover is to take back.","whyCN":"从 14 世纪中期起，这个意象变得字面化：re- 意为“回”，拉丁词干与 capere“拿取”相关，因此 recover 就是“拿回来”。"},{"no":"04","title":"Recoup money or losses","titleCN":"把钱或损失收回来","definition":"to get back money that was spent or lost, or to make up for a financial loss","definitionCN":"收回已经花掉或损失的钱，或弥补财务上的亏损","example":"The company recovered its investment within two years.","exampleCN":"公司在两年内收回了投资。","why":"Money is the most countable thing one can lose. Recovering it is the bookkeeping version of the same reach: the amount that left the account is brought back into it.","whyCN":"钱是人能失去的最可计数的东西。收回钱就是同一个伸手动作的记账版本：离开账户的数额又被带回账户里。"},{"no":"05","title":"Obtain by legal judgment","titleCN":"通过法律裁判取得","definition":"in law, to obtain money, property, or a right by judgment or legal proceedings","definitionCN":"在法律上，通过判决或法律程序取得金钱、财产或权利","example":"She recovered damages from the contractor who left the roof unfinished.","exampleCN":"她向那个没把屋顶修完的承包商追回了损害赔偿。","why":"When a court orders property or money returned, the law supplies the hand that takes it back. The physical reach becomes an official procedure, recorded from the late 14th century.","whyCN":"当法院命令归还财产或金钱时，法律提供了那只把东西拿回来的手。伸手的动作变成了正式程序，这一用法记录于 14 世纪晚期。"},{"no":"06","title":"Rescue someone from danger","titleCN":"把人从危险中救回","definition":"to save a person or animal from a dangerous place or situation","definitionCN":"把人或动物从危险的地点或处境中救出","example":"Firefighters recovered two children from the flooded basement.","exampleCN":"消防员从被淹的地下室里救出了两个孩子。","why":"From the 1610s the one who reaches back is no longer the loser but a rescuer. The person in danger is brought back out of the water or the fire, as if taken from a place that had swallowed them.","whyCN":"从 17 世纪 10 年代起，伸手的不再是失去者，而是施救者。身处险境的人被从水里或火里带回来，就像从未吞噬他们的地方被取了回来。"},{"no":"07","title":"Bring another person back to health","titleCN":"使他人恢复健康","definition":"to restore another person to health or to a normal condition, a transitive use recorded around 1600","definitionCN":"使另一个人恢复健康或正常状态，这一及物用法约记录于 1600 年","example":"The old sanatorium recovered soldiers who had collapsed on the march.","exampleCN":"那所旧疗养院让行军中倒下的士兵恢复了健康。","why":"Here the verb is done to someone else: the patient is the object being brought back. The same reach now belongs to the doctor or the place, not to the recovering person.","whyCN":"这里动词作用于别人：病人是被带回来的对象。同一个伸手动作现在属于医生或疗养地，而不属于康复者本人。"},{"no":"08","title":"Return to normal after a shock","titleCN":"受冲击后回到常态","definition":"of a market, economy, or activity, to return to a normal or healthy level after a difficult period","definitionCN":"指市场、经济或活动在困难时期之后回到正常或健康的水平","example":"Tourism recovered slowly after the pandemic.","exampleCN":"疫情之后，旅游业缓慢恢复。","why":"A system has a normal level the way a person has normal health. When a shock pushes it down, recovering means climbing back to that level, so the medical image is applied to whole economies.","whyCN":"一个系统有一个正常水平，就像人有正常健康。冲击把它压低之后，恢复就是爬回那个水平，于是医学意象被用到了整个经济体上。"},{"no":"09","title":"Reclaim material, energy, or data","titleCN":"回收材料、能量或数据","definition":"to extract and use again material, energy, or data that would otherwise be wasted or inaccessible","definitionCN":"重新提取并使用原本会被浪费或无法访问的材料、能量或数据","example":"The plant recovers heat from its exhaust and warms the offices with it.","exampleCN":"工厂从废气中回收热量，用来给办公室供暖。","why":"Waste heat and deleted files are things that have left useful circulation. Recovering them is the industrial form of taking back: what was given up is pulled into the hand again.","whyCN":"废热和被删除的文件都是已经离开有效循环的东西。回收它们就是“拿回来”的工业版本：被放弃的东西又被拉回手中。"}],"etymology":{"intro":{"en":"Recover reached English through Anglo-French and Old French from Latin recuperare. Its modern spelling hides the root: the Latin stem is linked to capere 'to take', not to cover. In this batch re- means 'back' here, while require uses it as 'repeatedly', research as an intensifier, reside as 'back, again', and region has no prefix at all — its re- belongs to the root reg-.","cn":"recover 经由盎格鲁法语和古法语，来自拉丁语 recuperare。现代拼写把词根藏了起来：拉丁词干与 capere“拿取”相关，而不是 cover。本批词里，这里的 re- 表示“回”；require 的 re- 表示“反复”，research 的 re- 是加强成分，reside 的 re- 表示“回、再”，而 region 根本没有前缀——它的 re- 属于词根 reg-。"},"items":[{"era":"c. 1300","en":"First recorded in English as 'to regain consciousness' and also 'to regain health or strength after sickness, injury, etc.' The medical sense is therefore older than the sense of getting property back.","cn":"英语最早记录为“恢复知觉”，同时也表示“病后、伤后重新获得健康或力气”。因此医学义比“取回财物”的义项更古老。"},{"era":"ANGLO-FRENCH / OLD FRENCH","en":"From Anglo-French rekeverer (13c.) and Old French recovrer (11c.) 'come back, return; regain health; procure, get again'.","cn":"来自盎格鲁法语 rekeverer（13 世纪）与古法语 recovrer（11 世纪），意为“回来、返回；恢复健康；取得、重新得到”。"},{"era":"MEDIEVAL LATIN","en":"The French verb goes back to Medieval Latin recuperare 'to recover', the source also of Spanish recobrar and Italian ricoverare. The noun recuperation is recorded in English from the late 15th century.","cn":"法语动词可追溯到中世纪拉丁语 recuperare“恢复”，它也是西班牙语 recobrar 与意大利语 ricoverare 的来源。名词 recuperation 在英语中记录于 15 世纪晚期。"},{"era":"LATIN","en":"Recuperare is related to, or a variant of, Latin recipere 'to hold, contain', built from re- 'back' + capere 'to take, seize'. That is why recover means 'take back' and has nothing to do with covering something again.","cn":"recuperare 与拉丁语 recipere“握有、容纳”相关，或是其变体；后者由 re-“回”加 capere“拿取、抓住”构成。这就是 recover 意为“拿回来”、而与“重新盖上”毫无关系的原因。"},{"era":"PIE","en":"Capere is traced by standard references to PIE *kap- 'to grasp', the same root that gives capture and capable. The link is well supported, though the exact path through the medieval forms is not fully certain.","cn":"通行词源资料把 capere 追溯到原始印欧语 *kap-“抓握”，同一词根也给出 capture 与 capable。这一联系有充分支持，但经过中世纪词形时的具体路径并非完全确定。"},{"era":"MODERN ENGLISH","en":"The sense 'get back possession or control' is mid-14c., the legal sense late 14c., 'restore another to health' c.1600, and 'rescue from danger' 1610s. Recover arms (1680s) is a military drill phrase. Re-cover, with a hyphen, is a different verb meaning 'cover again'.","cn":"“重新获得占有或控制”义在 14 世纪中期，“法律上取得”义在 14 世纪晚期，“使他人恢复健康”约在 1600 年，“从危险中救出”在 17 世纪 10 年代。recover arms（17 世纪 80 年代）是军事操练用语。带连字符的 re-cover 是另一个动词，意为“重新覆盖”。"}]},"similar":{"note":{"en":"The first group separates the derived words and the look-alike hyphenated verb from recover itself; the second compares the words learners most often use in its place. Remember that only four of the five words in this batch have the prefix re-: region's re- is part of the root reg-.","cn":"第一组把派生词与带连字符的形近动词同 recover 本身分开；第二组比较学习者最常用来替换它的几个词。记住本批五个词里只有四个带前缀 re-：region 的 re- 属于词根 reg-。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"recovery","ipa":"/rɪˈkʌvəri/","tag":"derived noun","definition":"the process or fact of getting something back, or of returning to health. It is the noun from recover, not another verb.","definitionCN":"重新获得的过程或事实，或恢复健康。它是 recover 派生的名词，不是另一个动词。"},{"word":"recoverable","ipa":"/rɪˈkʌvərəbl/","tag":"derived adjective","definition":"able to be got back or restored. It describes a possibility, while recover names the act.","definitionCN":"能够被找回或恢复的。它描述可能性，而 recover 指动作本身。"},{"word":"re-cover","ipa":"/ˌriːˈkʌvə/","tag":"different word","definition":"to cover something again, for example a chair or a roof. It is re- 'again' plus cover, and has no connection with Latin capere.","definitionCN":"重新覆盖某物，例如椅子或屋顶。它是 re-“再次”加 cover，与拉丁语 capere 毫无关系。"},{"word":"irrecoverable","ipa":"/ˌɪrɪˈkʌvərəbl/","tag":"negative adjective","definition":"lost for good and impossible to get back. The ir- makes the derived adjective negative, not the verb.","definitionCN":"永久失去、无法找回的。ir- 使这个派生形容词变成否定，而不是改变动词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"restore","ipa":"/rɪˈstɔː/","tag":"put back the old state","definition":"to bring something back to its former condition or place. It stresses the agent and completeness, while recover can happen by itself and suggests taking back.","definitionCN":"使某物回到从前的状态或位置。它强调施动者与完整性，而 recover 可以自行发生，并带有“拿回来”的意思。"},{"word":"regain","ipa":"/rɪˈɡeɪn/","tag":"get back a quality or position","definition":"to get back a quality, position, or ability that had been lost. It is narrower and more formal than recover and is rarely used for health or data.","definitionCN":"重新获得失去的品质、地位或能力。它比 recover 更窄、更正式，很少用于健康或数据。"},{"word":"recuperate","ipa":"/rɪˈkjuːpəreɪt/","tag":"medical recovery","definition":"to recover health and strength after illness. It shares the Latin recuperare root but is mostly a medical verb about the body, not about property or data.","definitionCN":"病后恢复健康与体力。它与 recover 共享拉丁语 recuperare 词根，但主要是关于身体的医学动词，不用于财物或数据。"},{"word":"retrieve","ipa":"/rɪˈtriːv/","tag":"fetch back","definition":"to go and get something back from where it is stored or lost, especially data, a file, or a memory. It focuses on the act of fetching, not on returning to a healthy state.","definitionCN":"去把存放在别处或丢失的东西取回来，尤指数据、文件或记忆。它聚焦“取回”的动作，而不是回到健康状态。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: re- 'back' plus the Latin stem behind capere 'to take', the recovery family, and the three collocations that mark three senses.","cn":"只用真实成分与真实同族词：re-“回”加上 capere“拿取”背后的拉丁词干、recovery 词族，以及标记三个义项的三条搭配。"},"normal":[{"en":"re- means 'back' and the Latin stem is linked to capere 'to take'. Recover is literally 'take back'.","cn":"re- 意为“回”，拉丁词干与 capere“拿取”相关。recover 字面上就是“拿回来”。"},{"en":"The same capere root gives capture, receive, capable and recuperate, so recover belongs with 'taking', never with 'covering'.","cn":"同一 capere 词根给出 capture、receive、capable、recuperate，所以 recover 属于“拿取”这一族，与“覆盖”无关。"},{"en":"Three collocations mark three branches: recover from illness (health), recover losses (money), recover consciousness (the mind).","cn":"三条搭配标记三个分支：recover from illness（健康）、recover losses（金钱）、recover consciousness（意识）。"},{"en":"re-cover with a hyphen is a different word: re- 'again' plus cover, as when you re-cover a sofa.","cn":"带连字符的 re-cover 是另一个词：re-“再次”加 cover，就像给沙发重新包面。"},{"en":"Recovery is the noun, recoverable the adjective, and irrecoverable means lost for good.","cn":"recovery 是名词，recoverable 是形容词，irrecoverable 表示永久失去、再也找不回。"}],"abstract":[{"en":"Picture a coin slipping from your hand into tall grass. Recover is the moment you reach down and close your fingers on it again.","cn":"想象一枚硬币从手里滑进深草丛。recover 就是你俯身伸手、再次把它握回掌心的那一刻。"},{"en":"The same reach works on a body: illness drops your strength, and recovery is the slow climb back to where you were.","cn":"同一个伸手动作也作用于身体：疾病让力气掉落，康复就是慢慢爬回原来的位置。"},{"en":"From a deleted file to waste heat, anything that has left useful circulation can be recovered if there is still a hand to pull it back.","cn":"从被删除的文件到废热，任何离开有效循环的东西，只要还有一只手能往回拉，就可以被回收。"}]},"examples":[{"en":"It took him six weeks to recover from the broken leg.","cn":"他花了六周才从腿伤中恢复过来。"},{"en":"The airline is still trying to recover the money it lost during the strike.","cn":"那家航空公司仍在设法挽回罢工期间的损失。"},{"en":"Heat from the furnace is recovered and used to warm the whole building.","cn":"炉子的余热被回收，用来给整栋楼供暖。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「瑞卡获」——瑞把手卡在别人手里的福气又“获”了回来 → recover 重新获得；康复（只借音，不表词源）","word":"recover"},"root":"经由古法语 recovrer 来自拉丁语 recuperare“重新获得”，其词干与 capere“拿取”相关，核心是“把失去的东西重新拿回手里”。","sensesIntro":{"en":"Nine senses of recover, all one motion: something has left your hand, and you reach back and close your fingers on it — whether what left is consciousness, health, property, money, a legal claim, another person, a market, or waste heat.","cn":"recover 的九个义项都来自一个动作：某样东西离开了你的手，你伸手回去把它重新握住——无论离开的是意识、健康、财物、金钱、法律请求权、另一个人、一个市场，还是余热。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand reaches back and closes on what had slipped away.","cn":"核心意象：一只手往回伸，把滑走的东西重新握紧。"},"chain":["SOMETHING IS LOST","REACH BACK","CLOSE THE HAND","GET IT AGAIN","STATE RESTORED","NOTHING WASTED"],"branches":[{"senses":"S1 · S2","en":"THE BODY: consciousness and health are possessions lost to injury or illness, and recovering is the body taking them back.","cn":"身体：意识与健康是被伤病夺走的拥有物，恢复就是身体把它们拿回来。"},{"senses":"S3 · S4 · S5","en":"WHAT WAS LOST: things, money, and legal claims all leave the hand in different ways, and the law supplies an official hand for the last one.","cn":"失去之物：财物、金钱与法律请求权以不同方式离开手心，而法律为最后一种提供了那只正式的手。"},{"senses":"S6 · S7","en":"TRANSITIVE RESCUE: when the verb acts on someone else, the rescuer or healer becomes the one reaching back.","cn":"及物救回：当动词作用于别人时，施救者或治疗者成了往回伸手的那一方。"},{"senses":"S8","en":"SYSTEMS: a market or economy drops below its normal level, and recovering is the climb back to that level.","cn":"系统：市场或经济跌破正常水平，恢复就是爬回那个水平。"},{"senses":"S9","en":"MATERIALS AND DATA: waste heat and deleted files have left circulation, and the same reach pulls them back into use.","cn":"材料与数据：废热与被删文件已经离开循环，同一个伸手动作把它们拉回使用之中。"}]},"affixes":{"intro":{"en":"Recover is a living English verb with a frozen Latin core: re- 'back' plus the capere 'take' stem. English adds -y, -able, -er and -ing to the finished verb, while the same Latin root also arrives through capture, receive and recuperate.","cn":"recover 是一个活的英语动词，内核是凝固的拉丁语：re-“回”加 capere“拿取”词干。英语在成品动词后加 -y、-able、-er、-ing，而同一拉丁词根还通过 capture、receive、recuperate 进入英语。"},"latinIntro":{"en":"The Latin family is recuperare 'get back, regain', recipere 'to hold, contain' (re- + capere), and capere 'to take, seize'. Capere is the source of a large English family about taking and holding.","cn":"拉丁语词族包括 recuperare“取回、重获”、recipere“握有、容纳”（re- + capere）以及 capere“拿取、抓住”。capere 是一大批关于“拿取、持有”的英语词的来源。"},"items":[{"word":"recover","structure":"re- (back) + Latin recuperare (get back), whose stem is linked to capere (take)","meaning":"to take back what was lost","meaningCN":"把失去的东西拿回来（re- 回 + capere 拿取）","example":"She recovered her passport from the lost-property office.","exampleCN":"她从失物招领处找回了护照。"},{"word":"recovery","structure":"recover + -y (noun of state or process)","meaning":"the act or state of getting something back","meaningCN":"找回；恢复；康复（-y 构成状态或过程名词）","example":"The recovery of the stolen silver took three months.","exampleCN":"追回被盗银器花了三个月。"},{"word":"recoverable","structure":"recover + -able (can be done)","meaning":"possible to get back or restore","meaningCN":"可找回的；可恢复的（-able 表示能够）","example":"The deleted files are still recoverable from the backup.","exampleCN":"被删的文件仍可从备份中恢复。"},{"word":"irrecoverable","structure":"ir- (not) + recoverable","meaning":"impossible to get back","meaningCN":"无法找回的；不可挽回的（ir- 否定 + recoverable）","example":"The manuscript was irrecoverable after the fire.","exampleCN":"那部手稿在大火之后再也找不回来了。"},{"word":"recovering","structure":"recover + -ing (participle or noun)","meaning":"in the process of getting better; the process itself","meaningCN":"正在康复的；康复过程（-ing 分词或动名词）","example":"The recovering patients walked the corridor each morning.","exampleCN":"正在康复的病人们每天早晨在走廊里散步。"},{"word":"recoverer","structure":"recover + -er (one who does)","meaning":"a person who gets something back","meaningCN":"找回者；追回者（-er 表示行为者）","example":"The recoverer of the wreck was praised by the court.","exampleCN":"打捞沉船的人受到了法院的表扬。"},{"word":"recuperate","structure":"Latin recuperare + -ate (verb)","meaning":"to regain health or strength","meaningCN":"恢复健康；恢复体力（同根，多用于身体）","example":"He recuperated at home for a month after the operation.","exampleCN":"手术后他在家休养了一个月。"},{"word":"recuperation","structure":"recuperate + -ion (noun of process)","meaning":"the process of regaining health","meaningCN":"康复；恢复过程","example":"Her recuperation was helped by daily walks.","exampleCN":"每天的散步帮助她康复。"},{"word":"recuperative","structure":"recuperate + -ive (adjective)","meaning":"helping someone regain health","meaningCN":"有助于康复的","example":"The mountain air had a recuperative effect.","exampleCN":"山间的空气有助康复。"},{"word":"capture","structure":"capt- (capere, take) + -ure (noun or verb ending)","meaning":"to seize or take by force","meaningCN":"俘获；夺取（capt- 拿取 + -ure）","example":"The soldiers captured the bridge before dawn.","exampleCN":"士兵们在黎明前夺取了那座桥。"},{"word":"receive","structure":"re- (back) + -ceive (capere, take)","meaning":"to take into one's possession what is given","meaningCN":"收到；接收（re- 回 + capere 拿取）","example":"She received the parcel the next morning.","exampleCN":"第二天早晨她收到了包裹。"},{"word":"re-cover","structure":"re- (again) + cover (to put something over)","meaning":"to cover something again; a different word","meaningCN":"重新覆盖（另一个词，与 recover 同形不同源）","example":"They re-covered the old armchair in blue cloth.","exampleCN":"他们用蓝布把旧扶手椅重新包了一遍。"}],"latinEntries":[{"word":"recuperare","structure":"re- (back) + a stem related to capere (take)","meaning":"to get back, regain, recover","meaningCN":"取回；重获；恢复"},{"word":"recipere","structure":"re- (back) + capere (take)","meaning":"to hold, contain, receive","meaningCN":"握有；容纳；接收"},{"word":"capere","structure":"Latin verb, from PIE *kap- 'to grasp'","meaning":"to take, seize, grasp","meaningCN":"拿取；抓住；握持"}]}},{"word":"refine","ipa_uk":"/rɪˈfaɪn/","ipa_us":"/rɪˈfaɪn/","definition_zh":"提炼；精炼；改良；使精细化；使（语言、举止）变得文雅","definition_en":"to make a substance pure by removing what is unwanted, or to improve something through small and careful changes","core_image":"一锅粗金属在炉火里烧着，杂质一层层被撇掉，最后只剩发亮的纯金属","scene":"炼油厂里，工人在钢罐中加热原油。Workers heat crude oil in steel tanks to refine it, and the last impurities settle out before the clean oil leaves the plant.","sceneCN":"这里 refine 是「提炼、精炼」（第 2 个义项：把原料加工成纯品）；句意：工人在钢罐里加热原油来提炼它，最后的杂质先析出，清亮的油才离开工厂。场景要点：炼油厂的钢罐、温度计、撇出的黑色残渣、流出的清亮油液。","pos":[{"tag":"vt.","zh":"提炼；精炼；改良；使精细化"},{"tag":"vi.","zh":"变得纯净；变得文雅"}],"collocations":[{"phrase":"refine oil","zh":"精炼石油"},{"phrase":"refine sugar","zh":"精制糖"},{"phrase":"refine a method","zh":"改进方法"},{"phrase":"refine one's technique","zh":"精进技艺"},{"phrase":"refine the definition","zh":"使定义更精确"},{"phrase":"refine crude oil into petrol","zh":"把原油炼成汽油"},{"phrase":"refine one's manners","zh":"使举止更文雅"}],"forms":[{"label":"三单（he/she/it）","form":"refines"},{"label":"过去式（已经发生）","form":"refined"},{"label":"过去分词（完成／被动）","form":"refined"},{"label":"现在分词（进行体）","form":"refining"}],"derivatives":[{"word":"refined","pos":"adj.","zh":"精炼的；提纯的；文雅的"},{"word":"refinement","pos":"n.","zh":"提炼；精炼；精细；文雅"},{"word":"refinery","pos":"n.","zh":"炼油厂；精炼厂"},{"word":"refiner","pos":"n.","zh":"精炼者；炼油商"},{"word":"refining","pos":"n.","zh":"精炼；提纯过程"}],"senses":[{"no":"01","title":"Fire separates metal from dross","titleCN":"用火把金属与渣滓分开","definition":"to heat a metal and remove the impurities mixed into it, so that only the pure metal remains","definitionCN":"加热金属并除去混在其中的杂质，只留下纯金属","example":"The smith refined the gold in a small clay crucible.","exampleCN":"铁匠在一只小坩埚里提炼黄金。","why":"The word entered English in the 1580s for metals. Fire burns away what is not metal, leaving the pure part, so this is the image in its first and most physical form.","whyCN":"这个词在 16 世纪 80 年代进入英语时就是用于金属的。火把不是金属的东西烧掉，只留下纯的部分，因此这是这幅意象最原始、最具体的形态。"},{"no":"02","title":"Turn a raw material into a pure product","titleCN":"把原料加工成纯品","definition":"to treat a raw material such as oil, sugar, or salt industrially so that it becomes clean and usable","definitionCN":"对石油、糖、盐等原料进行工业加工，使其变得洁净、可用","example":"The plant refines crude oil into petrol and diesel.","exampleCN":"这家工厂把原油炼成汽油和柴油。","why":"Once the image is applied to liquids and crystals, the furnace becomes a factory: the same removal of unwanted matter is now done at scale.","whyCN":"当这幅意象用在液体和晶体上，炉子就变成了工厂：同样的“去掉不要的东西”，现在以工业规模进行。"},{"no":"03","title":"Make a definition more exact","titleCN":"把定义磨得更精确","definition":"to improve a definition, rule, or method by removing what is vague or inexact","definitionCN":"删去含混或不精确之处，使定义、规则或方法更严密","example":"The committee refined the wording so that no applicant could be excluded unfairly.","exampleCN":"委员会修改了措辞，使任何申请人都不至于受到不公的排除。","why":"Fine also meant 'delicate, exact'. Refining a rule is stripping away everything loose until only the precise part is left.","whyCN":"fine 也有“精细、精确”的意思。refine 一条规则，就是把松散的部分一层层剥掉，只留下精确的那一部分。"},{"no":"04","title":"Raise a skill to a higher standard","titleCN":"把手艺提到更高水准","definition":"to improve a skill or technique through repeated small adjustments","definitionCN":"通过反复的细微调整提高某项技能或手法","example":"She refined her serve over three seasons of daily practice.","exampleCN":"经过三个赛季的每日训练，她把发球技术磨得更精。","why":"A skill, like ore, contains rough parts. Practice removes them one at a time, and the result is a cleaner, more controlled action.","whyCN":"一项技能也像矿石，里面带着粗糙的成分。练习一次去掉一点，最后得到的是更干净、更受控的动作。"},{"no":"05","title":"Polish manners and taste","titleCN":"把举止与品味磨得文雅","definition":"to make a person's manners or taste less coarse and more cultivated","definitionCN":"使某人的举止或品味摆脱粗俗，变得有教养","example":"Years at court refined his speech and his manners.","exampleCN":"在宫廷里的那些年，把他的言谈和举止都磨得文雅了。","why":"The 1590s applied the metal image to people: what is coarse is burned away, and what remains is thought elegant.","whyCN":"16 世纪 90 年代把这套金属意象用到了人身上：粗俗的部分被烧掉，剩下的部分就被视为优雅。"},{"no":"06","title":"Improve a design through repeated testing","titleCN":"通过反复测试改进设计","definition":"to improve a design or plan by testing it and correcting small faults","definitionCN":"通过测试并修正细小缺陷来改进设计或方案","example":"Engineers refined the wing shape after each wind-tunnel test.","exampleCN":"每次风洞测试之后，工程师都会改进机翼形状。","why":"Each test reveals a flaw the way smelting reveals slag. The design is reheated and cleaned until it performs as intended.","whyCN":"每次测试暴露一处缺陷，就像冶炼暴露出矿渣。设计被重新加热、清理，直到它按预期工作。"},{"no":"07","title":"Become pure or polished on its own","titleCN":"自身变得纯净、变得文雅","definition":"of a substance or a person, to become purer or more polished without an outside agent","definitionCN":"指物质或人无需外力作用而变得更纯或更有教养","example":"The silver refines as the lead is burned away.","exampleCN":"随着铅被烧掉，白银自身变得纯净。","why":"The intransitive use, recorded around 1600, drops the craftsman: the material itself undergoes the cleaning process.","whyCN":"不及物用法记录于 1600 年前后，它去掉了工匠：材料自己经历了这个清洗过程。"},{"no":"08","title":"Split the valuable from the waste in a plant","titleCN":"在工厂里把有用之物与废料分开","definition":"in an industrial refinery, to separate a raw material into valuable products and waste","definitionCN":"在工业精炼厂中，把原料分离为有价值的产品与废料","example":"The refinery refines forty thousand barrels of crude oil every day.","exampleCN":"这座炼油厂每天精炼四万桶原油。","why":"At full industrial scale, refining is not one pot but a row of towers; the same separation now runs continuously.","whyCN":"到了完整的工业规模，精炼不是一口锅，而是一排塔；同一种分离现在昼夜不停地运行。"},{"no":"09","title":"Make language more exact and elegant","titleCN":"把语言磨得更精确、更雅致","definition":"to improve written or spoken language by removing clumsy or imprecise expressions","definitionCN":"删去笨拙或含糊的表达，使书面语或口语更精确、更雅致","example":"The editor refined the sentence until every word carried its weight.","exampleCN":"编辑反复打磨那句话，直到每个词都承担起分量。","why":"Language is treated as material: coarse wording is slag, and the refined version is the small, bright remainder.","whyCN":"语言被当作材料来处理：粗糙的措辞是矿渣，改好的版本则是剩下的一小块发亮之物。"}],"etymology":{"intro":{"en":"Refine is an English verb of the 1580s, built on re- plus an obsolete verb fine 'make fine', which comes from fine 'delicate, pure'. The exact role of re- is debated: it may be intensive rather than 'again', and the French raffiner is a close parallel. Dates follow standard etymological references.","cn":"refine 是 16 世纪 80 年代的英语动词，由 re- 加已废弃的动词 fine“使精细”构成，fine 又来自形容词 fine“精细的、纯的”。re- 的确切作用有争议：它可能是加强前缀而非“再次”，法语 raffiner 是高度平行的形式。年代依据通行词源资料。"},"items":[{"era":"1580s","en":"First recorded of metals: 'to bring or reduce to a pure state or a condition of purity as full as possible'. The image is the furnace, not the office.","cn":"最早记录于 16 世纪 80 年代，用于金属，意为“使达到或尽可能充分地达到纯净状态”。此时的核心画面是炉子，而不是办公室。"},{"era":"c.1590","en":"Extended to manners: 'purify from what is coarse, low, vulgar, inelegant'. The general and figurative sense is recorded from the 1590s.","cn":"约 1590 年扩展到举止，意为“去除粗鄙、低俗、不雅之处”。一般义与比喻义都记录于 16 世纪 90 年代。"},{"era":"1610s / c.1600","en":"Of sugar from the 1610s, which is refining as an industry. The intransitive sense 'become pure' appears around 1600.","cn":"用于糖的义项始于 17 世纪 10 年代，这时的精炼已成为一种产业。不及物义“变得纯净”约出现于 1600 年。"},{"era":"OLD FRENCH / LATIN","en":"Fine 'delicate, pure' came from Old French fin 'perfected, of highest quality', which is either a back-formation from finire or from Latin finis 'boundary, limit, end', hence 'acme, peak, height'.","cn":"fine“精细的、纯的”来自古法语 fin“完美的、品质最高的”，后者或由 finire 逆构而成，或出自拉丁语 finis“边界、界限、终点”，由此引申为“顶点、极致”。"},{"era":"re- + FINE","en":"The standard account is re- + the obsolete verb fine 'make fine'. Here re- is 'perhaps an intensive prefix', not clearly 'again'. French raffiner, Italian raffinare and Spanish refinar are the matching forms, so an exact single path is source uncertain.","cn":"通行说法是 re- 加已废弃的动词 fine“使精细”。这里的 re-“或许是一个加强前缀”，并不明确表示“再次”。法语 raffiner、意大利语 raffinare、西班牙语 refinar 都是对应形式，因此确切的单一演变路径来源不确定。"},{"era":"MODERN ENGLISH","en":"Refined, refinement (1610s) and refinery complete the family. Modern usage keeps both branches: purifying a substance, and improving anything by small exact changes.","cn":"refined、refinement（17 世纪 10 年代）、refinery 补足了词族。现代用法保留了两支：提纯某种物质，以及通过细微而精确的改动改良任何事物。"}]},"similar":{"note":{"en":"The first group separates refine from its own derived forms, which name a process, a place, a person, or a result. The second group compares refine with four verbs of improvement that are close but not interchangeable.","cn":"第一组把 refine 与它自己的派生形式分开，后者分别命名过程、场所、人和结果；第二组把 refine 与四个意思相近却不能互换的“改良”动词作比较。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"refinement","ipa":"/rɪˈfaɪnmənt/","tag":"derived noun: process","definition":"the act or process of refining, or the quality of being refined. It names the work or the polish, not the verb.","definitionCN":"提炼的行为或过程，或文雅精细的品质。它命名的是这项工作或这份修养，而不是动词本身。"},{"word":"refinery","ipa":"/rɪˈfaɪnəri/","tag":"derived noun: place","definition":"a plant where a raw material such as oil or sugar is refined. It is the place where the verb happens.","definitionCN":"精炼石油、糖等原料的工厂。它是这个动词发生的场所。"},{"word":"refiner","ipa":"/rɪˈfaɪnə/","tag":"derived noun: person","definition":"a person or company that refines a material. It is the doer, while refinery is the building.","definitionCN":"精炼某种材料的人或公司。它是行为者，而 refinery 是建筑。"},{"word":"refined","ipa":"/rɪˈfaɪnd/","tag":"past participle as adjective","definition":"purified, or polished in manner. It describes the result, while refine names the action that produced it.","definitionCN":"已提纯的，或举止文雅的。它描述结果，而 refine 命名产生这个结果的动作。"}]},{"heading":"NEAR MEANING","entries":[{"word":"improve","ipa":"/ɪmˈpruːv/","tag":"general betterment","definition":"to make something better in any way. It is the broad word; refine is narrower and means better by removing what is coarse or inexact.","definitionCN":"以任何方式使某物变好。它是最宽泛的词；refine 更窄，指通过去掉粗糙或不精确之处而变好。"},{"word":"purify","ipa":"/ˈpjuːrɪfaɪ/","tag":"remove contamination","definition":"to remove dirt, germs, or harmful substances from something. It stresses cleanliness and safety, while refine stresses raising quality toward a pure, fine standard.","definitionCN":"去除污物、细菌或有害物质。它强调洁净与安全，而 refine 强调把品质提升到纯净、精细的标准。"},{"word":"polish","ipa":"/ˈpɒlɪʃ/","tag":"surface finish","definition":"to rub a surface until it shines, or to improve a piece of work slightly. It works on the surface, while refine works through the substance.","definitionCN":"摩擦表面使其发亮，或对作品做小幅润色。它作用于表面，而 refine 作用于内部实质。"},{"word":"perfect","ipa":"/pəˈfekt/","tag":"make faultless","definition":"to make something completely free of faults. It claims a finished ideal; refine claims only a further, finer stage of the same work.","definitionCN":"使某物完全没有缺陷。它声称达到了完成的理想状态；refine 只声称在同一项工作上又精细了一层。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: re- plus the obsolete verb fine 'make fine', the adjective fine from Latin finis, and the English family refined, refinement, refinery and refiner.","cn":"只用真实成分与真实同族词：re- 加已废弃的动词 fine“使精细”、出自拉丁语 finis 的形容词 fine，以及英语词族 refined、refinement、refinery、refiner。"},"normal":[{"en":"The oldest sense is metallurgical: heat the ore, and the slag separates from the pure metal.","cn":"最古老的义项是冶金：把矿石加热，矿渣便与纯金属分开。"},{"en":"Fine originally meant 'delicate, pure, of the highest quality', so refining is literally 'making fine'.","cn":"fine 原本意为“精细的、纯的、品质最高的”，所以 refine 字面上就是“使变精细”。"},{"en":"Here re- is probably intensive, not 'again': the word means 'make very fine', not 'fine it a second time'.","cn":"这里的 re- 大概是加强语气，而不是“再次”：这个词意为“使非常精细”，而不是“再精细一次”。"},{"en":"The two modern branches are easy to tell apart: refine oil in a plant, and refine an argument in a meeting.","cn":"现代的两支很容易分辨：在工厂里 refine 石油，在会上 refine 一个论点。"},{"en":"Refinement is the quality, refinery is the place, refiner is the company or person.","cn":"refinement 是品质，refinery 是场所，refiner 是公司或人。"}],"abstract":[{"en":"Picture a crucible tilted over a flame: a grey crust is skimmed off, and what pours out is bright and narrow.","cn":"想象一只坩埚斜在火焰上：撇掉一层灰色浮渣，倒出来的东西又亮又细。"},{"en":"The same gesture works on ideas: take a rough rule, skim off the vague parts, and what remains is exact.","cn":"同一动作也能用在思想上：拿一条粗糙的规则，撇掉含混的部分，剩下的就是精确的。"},{"en":"Refine is never a single act: it is heat, skim, test, and heat again, which is why it fits skills and designs so well.","cn":"refine 从不是一次完成的动作：加热、撇去、检验、再加热，所以它特别适合技能与设计。"}]},"examples":[{"en":"Ancient alchemists tried to refine lead into gold.","cn":"古代炼金术士试图把铅提炼成黄金。"},{"en":"The coach helped her refine her breathing technique.","cn":"教练帮她改进了呼吸技巧。"},{"en":"A good editor refines a draft without changing its argument.","cn":"好的编辑会打磨稿子，却不改动它的论点。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“瑞芬”——瑞芬把一锅粗糖熬了又熬，撇去浮沫，只剩雪白的晶粒 → refine 提炼、精炼（只借音，不表词源）","word":"refine"},"root":"由 re-（此处或为加强前缀）加已废弃的动词 fine“使精细”构成，fine 又出自拉丁语 finis“界限、终点”，核心是“反复加工、去掉杂质，使其纯而精”。","sensesIntro":{"en":"Nine senses of refine, all from one process: take something rough, remove what is coarse or inexact, and keep the small bright part that is left.","cn":"refine 的九个义项都出自同一个过程：拿一样粗糙的东西，去掉粗的或不精确的部分，只留下剩下那一小块发亮的东西。"},"semanticMap":{"core":{"en":"CORE IMAGE: a crucible over fire, dross skimmed off, pure metal left.","cn":"核心意象：火上的坩埚，撇去浮渣，留下纯金属。"},"chain":["TAKE THE ROUGH MATERIAL","APPLY HEAT OR WORK","REMOVE THE COARSE PART","KEEP THE PURE PART","RAISE THE QUALITY","REPEAT UNTIL EXACT"],"branches":[{"senses":"S1 · S2","en":"MATTER: metal in a crucible and oil in a tower are purified by separating what is wanted from what is not.","cn":"物质：坩埚里的金属与塔里的石油，都是靠把要的与不要的分开而得到提纯。"},{"senses":"S3 · S9","en":"EXACTNESS: rules and sentences are skimmed of vague or clumsy parts until only the precise wording remains.","cn":"精确：规则与句子被撇去含混或笨拙的部分，直到只剩下精确的措辞。"},{"senses":"S4 · S6","en":"CRAFT: a skill or a design is improved through small repeated corrections, the way ore is reheated.","cn":"手艺：技能或设计通过反复的小修正而改进，就像矿石被重新加热。"},{"senses":"S5 · S7","en":"PERSON: manners lose their coarseness, and the intransitive form lets the person or substance refine itself.","cn":"人：举止去掉粗俗；不及物形式则让人或物质自行变得精细。"},{"senses":"S8","en":"INDUSTRY: at plant scale the single crucible becomes a row of towers running day and night.","cn":"工业：在工厂规模上，单只坩埚变成一排昼夜运行的塔。"}]},"affixes":{"intro":{"en":"Refine is re- plus the obsolete verb fine, so the prefix and the base are both visible. English then adds -ed, -ment, -ery and -er; the base fine belongs to the Latin finis family.","cn":"refine 由 re- 加已废弃的动词 fine 构成，前缀与词基都看得见。英语随后加上 -ed、-ment、-ery、-er；词基 fine 属于拉丁语 finis 词族。"},"latinIntro":{"en":"Latin finis meant 'boundary, limit, end', and finire 'to limit, finish'. The sense 'peak, height' grew from 'end', which is how fine came to mean 'of the highest quality'. The Latin prefix re- means 'back, again', though here it works as emphasis.","cn":"拉丁语 finis 意为“边界、界限、终点”，finire 意为“限定、完成”。由“终点”引申出“顶点、极致”，fine 的“品质最高”正由此而来。拉丁语前缀 re- 意为“回、再”，不过在这里起加强作用。"},"items":[{"word":"refine","structure":"re- (intensive) + obsolete fine 'make fine'","meaning":"to purify or improve by removing what is coarse","meaningCN":"提纯；通过去除粗糙部分而改良","example":"The mill refines ore before it is shipped.","exampleCN":"矿石在运出之前先由这家工厂精炼。"},{"word":"refined","structure":"refine + -ed (past participle as adjective)","meaning":"purified; polished in manner","meaningCN":"精炼的；举止文雅的（-ed 构成形容词）","example":"She spoke in a refined accent.","exampleCN":"她说话带着一种文雅的口音。"},{"word":"refinement","structure":"refine + -ment (noun of process or state)","meaning":"the process of refining, or cultivated quality","meaningCN":"提炼过程；精细；文雅（-ment 构成过程或状态名词）","example":"The design went through several refinements.","exampleCN":"这个设计经过了好几次细化。"},{"word":"refinery","structure":"refine + -ery (place where something is done)","meaning":"a plant where a raw material is refined","meaningCN":"精炼厂；炼油厂（-ery 表示场所）","example":"The sugar refinery runs all year.","exampleCN":"这座制糖厂全年运转。"},{"word":"refiner","structure":"refine + -er (person or firm that does)","meaning":"a person or company that refines material","meaningCN":"精炼者；精炼商（-er 表示行为者）","example":"The refiner buys crude oil from three countries.","exampleCN":"这家炼油商从三个国家购买原油。"},{"word":"fine","structure":"Old French fin, from Latin finis 'end, limit'","meaning":"delicate, pure, of high quality","meaningCN":"精细的；纯的；品质高的（出自拉丁语 finis“终点”）","example":"The cloth was woven from fine silk.","exampleCN":"这块布由精细的丝线织成。"},{"word":"finery","structure":"fine + -ery (collective ornaments)","meaning":"showy clothes and ornaments","meaningCN":"华丽服饰；华美的装饰（-ery 表示集合）","example":"The guests arrived in their winter finery.","exampleCN":"客人们穿着冬日的盛装到来。"},{"word":"final","structure":"fin- (Latin finis, end) + -al (adjective)","meaning":"coming at the end","meaningCN":"最终的；末尾的（fin- 终点 + -al 形容词）","example":"The final report is due on Friday.","exampleCN":"最终报告周五交。"},{"word":"define","structure":"de- (completely) + fin- (finis, boundary) + -e","meaning":"to mark out the limits of something","meaningCN":"定义；划定……的界限（de- 完全 + finis 边界）","example":"The law defines what counts as waste.","exampleCN":"法律界定了什么算作废弃物。"},{"word":"confine","structure":"con- (together) + fin- (finis, boundary)","meaning":"to keep within limits","meaningCN":"限制；禁闭（con- 一起 + finis 边界）","example":"The illness was confined to one region.","exampleCN":"这种疾病被限制在一个地区之内。"}],"latinEntries":[{"word":"finis","structure":"Latin noun","meaning":"boundary, limit, end","meaningCN":"边界；界限；终点"},{"word":"finire","structure":"finis + -ire (verb)","meaning":"to limit, finish","meaningCN":"限定；结束；完成"},{"word":"re-","structure":"Latin prefix","meaning":"back, again; often merely intensive","meaningCN":"回；再；也常仅作加强"}]}},{"word":"region","ipa_uk":"/ˈriːdʒən/","ipa_us":"/ˈriːdʒən/","definition_zh":"地区；区域；地带；行政区；领域；（身体的）部位；（数值的）大约范围","definition_en":"a broad area of land or space, an administrative division, a field of activity, or an approximate range","core_image":"一条线在地上画出的圈：圈内是一片地，圈外是别的世界","scene":"火车穿过山口之后，窗外的语言、屋顶和葡萄品种都变了。The conductor said that they had entered another region, where the roofs and the grapes looked nothing like the ones at home.","sceneCN":"这里 region 是「地理区域」（第 2 个义项：世界或国土的一部分）；句意：列车员说他们已经进入另一个区域，那里的屋顶和葡萄都跟家乡完全不一样。场景要点：山口隧道、车窗外变换的屋顶样式、葡萄园、站牌上的地名。","pos":[{"tag":"n.","zh":"地区；区域；行政区；领域；部位"}],"collocations":[{"phrase":"in the region of","zh":"大约；在……左右"},{"phrase":"the Asia-Pacific region","zh":"亚太地区"},{"phrase":"a mountainous region","zh":"山区"},{"phrase":"a region of the brain","zh":"大脑的一个区域"},{"phrase":"the region of the impossible","zh":"不可能的领域"},{"phrase":"regional economy","zh":"区域经济"},{"phrase":"desert regions","zh":"沙漠地区"}],"forms":[{"label":"名词复数","form":"regions"}],"derivatives":[{"word":"regional","pos":"adj.","zh":"地区的；区域性的；地方性的"},{"word":"regionally","pos":"adv.","zh":"在地区层面；按地区"},{"word":"regionalism","pos":"n.","zh":"地方主义；区域特色"},{"word":"regionalize","pos":"v.","zh":"按地区划分；使区域化"},{"word":"subregion","pos":"n.","zh":"亚区；分区"}],"senses":[{"no":"01","title":"A broad tract of land","titleCN":"一大片土地","definition":"a broad area of land whose boundaries are not precisely fixed","definitionCN":"一大片土地，其边界并不精确固定","example":"The northern region is mostly forest and thin soil.","exampleCN":"北部地区主要是森林和贫瘠的土壤。","why":"Latin regio came from regere 'to direct, rule', and originally named a line or boundary. A region is land that has been marked off, even if the mark is only approximate.","whyCN":"拉丁语 regio 来自 regere“引导、统治”，最初指一条线或边界。region 就是被划出来的一片地，即使那条线只是大致的。"},{"no":"02","title":"A part of the world","titleCN":"世界的一个部分","definition":"a part of the world or of a country, usually identified by climate, culture, or position","definitionCN":"世界或国家的一个部分，通常以气候、文化或位置来识别","example":"Coffee grows best in tropical regions with steady rain.","exampleCN":"咖啡在雨水稳定的热带地区长得最好。","why":"The bounded tract is scaled up to the map. Once the line is drawn on a map, the land inside is a region, and neighbouring regions acquire different climates and customs.","whyCN":"被划出的地块放大到了地图上。一旦线被画在地图上，圈内的土地就是一个 region，相邻的区域也获得了不同的气候与习俗。"},{"no":"03","title":"An administrative division","titleCN":"行政区、省份","definition":"a named administrative division of a country, with its own government or offices","definitionCN":"国家的一个有名行政区划，拥有自己的政府或机构","example":"The region of Campania has its own governor and budget.","exampleCN":"坎帕尼亚大区有自己的行政长官和预算。","why":"Here the boundary is legal rather than natural. The line is drawn by an authority, which is exactly what the root regere 'to rule' implies: the ruler's line makes the region.","whyCN":"这里的边界是法律的，而不是自然的。线由权威画出，这正是词根 regere“统治”所暗示的：统治者的线造出了区域。"},{"no":"04","title":"The countryside around a city","titleCN":"城市周边的乡野","definition":"the rural area lying around a city, used in contrast with the city itself","definitionCN":"环绕城市的那片乡村地带，与城市本身相对","example":"The old nobility still owned estates in the region.","exampleCN":"旧贵族仍在这一带拥有庄园。","why":"From the late 14th century the word also named the land outside the walls. The city is the centre, and the region is the ring of fields and villages around it.","whyCN":"从 14 世纪晚期起，这个词也指城墙之外的土地。城市是中心，region 就是环绕它的那一圈田野与村庄。"},{"no":"05","title":"A part of the body","titleCN":"身体的一个部位","definition":"a defined part or zone of the body, especially in anatomy and medicine","definitionCN":"身体的一个确定部位或区域，尤用于解剖学与医学","example":"The surgeon worked on the lumbar region of the spine.","exampleCN":"外科医生在脊柱的腰部区域动手术。","why":"The line that marks off land is redrawn on the body. Anatomy divides the body into named regions, so the same word for a bounded tract now names a bounded part.","whyCN":"划出土地的那条线被重新画在身体上。解剖学把身体分成有名字的区域，于是同一个表示“被划出的地块”的词，现在命名一个被划出的部位。"},{"no":"06","title":"A sphere of activity or thought","titleCN":"活动或思想的领域","definition":"a field of activity, knowledge, or thought with its own boundaries","definitionCN":"活动、知识或思想的一个领域，有自己的边界","example":"That question lies outside the region of physics.","exampleCN":"那个问题落在物理学的领域之外。","why":"The boundary becomes invisible. What separates physics from poetry is not a fence but a limit of method, yet the mind still pictures a territory with an inside and an outside.","whyCN":"边界变得看不见了。把物理学与诗歌分开的不是篱笆，而是方法的界限，但头脑仍然把它想象成一块有内有外的领地。"},{"no":"07","title":"An approximate range of a number","titleCN":"数值的大致范围","definition":"in the phrase in the region of, approximately or about a particular amount","definitionCN":"用于 in the region of 这一短语，表示大约、在某个数量左右","example":"The repairs will cost in the region of ten thousand pounds.","exampleCN":"维修费用大约在一万英镑左右。","why":"The bounded area becomes a bounded interval on a scale. A number 'in the region of' ten thousand is not exactly ten thousand; it is somewhere inside that neighbourhood.","whyCN":"被划出的区域变成刻度上一个被划出的区间。in the region of ten thousand 的数不是精确的一万，而是落在那个邻近区间里的某处。"},{"no":"08","title":"A layer or zone of the atmosphere","titleCN":"大气或空间的一层","definition":"one of the horizontal layers or zones of the atmosphere, oceans, or space","definitionCN":"大气、海洋或空间中水平划分的一层或一个带","example":"Weather balloons climb into the upper region of the atmosphere.","exampleCN":"气象气球升入大气的高层区域。","why":"Height is divided into horizontal bands the way land is divided into tracts. The upper region is not a place with a fence but a layer with a defined range.","whyCN":"高度像土地被分成地块那样，被分成水平的带。高层区域不是有篱笆的地方，而是一个有确定范围的一层。"},{"no":"09","title":"A bounded area in computing","titleCN":"计算机中的一个限定区域","definition":"a defined block of memory, or a selected area of a screen or map","definitionCN":"一块被限定的内存区域，或屏幕、地图上被选定的区域","example":"The program copies the image into a separate memory region.","exampleCN":"程序把图像复制到一个单独的内存区域。","why":"Software needs edges even when nothing physical is being divided. A memory region is a range with a start and an end, the same bounded tract expressed as two addresses.","whyCN":"即使没有实体被分割，软件也需要边界。内存区域是一段有起点和终点的范围，也就是同一块被限定的地，用两个地址表达出来。"}],"etymology":{"intro":{"en":"Region looks as if it begins with re-, but it does not: the re- belongs to the root reg-, from Latin regere 'to direct, rule'. The word's core is a line drawn to bound a tract of land. That makes region unlike recover (capere 'take'), require (quaerere 'ask'), research (circare 'go about') and reside (sedere 'sit'), all of which carry a real re- prefix.","cn":"region 看起来像以 re- 开头，其实不是：它的 re- 属于词根 reg-，来自拉丁语 regere“引导、统治”。这个词的核心是一条画出来、把一片地围住的线。因此 region 与 recover（capere“拿取”）、require（quaerere“询问”）、research（circare“绕行”）、reside（sedere“坐”）都不同，后四个才带真正的前缀 re-。"},"items":[{"era":"c. 1300","en":"First recorded as regioun, 'tract of land of a considerable but indefinite extent'. It also meant 'a kingdom, country, nation; the people of a country'.","cn":"最早记录为 regioun，意为“范围相当大但边界不定的一片土地”，同时也表示“王国、国家、民族；一国的人民”。"},{"era":"ANGLO-FRENCH / OLD FRENCH","en":"From Anglo-French regioun and Old French region 'land, region, province' (12c.), and directly from Latin regionem, nominative regio.","cn":"来自盎格鲁法语 regioun 与古法语 region“土地、地区、省份”（12 世纪），并直接来自拉丁语 regionem（主格 regio）。"},{"era":"LATIN regio","en":"Latin regio meant 'a district, portion of a country, territory; a direction, line; boundary line, limit'. It was a noun of state from the past-participle stem of regere.","cn":"拉丁语 regio 意为“区、国家的一部分、领土；方向、直线；边界线、界限”。它是 regere 过去分词词干的性状名词。"},{"era":"regere / PIE *reg-","en":"Regere means 'to direct, rule', from PIE *reg- 'move in a straight line', with derivatives meaning 'to direct in a straight line', hence 'to lead, rule'. A straight line is what makes a boundary.","cn":"regere 意为“引导、统治”，来自原始印欧语 *reg-“沿直线移动”，其派生义为“沿直线引导”，进而表示“带领、统治”。正是直线构成了边界。"},{"era":"LATE 14C.","en":"The sense 'a part of the world' appears in the late 14th century, as does 'the rural area around a city'. The word is now both a map unit and a city's hinterland.","cn":"“世界的一个部分”这一义项出现于 14 世纪晚期，“城市周边的乡村地带”也在同一时期出现。这个词如今既是地图单位，也是城市腹地。"},{"era":"MODERN ENGLISH","en":"The phrase in the region of 'about' is recorded from 1961. Regional is from the early 15th century, and subregion from 1830. The Latin root also gives regal, regent, regime, regulate, direct, correct and rectangle.","cn":"短语 in the region of“大约”记录于 1961 年。regional 始于 15 世纪早期，subregion 始于 1830 年。同一拉丁词根还给出 regal、regent、regime、regulate、direct、correct、rectangle。"}]},"similar":{"note":{"en":"The first group separates the derived forms from the noun; the second compares the four area words learners mix up. Region is usually a large or officially bounded area, while its re- is part of reg- 'rule', not the prefix of recover, require, research or reside.","cn":"第一组把派生形式同名词分开；第二组比较学习者容易混用的四个“区域”词。region 通常指较大或官方划定的区域，而它的 re- 属于 reg-“统治”，不是 recover、require、research、reside 的那个前缀。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"regional","ipa":"/ˈriːdʒənl/","tag":"derived adjective","definition":"relating to a particular region. It describes something belonging to a region, while region names the area itself.","definitionCN":"与某一地区有关的。它描述属于某个地区的事物，而 region 命名这个地区本身。"},{"word":"regionalism","ipa":"/ˈriːdʒənəlɪzəm/","tag":"derived noun","definition":"loyalty to one's own region, or a feature peculiar to it. It is an attitude or a local trait, not the area.","definitionCN":"对本地区的忠诚，或本地区特有的特征。它是一种态度或地方特色，而不是地区本身。"},{"word":"regionally","ipa":"/ˈriːdʒənəli/","tag":"derived adverb","definition":"in a regional way or at the regional level. It modifies an action, while region is a noun.","definitionCN":"以地区方式，或在地区层面上。它修饰动作，而 region 是名词。"},{"word":"subregion","ipa":"/ˈsʌbriːdʒən/","tag":"derived noun","definition":"a smaller division inside a region. The sub- marks a region within a region.","definitionCN":"一个地区内部的更小分区。sub- 标记“区域之中的区域”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"area","ipa":"/ˈeəriə/","tag":"general size or space","definition":"a part of a place or a measured surface. It is the most general word and can be as small as a room; region usually suggests a larger or more defined stretch.","definitionCN":"一个地方的一部分，或一个被测量的表面。它是最通用的词，可以小到一个房间；region 通常暗示更大或更明确的一片。"},{"word":"district","ipa":"/ˈdɪstrɪkt/","tag":"official subdivision","definition":"an official division of a city, country, or organization for administration. It is usually smaller and more precisely defined than a region.","definitionCN":"城市、国家或组织为行政而划分的正式区域。它通常比 region 更小、边界更精确。"},{"word":"zone","ipa":"/zəʊn/","tag":"purpose-marked area","definition":"an area marked off for a particular purpose, such as a climate zone or a no-parking zone. It stresses function or rule, while region stresses land or extent.","definitionCN":"为特定目的划出的区域，如气候带或禁停区。它强调功能或规则，而 region 强调土地或范围。"},{"word":"realm","ipa":"/relm/","tag":"kingdom or domain","definition":"a kingdom, or a sphere of activity. It is more literary and more abstract than region, and it comes from a different French source, not from the Latin reg- root.","definitionCN":"王国，或活动的领域。它比 region 更文学化、更抽象，而且来自另一条法语来源，并非拉丁语 reg- 词根。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: Latin regere 'to rule, direct', regio 'a bounded district', the *reg- family, and the five derived forms regional, regionally, regionalism, regionalize and subregion.","cn":"只用真实成分与真实同族词：拉丁语 regere“统治、引导”、regio“被划定的区”、*reg- 词族，以及五个派生形式 regional、regionally、regionalism、regionalize、subregion。"},"normal":[{"en":"regere means 'to rule, direct', and a ruler draws straight lines. A region is the land inside one of those lines.","cn":"regere 意为“统治、引导”，而统治者画直线。region 就是其中一条线以内的土地。"},{"en":"The same *reg- root gives regal, regent, regime, regulate, direct, correct and rectangle — all about straight lines and rule.","cn":"同一 *reg- 词根给出 regal、regent、regime、regulate、direct、correct、rectangle——全都关于直线与统治。"},{"en":"Region's re- is not a prefix: it is the start of reg-, so do not link it to recover or reside.","cn":"region 的 re- 不是前缀：它是 reg- 的开头，所以不要把它和 recover 或 reside 联系起来。"},{"en":"in the region of means 'about': a number inside a small neighbourhood on a scale.","cn":"in the region of 意为“大约”：刻度上某个数附近的一小片邻域。"},{"en":"Regional is the adjective, regionalism the attitude, and subregion a region inside a region.","cn":"regional 是形容词，regionalism 是态度，subregion 是区域内部的区域。"}],"abstract":[{"en":"Picture a ruler drawing one straight line across a map. Everything on one side becomes a region; everything on the other side becomes somewhere else.","cn":"想象一把尺子在地图上画下一条直线。线这一侧的一切成为一个 region；另一侧的一切成为别处。"},{"en":"The line can be moved from land to the body, to thought, to numbers, to memory: wherever a boundary is drawn, there is a region inside it.","cn":"这条线可以从土地移到身体、思想、数字与内存：只要画下一条边界，界内就有一个 region。"},{"en":"A region is not the line itself but the inside it creates, which is why the word always implies both an edge and a stretch of ground.","cn":"region 不是线本身，而是线所造成的内部，所以这个词总同时暗示一条边和一片地。"}]},"examples":[{"en":"The wine is grown in a cool region near the coast.","cn":"这种葡萄酒产自沿海一个凉爽的地区。"},{"en":"Damage to that region of the brain can affect speech.","cn":"大脑那个区域受损可能影响言语能力。"},{"en":"A new laptop will cost in the region of eight hundred dollars.","cn":"一台新笔记本电脑大约要八百美元。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「瑞金」——瑞金既是一座城，也是一片有名的地区 → region 地区；区域（只借音，不表词源）","word":"region"},"root":"源自拉丁语 regio“被划定的区”，其词根 regere 意为“引导、统治”，可追溯到原始印欧语 *reg-“沿直线移动”，核心是“用一条线划出来的一片地”。","sensesIntro":{"en":"Nine senses of region, all from one act: drawing a line to bound a stretch. The stretch can be land, a part of the world, a province, a city's hinterland, a body part, a field of thought, a numeric neighbourhood, a layer of air, or a block of memory.","cn":"region 的九个义项都来自同一个动作：画一条线，把一片范围围起来。这片范围可以是土地、世界的一部分、省份、城市腹地、身体部位、思想领域、数值邻域、大气的一层，或一块内存。"},"semanticMap":{"core":{"en":"CORE IMAGE: a straight line drawn to enclose a stretch of ground.","cn":"核心意象：画下一条直线，把一片地圈在里面。"},"chain":["DRAW A LINE","ENCLOSE A TRACT","NAME THE INSIDE","GIVE IT A GOVERNMENT","MOVE THE LINE INWARD","BOUND ANY RANGE"],"branches":[{"senses":"S1 · S2 · S3","en":"LAND: an indefinite tract, a part of the world, and an administrative province are the same enclosed ground at three scales.","cn":"土地：边界不定的一片地、世界的一部分、行政区划，是同一片被圈起来的土地在三种尺度上。"},{"senses":"S4","en":"AROUND THE CITY: the line is drawn at the city wall, and the fields outside become the region.","cn":"城市周边：线画在城墙处，墙外的田野就成了 region。"},{"senses":"S5","en":"THE BODY: anatomy redraws the line inside a person and names the enclosed part.","cn":"身体：解剖学把线画进人体内部，并给被围住的部位命名。"},{"senses":"S6","en":"THOUGHT: the boundary becomes invisible, marking what a discipline does and does not cover.","cn":"思想：边界变得看不见，标记一门学科涵盖与不涵盖的范围。"},{"senses":"S7 · S8 · S9","en":"MEASURED RANGES: a numeric neighbourhood, a layer of atmosphere, and a block of memory are all bounded intervals rather than ground.","cn":"可测的范围：数值邻域、大气的一层、一块内存，都是有界的区间，而不是土地。"}]},"affixes":{"intro":{"en":"Region is not re- plus a root; it is the Latin stem reg- plus -ion. English adds -al, -ly, -ism, -ize and sub-. The same reg- root also supplies regal, regent, regime, regulate, direct, correct and rectangle.","cn":"region 不是 re- 加词根，而是拉丁词干 reg- 加 -ion。英语再加 -al、-ly、-ism、-ize 与 sub-。同一 reg- 词根还供应 regal、regent、regime、regulate、direct、correct、rectangle。"},"latinIntro":{"en":"Latin regere 'to direct, rule' gives the noun regio 'a district, boundary line', the noun rex 'king', and the noun regula 'rule, straight stick'. The PIE root *reg- means 'move in a straight line', which links ruling to drawing a straight boundary.","cn":"拉丁语 regere“引导、统治”给出名词 regio“区、边界线”、名词 rex“国王”与名词 regula“规则、直尺”。原始印欧语词根 *reg- 意为“沿直线移动”，把“统治”与“画一条笔直的边界”联系起来。"},"items":[{"word":"region","structure":"reg- (direct, rule) + -ion (noun of state)","meaning":"a district bounded by a line","meaningCN":"被一条线划定的区域（reg- 引导 + -ion 状态名词）","example":"The region has been famous for its wool for centuries.","exampleCN":"这个地区几百年来以羊毛闻名。"},{"word":"regional","structure":"region + -al (adjective)","meaning":"relating to a region","meaningCN":"地区的；区域性的（-al 构成形容词）","example":"Regional differences in accent are still strong.","exampleCN":"口音的地区差异仍然很明显。"},{"word":"regionally","structure":"regional + -ly (adverb)","meaning":"at the level of a region","meaningCN":"在地区层面上（-ly 构成副词）","example":"The paper is published regionally, not nationally.","exampleCN":"这份报纸在地区发行，而不是全国发行。"},{"word":"regionalism","structure":"regional + -ism (doctrine or feature)","meaning":"loyalty to a region, or a local feature","meaningCN":"地方主义；地方特色（-ism 构成主义或特征）","example":"The novel is full of the regionalism of the northern coast.","exampleCN":"这部小说充满北部海岸的地方特色。"},{"word":"regionalize","structure":"regional + -ize (verb)","meaning":"to organize something by region","meaningCN":"按地区组织；使区域化（-ize 构成动词）","example":"The company regionalized its supply chain last year.","exampleCN":"公司去年把供应链按地区重新组织。"},{"word":"subregion","structure":"sub- (under, below) + region","meaning":"a smaller division within a region","meaningCN":"亚区；分区（sub- 在下 + region）","example":"Each subregion has a different rainfall pattern.","exampleCN":"每个分区都有不同的降雨模式。"},{"word":"regal","structure":"reg- (king, rule) + -al (adjective)","meaning":"belonging to a king or queen","meaningCN":"王室的；帝王般的（reg- 王 + -al 形容词）","example":"The hall was decorated in regal red and gold.","exampleCN":"大厅以帝王般的红金两色装饰。"},{"word":"regent","structure":"reg- (rule) + -ent (one who does)","meaning":"a person who rules during a monarch's absence or minority","meaningCN":"摄政者（reg- 统治 + -ent 行为者）","example":"A regent governed the country while the king was abroad.","exampleCN":"国王出国期间由一位摄政者治理国家。"},{"word":"regulate","structure":"regula (rule, straight stick) + -ate (verb)","meaning":"to control by rules","meaningCN":"管理；调节（regula 规则、直尺 + -ate 动词）","example":"The agency regulates the safety of new drugs.","exampleCN":"该机构监管新药的安全。"},{"word":"direct","structure":"dis- + regere (to set straight)","meaning":"to guide or manage","meaningCN":"指导；导演（dis- + regere 使变直）","example":"She directed the whole production herself.","exampleCN":"整场制作由她亲自执导。"},{"word":"correct","structure":"com- (together) + regere (make straight)","meaning":"to make right or accurate","meaningCN":"改正；正确的（com- 共同 + regere 使直）","example":"He corrected the spelling on the label.","exampleCN":"他改正了标签上的拼写。"},{"word":"rectangle","structure":"rect- (straight) + angle","meaning":"a four-sided shape with right angles","meaningCN":"长方形；矩形（rect- 直 + angle 角）","example":"The garden is laid out as a long rectangle.","exampleCN":"花园被布置成一个狭长的矩形。"}],"latinEntries":[{"word":"regere","structure":"Latin verb, from PIE *reg- 'move in a straight line'","meaning":"to direct, rule, lead, govern","meaningCN":"引导；统治；带领；治理"},{"word":"regio","structure":"reg- (direct) + -io (noun of state)","meaning":"a district, boundary line, direction","meaningCN":"区；边界线；方向"},{"word":"regula","structure":"reg- (straight) + -ula (diminutive)","meaning":"a rule, a straight stick","meaningCN":"规则；直尺"}]}},{"word":"register","ipa_uk":"/ˈredʒɪstə/","ipa_us":"/ˈredʒɪstər/","definition_zh":"登记册；记录器；收银机；音域；语域；寄存器；登记；注册；显示（读数）；流露出（神情）","definition_en":"an official book or list of records, a device that records data, a range of a voice or instrument, or to write something into a list and show a reading","core_image":"一本摊在柜台上的厚册子，每来一个人、每做一笔账，就在格子里添上一行","scene":"Every visitor must register at the front desk before entering the plant.","sceneCN":"这里 register 是「登记姓名」（第 7 个义项：把自己的名字写进名单）；句意：每位来访者进厂前都必须在前台登记姓名。场景要点：前台、翻开的登记簿、递过来的笔、挂在胸前的访客证。","pos":[{"tag":"n.","zh":"登记册；记录器；收银机；音域；语域；寄存器"},{"tag":"v.","zh":"登记；注册；显示（读数）；流露出（神情）"}],"collocations":[{"phrase":"register for a course","zh":"报名参加课程"},{"phrase":"register with a doctor","zh":"在诊所登记（成为其病人）"},{"phrase":"register a company","zh":"注册公司"},{"phrase":"register a complaint","zh":"正式提出投诉"},{"phrase":"a register of voters","zh":"选民名册"},{"phrase":"cash register","zh":"收银机"},{"phrase":"speak in a formal register","zh":"用正式语体说话"}],"forms":[{"label":"三单（he/she/it）","form":"registers"},{"label":"过去式（已经发生）","form":"registered"},{"label":"过去分词（完成／被动）","form":"registered"},{"label":"现在分词（进行体）","form":"registering"},{"label":"名词复数","form":"registers"}],"derivatives":[{"word":"registration","pos":"n.","zh":"登记；注册；挂号"},{"word":"registry","pos":"n.","zh":"登记处；注册表；登记簿"},{"word":"registrar","pos":"n.","zh":"登记员；注册主任；户籍员"},{"word":"registrant","pos":"n.","zh":"登记者；注册人"},{"word":"registered","pos":"adj.","zh":"已登记的；注册的；挂号的"}],"senses":[{"no":"01","title":"The book that holds the entries","titleCN":"收藏条目的册子","definition":"an official book or list in which names, events, or amounts are written down and kept","definitionCN":"正式记录姓名、事件或金额并加以保存的册子或名单","example":"The parish register records every birth and marriage since 1700.","exampleCN":"这个教区登记簿记录了 1700 年以来每一次出生与婚姻。","why":"The Latin verb regerere meant 'carry back': events were carried back into a book so that they would not be lost. The book is that carried-back record.","whyCN":"拉丁语动词 regerere 意为“带回来”：发生的事情被带回一本册子里，以免丢失。这本册子就是那份被带回的记录。"},{"no":"02","title":"The machine that rings up a sale","titleCN":"记录一笔买卖的机器","definition":"a machine that records the amount of money taken in a sale and keeps a running total","definitionCN":"记录每笔交易金额并累计总额的机器","example":"She opened the cash register and counted the morning's takings.","exampleCN":"她打开收银机，清点了上午的收入。","why":"Once entries were kept by a machine rather than a clerk, the name of the book moved to the box: the register registers each sale as it happens.","whyCN":"当条目由机器而不是店员来记录，这本册子的名字就转移到了那只箱子上：收银机在每笔交易发生时把它记下来。"},{"no":"03","title":"The range of a voice or instrument","titleCN":"人声或乐器的音域","definition":"the range of pitches that a voice or instrument can produce, or a part of that range with a distinct quality","definitionCN":"人声或乐器能发出的音高范围，或其中音质独特的一段","example":"The soprano's upper register was clear and effortless.","exampleCN":"那位女高音的高音区清亮而毫不费力。","why":"A register was first a list, then the compass of a voice — the full list of notes it can reach. The musical sense, recorded in 1811, treats pitch as entries on a scale.","whyCN":"register 先是一份名单，再是一个声音的“音域”——它能达到的全部音符的名单。音乐义记录于 1811 年，把音高当作同一把尺子上的条目。"},{"no":"04","title":"The level of language a situation calls for","titleCN":"场合要求的语言层次","definition":"in linguistics, a style or level of language used in a particular social situation","definitionCN":"语言学中指在特定社会场合所使用的语言风格或层次","example":"The report was written in a formal academic register.","exampleCN":"这份报告用的是正式的学术语体。","why":"The musical idea of a range or level was carried into language: a speaker moves between formal and casual registers much as a voice moves between high and low.","whyCN":"音乐里“音域、层次”的观念被带进了语言：说话人在正式与随意之间切换语体，正如人声在高音与低音之间移动。"},{"no":"05","title":"A slot inside a processor","titleCN":"处理器里的一个存储槽","definition":"in computing, a small, fast storage location inside a processor that holds one piece of data during an operation","definitionCN":"计算机中指处理器内部容量很小、速度很快的存储位置，在一次运算中存放一项数据","example":"The program loads both numbers into registers before adding them.","exampleCN":"程序先把两个数装进寄存器，然后再相加。","why":"A processor register is a numbered slot where a value is entered and kept, the smallest version of the ledger's ruled line.","whyCN":"处理器寄存器是一个编号的格子，一个数值被“写进去”并保存在那里，它是账簿横线的最小版本。"},{"no":"06","title":"Write it into the record","titleCN":"把它写进记录","definition":"to write a name, fact, or amount into an official list or system","definitionCN":"把姓名、事实或金额写进正式的名单或系统","example":"The clerk registered the deed at the county office.","exampleCN":"职员在县办事处登记了这份契约。","why":"This is the verb built directly on the noun: to register is to put an entry into the register.","whyCN":"这是直接由名词构成的动词：to register 就是把一个条目放进登记册。"},{"no":"07","title":"Put your own name down","titleCN":"把自己的名字写上","definition":"to add your own name to a list in order to take part in something","definitionCN":"为参加某项活动而把自己的名字加入名单","example":"You must register to vote before the end of the month.","exampleCN":"你必须在本月底之前登记才能投票。","why":"The verb turned reflexive in ordinary use: the person becomes both the writer and the entry. This sense is recorded from 1848.","whyCN":"这个动词在日常使用中转向了自身：人既是书写者，也是被写下的那一条。这个义项记录于 1848 年。"},{"no":"08","title":"Show a reading on a dial","titleCN":"在表盘上显示读数","definition":"of an instrument, to show or record a measured value","definitionCN":"指仪器显示或记录某个测得的数值","example":"The thermometer registered thirty degrees at noon.","exampleCN":"正午时温度计显示三十度。","why":"An instrument registering is the machine doing the clerk's work: it enters the measurement into its own record and displays it.","whyCN":"仪器 register，就是机器在做店员的活：它把测量结果写进自己的记录，并显示出来。"},{"no":"09","title":"Let an expression show","titleCN":"让神情显露出来","definition":"of a feeling, to appear on a face or in a voice before it is put into words","definitionCN":"指某种情绪在说出口之前先显现在脸上或声音里","example":"Surprise registered on her face before she spoke.","exampleCN":"她还没开口，惊讶就先显在了脸上。","why":"The 1901 sense treats the face as an instrument: the feeling reaches the surface and the dial moves.","whyCN":"1901 年的这个义项把脸当作一台仪器：情绪抵达表面，表盘便动了。"}],"etymology":{"intro":{"en":"Register comes from Medieval Latin registrum, a much altered form of regestum, from Latin regerere 'carry back'. The second -r- was added by analogy, and some later senses were coloured by the unrelated regere 'rule'. Dates follow standard etymological references.","cn":"register 来自中世纪拉丁语 registrum，它是 regestum 经过大幅变形的形式，源头是拉丁语 regerere“带回”。第二个 -r- 是类比加上的，后来某些义项又受到无关的 regere“统治”影响。年代依据通行词源资料。"},"items":[{"era":"LATE 14C.","en":"The noun registre is first recorded meaning 'public record book, private account book, an official written account regularly kept'.","cn":"名词 registre 最早记录于 14 世纪晚期，意为“公共记录簿、私人账簿、定期保存的正式书面记录”。"},{"era":"MEDIEVAL LATIN","en":"From Old French registre (13c.) and directly from Medieval Latin registrum, regestrum, properly regestum, from Late Latin regesta 'list, matters recorded'. The unetymological second -r- came by influence of Latin nouns in -istrum.","cn":"来自古法语 registre（13 世纪），并直接来自中世纪拉丁语 registrum、regestrum，本作 regestum，出自晚期拉丁语 regesta“清单、被记录的事项”。非词源的第二个 -r- 是受拉丁语 -istrum 类名词影响而加上的。"},{"era":"LATIN","en":"Regesta is the neuter plural of regestus, past participle of regerere 'to record; retort', literally 'to carry back, bring back', from re- 'back' + gerere 'carry, bear'. The record is what has been carried back.","cn":"regesta 是 regestus 的中性复数，后者是 regerere 的过去分词，意为“记录；反驳”，字面是“带回、携回”，由 re-“回”加 gerere“携带、承载”构成。记录就是被带回来的东西。"},{"era":"FALSE FRIEND","en":"Some later senses seem to have been influenced by association with unrelated Latin regere 'to rule, to guide, to keep straight'. Regere is not the source of register; the two families only resemble each other.","cn":"后来某些义项似乎受到无关的拉丁语 regere“统治、引导、使笔直”的联想影响。regere 并不是 register 的来源；两个词族只是形似。"},{"era":"1680s–1830","en":"The printing sense 'exact alignment of presswork' is from the 1680s. The musical sense 'compass or range of a voice or instrument' is from 1811, hence 'a series of tones of the same quality'. The sense 'device by which data is automatically recorded' is by 1830, from the verb.","cn":"印刷义“印件的精确对齐”始于 17 世纪 80 年代。音乐义“人声或乐器的音域”始于 1811 年，由此引申为“同一音质的一组音”。义项“自动记录数据的装置”到 1830 年已出现，来自动词。"},{"era":"VERB, 14C–1901","en":"The verb registren 'to record, enter in a listing' is late 14c.; 'enroll someone' is c.1400; instruments 'show a reading' 1797; 'enter one's own name' 1848; persons and feelings 'make an impression' by 1901. Registered nurse is attested from 1879.","cn":"动词 registren“记录、列入清单”为 14 世纪晚期；c.1400 起有“使某人登记入册”；仪器“显示读数”始于 1797 年；“写下自己的名字”始于 1848 年；人或情绪“留下印象”到 1901 年已出现。registered nurse（注册护士）见于 1879 年。"}]},"similar":{"note":{"en":"The first group separates register from its derived nouns, each of which names a different part of the act: the process, the office, the official, the person enrolled. The second group compares the verbs of putting something on a list.","cn":"第一组把 register 与它的派生名词分开，每个派生词命名这个行为的不同部分：过程、机构、官员、被登记的人。第二组比较几个“把某物列入名单”的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"registration","ipa":"/ˌrɪdʒɪˈstreɪʃn/","tag":"derived noun: process","definition":"the act or process of registering. It names the procedure, while register is the book or the act itself.","definitionCN":"登记或注册的行为与过程。它命名程序，而 register 是册子或动作本身。"},{"word":"registry","ipa":"/ˈrɪdʒɪstri/","tag":"derived noun: office or list","definition":"an office where records are kept, or a formal list or database. It is the place or the collection, not the single book on the counter.","definitionCN":"保存记录的机构，或正式的名单、数据库。它是场所或集合，而不是柜台上那一本册子。"},{"word":"registrar","ipa":"/ˌredʒɪˈstrɑː/","tag":"derived noun: official","definition":"the official who keeps a register, especially at a university or hospital. It is the person, not the record.","definitionCN":"保管登记册的官员，尤指大学或医院中的注册主任。它是人，而不是记录。"},{"word":"registrant","ipa":"/ˈredʒɪstrənt/","tag":"derived noun: person enrolled","definition":"a person who registers, especially for a course, exam, or event. It is the person on the list, not the person keeping it.","definitionCN":"进行登记的人，尤指报名课程、考试或活动者。它是名单上的人，而不是保管名单的人。"}]},{"heading":"NEAR MEANING","entries":[{"word":"record","ipa":"/ˈrekɔːd/","tag":"store information","definition":"to store information so that it can be found later. It is broader than register: you can record a sound or a fact without entering it in an official list.","definitionCN":"把信息存下来以便日后查找。它比 register 宽：你可以记录一段声音或一个事实，而不必把它写进正式名单。"},{"word":"enroll","ipa":"/ɪnˈrəʊl/","tag":"join a programme","definition":"to join a school, course, or organization by having your name entered on its list. It focuses on becoming a member, while register focuses on the act of writing the name down.","definitionCN":"通过把名字列入名单而加入学校、课程或组织。它强调成为成员，而 register 强调写下名字这个动作。"},{"word":"sign up","ipa":"/ˈsaɪn ʌp/","tag":"informal joining","definition":"to put your name down for something, usually in everyday speech. It is the informal phrasal equivalent of register for a course or event.","definitionCN":"报名参加某事，通常用于日常口语。它是 register 用于课程或活动时的非正式短语对应语。"},{"word":"log","ipa":"/lɒɡ/","tag":"ongoing written record","definition":"to write down events in a regular record as they happen, especially for technical or official purposes. A log is continuous; a register is often a formal list of names or transactions.","definitionCN":"随着事件发生而定期写入记录，尤用于技术或正式目的。日志是连续的；登记册通常是姓名或交易的正式名单。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: Latin re- 'back' + gerere 'carry', the Medieval Latin registrum, and the English family registration, registry, registrar and registrant.","cn":"只用真实成分与真实同族词：拉丁语 re-“回”加 gerere“携带”、中世纪拉丁语 registrum，以及英语词族 registration、registry、registrar、registrant。"},"normal":[{"en":"regerere means 'carry back': an event is carried back into a book so that it can be found again.","cn":"regerere 意为“带回”：一件事被带回册子里，以便日后还能找到。"},{"en":"The second -r- in registrum is unetymological, added by analogy with nouns ending in -istrum. It is not part of the root.","cn":"registrum 里的第二个 -r- 不是词源原有的，而是类比 -istrum 结尾的名词加上去的。它不属于词根。"},{"en":"regere 'rule' is a different verb. It coloured some later senses but did not father the word.","cn":"regere“统治”是另一个动词。它影响了后来某些义项，却不是这个词的来源。"},{"en":"The verb has two everyday branches: write something in (register a deed), and put your own name down (register to vote).","cn":"动词有两个日常分支：把某物写进去（登记契约），以及写下自己的名字（登记投票）。"},{"en":"An instrument registers a reading, and a face registers a feeling: both are dials that move when something arrives.","cn":"仪器 register 一个读数，脸 register 一种情绪：两者都是“有东西到达时表盘就动”的仪器。"}],"abstract":[{"en":"Picture a ledger open on a counter. Every arrival gets one line, and the line stays after the person has gone.","cn":"想象一本摊在柜台上的账簿。每来一个人就添一行，人走了，这一行还留着。"},{"en":"From that book the word spreads in three directions: the machine that writes the lines, the range of notes written on a musical scale, and the slot where a processor keeps one value.","cn":"从这个册子出发，这个词向三个方向扩散：替人写行的机器、写在音阶上的音域，以及处理器保存一个数值的格子。"},{"en":"Register is about entry, not memory: the point is that the name or number has been formally put in, not that someone remembers it.","cn":"register 的关键是“入册”，而不是记忆：重点在于姓名或数字已被正式写进去，而不在于有人记得它。"}]},"examples":[{"en":"All births and deaths are registered at the town hall.","cn":"所有出生与死亡都在市政厅登记。"},{"en":"The university requires new students to register before orientation.","cn":"大学要求新生在迎新之前完成注册。"},{"en":"The gauge registered a sudden drop in pressure.","cn":"压力表显示压力突然下降。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“日记斯特”——日记斯特把每天来往的人和账都记进一本厚册子 → register 登记；登记册（只借音，不表词源）","word":"register"},"root":"源自中世纪拉丁语 registrum，上溯拉丁语 regerere“带回、记录”（re- 回 + gerere 携带），核心是“把发生的事带回册子里写下来”。","sensesIntro":{"en":"Nine senses of register, all from one object: a ruled book in which each name, sale, note, or value gets its own line, and the act of putting that line there.","cn":"register 的九个义项都围绕同一件东西：一本划了格子的册子，每个姓名、每笔交易、每个音符、每个数值都占一行；以及把这一行写进去的动作。"},"semanticMap":{"core":{"en":"CORE IMAGE: a ledger open on a counter, one line added for each entry.","cn":"核心意象：一本摊在柜台上的账簿，每记一项就添一行。"},"chain":["CARRY BACK THE EVENT","WRITE IT IN A BOOK","KEEP IT IN ORDER","A MACHINE THAT WRITES","A RANGE OF ENTRIES","A READING THAT SHOWS"],"branches":[{"senses":"S1","en":"THE BOOK: the original sense is the official volume itself, where names and events are kept in ruled lines.","cn":"册子：最原始的义项就是这本正式簿册，姓名与事件被保存在划好的行里。"},{"senses":"S2 · S5","en":"MACHINES AND SLOTS: the cash register writes the line for us, and the processor register is the smallest ruled slot of all.","cn":"机器与存储槽：收银机替我们写这一行，处理器寄存器则是所有格子里最小的一个。"},{"senses":"S3 · S4","en":"RANGE AND LEVEL: a voice's register is its full list of notes; a language register is the level a situation calls for.","cn":"范围与层次：人声的音域是它全部音符的名单；语域则是场合所要求的语言层次。"},{"senses":"S6 · S7","en":"WRITING NAMES IN: the verb records someone else's entry, or turns reflexive and writes one's own name.","cn":"写入姓名：动词既记录别人的条目，也可转向自身、写下自己的名字。"},{"senses":"S8 · S9","en":"SHOWING: instruments and faces register readings and feelings, as if a dial moved when something arrived.","cn":"显示：仪器与脸分别 register 读数和情绪，仿佛有东西到达时表盘就动了。"}]},"affixes":{"intro":{"en":"Register is a Latin-derived noun whose visible ending is -ister/-istery in its medieval forms, not a living English suffix. English builds registration, registry, registrar and registrant on the finished word, and the root gerere also reaches English through gesture, suggest and digest.","cn":"register 是源自拉丁语的名词，其中世纪形式里看得见的词尾是 -ister／-istery，并非活的英语后缀。英语在成品词上构成 registration、registry、registrar、registrant；词根 gerere 还通过 gesture、suggest、digest 进入英语。"},"latinIntro":{"en":"The Latin source is regerere 'carry back, record' (re- 'back' + gerere 'carry, bear'). Its past participle regestus became regesta 'things recorded', then Medieval Latin registrum. Gerere is a busy verb: it also gives gesture, digest, suggest, congest and register itself.","cn":"拉丁语源头是 regerere“带回、记录”（re-“回”+ gerere“携带、承载”）。其过去分词 regestus 变成 regesta“被记录的事项”，再变成中世纪拉丁语 registrum。gerere 是个繁忙的动词：gesture、digest、suggest、congest 以及 register 本身都出自它。"},"items":[{"word":"register","structure":"re- (back) + gerere (carry), through regestus / registrum","meaning":"a book of carried-back records; to enter in it","meaningCN":"把记录带回的册子；登记入册（re- 回 + gerere 携带，经 regestus／registrum）","example":"The hotel keeps a register of all guests.","exampleCN":"旅馆保存着所有客人的登记册。"},{"word":"registration","structure":"register + -ation (noun of process)","meaning":"the process of registering","meaningCN":"登记；注册（过程）（-ation 构成过程名词）","example":"Registration closes on the first of September.","exampleCN":"注册在九月一日截止。"},{"word":"registry","structure":"register + -y (office or collection)","meaning":"an office or list where records are kept","meaningCN":"登记处；注册表（-y 表示机构或集合）","example":"The land registry holds every title deed.","exampleCN":"土地登记处保存着每一份地契。"},{"word":"registrar","structure":"registr- + -ar (person holding an office)","meaning":"the official who keeps the register","meaningCN":"登记员；注册主任（-ar 表示任职者）","example":"The registrar signed the marriage certificate.","exampleCN":"登记员签署了结婚证书。"},{"word":"registrant","structure":"registr- + -ant (person who does)","meaning":"a person who registers","meaningCN":"登记者；注册人（-ant 表示行为者）","example":"Each registrant receives a badge at the door.","exampleCN":"每位登记者在门口领取一张胸牌。"},{"word":"registered","structure":"register + -ed (past participle as adjective)","meaning":"officially recorded on a list","meaningCN":"已登记的；注册的（-ed 构成形容词）","example":"It is a registered charity.","exampleCN":"这是一个注册慈善机构。"},{"word":"deregister","structure":"de- (remove) + register","meaning":"to remove from an official register","meaningCN":"注销登记；撤销注册（de- 去除 + register）","example":"The company deregistered for tax purposes.","exampleCN":"这家公司为税务目的注销了登记。"},{"word":"gesture","structure":"gest- (gerere, carry/perform) + -ure","meaning":"a movement that expresses meaning","meaningCN":"手势；姿态（gest- 承载、表演 + -ure）","example":"He made a small gesture of welcome.","exampleCN":"他做了一个小小的欢迎手势。"},{"word":"suggest","structure":"sug- (sub-, under) + gerere (carry)","meaning":"to bring an idea under someone's notice","meaningCN":"建议；暗示（sug- 在下 + gerere 携带，即“带到下面给人看”）","example":"Her tone suggested that the plan was already agreed.","exampleCN":"她的语气暗示这个计划已经谈妥。"},{"word":"digest","structure":"di- (dis-, apart) + gerere (carry)","meaning":"to break down and absorb; a summary","meaningCN":"消化；摘要（di- 分开 + gerere 携带，即“分开带走”）","example":"The body digests food slowly at night.","exampleCN":"夜间身体消化食物较慢。"}],"latinEntries":[{"word":"regerere","structure":"re- (back) + gerere (carry)","meaning":"to carry back; to record","meaningCN":"带回；记录"},{"word":"gerere","structure":"Latin verb","meaning":"to carry, bear, perform","meaningCN":"携带；承载；施行"},{"word":"regesta","structure":"neuter plural of regestus, past participle of regerere","meaning":"list, matters recorded","meaningCN":"清单；被记录的事项"}]}},{"word":"regulate","ipa_uk":"/ˈreɡjʊleɪt/","ipa_us":"/ˈreɡjəleɪt/","definition_zh":"管理；监管；控制；调节；校准；使保持规律","definition_en":"to control an activity or process by rules, or to adjust something so that it stays at a desired level","core_image":"一把直尺压在一排歪斜的器物上，把它们一件件推回同一条直线","scene":"A thermostat regulates the temperature of the greenhouse all winter.","sceneCN":"这里 regulate 是「自动调节」（第 4 个义项：恒温器把温度稳定在设定值）；句意：整个冬天，恒温器把温室的温度调节在设定值。场景要点：温室墙上的恒温器、红色指针、玻璃上的霜、沿墙延伸的暖气管。","pos":[{"tag":"vt.","zh":"管理；监管；控制；调节；校准"}],"collocations":[{"phrase":"regulate the market","zh":"监管市场"},{"phrase":"regulate temperature","zh":"调节温度"},{"phrase":"regulate speed","zh":"控制速度"},{"phrase":"regulate one's emotions","zh":"调节情绪"},{"phrase":"strictly regulated","zh":"受严格监管的"},{"phrase":"regulate the flow of water","zh":"调节水流"},{"phrase":"regulate a clock","zh":"校准时钟"}],"forms":[{"label":"三单（he/she/it）","form":"regulates"},{"label":"过去式（已经发生）","form":"regulated"},{"label":"过去分词（完成／被动）","form":"regulated"},{"label":"现在分词（进行体）","form":"regulating"}],"derivatives":[{"word":"regulation","pos":"n.","zh":"规章；条例；管理；调节"},{"word":"regulator","pos":"n.","zh":"监管机构；调节器；监管者"},{"word":"regulatory","pos":"adj.","zh":"监管的；规章性的"},{"word":"deregulate","pos":"v.","zh":"放松管制；解除监管"},{"word":"regulated","pos":"adj.","zh":"受监管的；已调节的"}],"senses":[{"no":"01","title":"The state makes rules for an industry","titleCN":"国家为某个行业制定规则","definition":"to control an industry or activity by official rules and laws","definitionCN":"以正式规则和法律控制某个行业或活动","example":"The agency regulates the safety of new medicines.","exampleCN":"该机构监管新药的安全性。","why":"Latin regula was a straight piece of wood used as a rule. To regulate is to lay that ruler against an activity and force it into line, which is the image behind official control.","whyCN":"拉丁语 regula 是一根用来量直的木条，也就是尺子。regulate 就是把这把尺子压在某个活动上、把它推回直线，这正是官方管控背后的意象。"},{"no":"02","title":"A city puts a ceiling on rent","titleCN":"城市给租金设上限","definition":"to set official limits on prices, rents, or charges","definitionCN":"对价格、租金或收费设定官方上限","example":"The city regulated rents during the housing crisis.","exampleCN":"住房危机期间，这座城市对租金实行管制。","why":"A price can be kept inside a band the way a plank is kept against a ruler. When the tool is a legal limit rather than a thermostat, regulating becomes restriction.","whyCN":"价格可以像木板贴着尺子那样被限制在某个区间内。当工具是法律上限而不是恒温器时，regulate 就变成了限制。"},{"no":"03","title":"An authority limits hunting or fishing","titleCN":"当局限制捕猎或捕鱼","definition":"to control how much of a natural resource may be taken, usually to protect it","definitionCN":"控制某种自然资源可被取用的数量，通常是为了保护它","example":"The river is regulated to protect the salmon run.","exampleCN":"这条河受到管理，以保护鲑鱼的洄游。","why":"Here the ruler is applied to a natural process: take no more than this line, so that the run continues next year.","whyCN":"这里尺子被压在自然过程上：取用不得超过这条线，好让来年仍有鱼群洄游。"},{"no":"04","title":"A thermostat holds a temperature steady","titleCN":"恒温器把温度稳住","definition":"to keep a physical condition such as temperature or pressure at a chosen level automatically","definitionCN":"自动把温度、压力等物理状况维持在选定水平","example":"The thermostat regulates the heat to within one degree.","exampleCN":"恒温器把热量控制在误差一度之内。","why":"The ruler now works by feedback: a sensor reads the value, and the device pushes it back whenever it drifts off the line.","whyCN":"这把尺子现在靠反馈工作：传感器读出数值，一旦偏离直线，装置就把它推回去。"},{"no":"05","title":"Set a clock to the standard","titleCN":"把钟校准到标准","definition":"to adjust an instrument such as a clock so that it agrees with an accepted standard","definitionCN":"调整钟表等仪器，使其与公认标准一致","example":"The engineer regulated the clock against the radio signal.","exampleCN":"工程师依据无线电信号校准了那只钟。","why":"The oldest mechanical use is exactly this: hold the instrument against a standard and move it until the two coincide. The clock is brought onto the ruler.","whyCN":"最早的机械用法正是这个：把仪器贴住标准，移动它直到两者重合。钟被拉到了尺子上。"},{"no":"06","title":"A governor keeps an engine at one speed","titleCN":"调速器让发动机保持同一转速","definition":"to hold a machine at a constant speed or output by means of a controlling device","definitionCN":"借助控制装置使机器保持恒定转速或输出","example":"A governor regulates the engine so it does not overrun.","exampleCN":"调速器调节发动机，使它不会超速运转。","why":"The device called a regulator was applied to machinery from 1702. It acts like a hand on the ruler, pulling the engine back whenever speed rises past the mark.","whyCN":"名为 regulator 的装置从 1702 年起用于机械。它像一只按在尺子上的手，转速一旦越过刻度就把发动机拉回来。"},{"no":"07","title":"Keep traffic or water flowing evenly","titleCN":"让车流或水流均匀通过","definition":"to control the pace or flow of moving things so that it stays even","definitionCN":"控制移动事物的速度或流量，使其保持均匀","example":"Traffic lights regulate the flow of cars into the tunnel.","exampleCN":"红绿灯调节进入隧道的车流。","why":"Flow is a line of moving units. Regulating it means spacing them along that line instead of letting them bunch and stop.","whyCN":"流动是一串移动的单位。调节它，就是让它们沿这条线均匀分布，而不是挤成一团、走走停停。"},{"no":"08","title":"The body balances its own functions","titleCN":"身体平衡自身的机能","definition":"of a living body, to keep a function such as temperature, heart rate, or blood sugar within a safe range","definitionCN":"指生命体把体温、心率或血糖等机能维持在安全范围内","example":"The body regulates its temperature by sweating and shivering.","exampleCN":"身体通过出汗和发抖来调节体温。","why":"The ruler is now inside the organism. Feedback loops do the work, and the word describes a natural control system rather than an outside authority.","whyCN":"这把尺子现在长在生物体内部。反馈回路承担了这项工作，词所描述的是自然控制系统，而不是外部权威。"},{"no":"09","title":"A person keeps emotions in check","titleCN":"人把自己的情绪收住","definition":"to control one's own emotions, habits, or behaviour so that they stay within acceptable limits","definitionCN":"控制自己的情绪、习惯或行为，使其保持在可接受的限度内","example":"He learned to regulate his anger before speaking.","exampleCN":"他学会了在开口之前先压住怒气。","why":"When the authority and the subject are the same person, regulating becomes self-control: one part of the self holds the other to the line.","whyCN":"当权威与对象是同一个人时，regulate 就成了自我控制：自我的一部分把另一部分按在直线上。"}],"etymology":{"intro":{"en":"Regulate is a fifteenth-century borrowing from Late Latin regulare, built on regula 'rule, straight piece of wood'. The same root gives rule, regular, regime and correct. Dates follow standard etymological references.","cn":"regulate 是 15 世纪从晚期拉丁语 regulare 借来的词，词基是 regula“规则、直木条”。同一词根还给出 rule、regular、regime、correct。年代依据通行词源资料。"},"items":[{"era":"EARLY 15C.","en":"First recorded as regulaten, 'adjust by rule, method, or control', from Late Latin regulatus, past participle of regulare.","cn":"最早记录为 regulaten，意为“按规则、方法或控制来调整”，来自晚期拉丁语 regulatus，即 regulare 的过去分词。"},{"era":"LATE LATIN","en":"Regulare meant 'to control by rule, direct', from Latin regula 'rule, straight piece of wood'. A regula was first a measuring rod, then a rule of conduct.","cn":"regulare 意为“按规则控制、引导”，来自拉丁语 regula“规则、直木条”。regula 先是一根量尺，后来才成为行为规则。"},{"era":"LATIN / PIE","en":"Regula goes back to PIE *reg- 'move in a straight line', with derivatives meaning 'to direct in a straight line', hence 'to lead, rule'. Latin regere 'to rule, guide' belongs to the same root.","cn":"regula 可追溯到原始印欧语 *reg-“沿直线移动”，其派生义为“使沿直线引导”，由此引申为“引导、统治”。拉丁语 regere“统治、引导”属于同一词根。"},{"era":"1620s","en":"The sense 'to govern by restriction' is recorded from the 1620s. This is the branch that leads to government regulation of industries and prices.","cn":"“以限制来治理”的义项记录于 17 世纪 20 年代。正是这一支引出了政府对行业与价格的监管。"},{"era":"1660s","en":"The sense 'to adjust a clock or instrument with reference to a standard of accuracy' is recorded by the 1660s. Here the ruler is a standard of measurement, not a law.","cn":"“依据精确度标准来调整钟表或仪器”的义项到 17 世纪 60 年代已有记录。这里的尺子是测量标准，而不是法律。"},{"era":"MODERN ENGLISH","en":"Regulation is from the 1670s, regulator from the 1650s and as a machine part from 1702; deregulate is from 1950. The two branches, rule-making and level-holding, both remain central.","cn":"regulation 始于 17 世纪 70 年代，regulator 始于 17 世纪 50 年代、1702 年起指机械部件；deregulate 始于 1950 年。制定规则与维持水平这两支至今都是核心。"}]},"similar":{"note":{"en":"The first group separates regulate from its derived words: the body of rules, the agency or device, the adjective, and the opposite verb. The second group compares four verbs of control that are often used as if they were the same.","cn":"第一组把 regulate 与派生词分开：规则体系、机构或装置、形容词，以及反义动词。第二组比较四个常被当成同义词的“控制”动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"regulation","ipa":"/ˌreɡjuˈleɪʃn/","tag":"derived noun: rule or process","definition":"an official rule, or the act of regulating. It can name either the piece of paper or the work, while regulate names the action.","definitionCN":"官方的规章，或调节的行为。它既可指那张纸，也可指这项工作，而 regulate 命名动作本身。"},{"word":"regulator","ipa":"/ˈreɡjuleɪtə/","tag":"derived noun: agency or device","definition":"an official body that supervises an industry, or a device that holds a machine at a set level. It is the doer, human or mechanical.","definitionCN":"监督某个行业的官方机构，或把机器稳定在设定值的装置。它是行为者，人或机械皆可。"},{"word":"regulatory","ipa":"/ˌreɡjuˈleɪtəri/","tag":"derived adjective","definition":"relating to rules and the bodies that enforce them. It describes the system, while regulate describes what the system does.","definitionCN":"与规章及执行规章的机构有关的。它描述制度，而 regulate 描述制度所做的事。"},{"word":"deregulate","ipa":"/ˌdiːˈreɡjuleɪt/","tag":"opposite verb","definition":"to remove official rules from an industry. It is the reverse action, not a milder kind of regulating.","definitionCN":"解除对某个行业的官方管制。它是反向动作，而不是程度更轻的 regulate。"}]},{"heading":"NEAR MEANING","entries":[{"word":"control","ipa":"/kənˈtrəʊl/","tag":"hold power over","definition":"to have power over something and make it do what you want. It is wider than regulate: control can be exercised without any rule or standard.","definitionCN":"对某物拥有权力并使其按自己的意愿行事。它比 regulate 宽：控制可以在没有任何规则或标准的情况下施行。"},{"word":"manage","ipa":"/ˈmænɪdʒ/","tag":"run with responsibility","definition":"to be in charge of people, money, or a situation and make it work. It stresses responsibility and organisation, while regulate stresses keeping something on a line.","definitionCN":"负责管理人员、资金或局面并使其运转。它强调责任与组织，而 regulate 强调让某物保持在一条线上。"},{"word":"adjust","ipa":"/əˈdʒʌst/","tag":"small change","definition":"to change something slightly so that it fits better. It does not require a rule or a continuing standard; regulate usually implies a level that must be maintained.","definitionCN":"小幅改变某物，使其更合适。它不需要规则或持续的标准；regulate 通常隐含一个必须维持的水平。"},{"word":"calibrate","ipa":"/ˈkælɪbreɪt/","tag":"set against a standard","definition":"to mark or adjust an instrument by comparing it with a known standard. It is the precise technical part of regulating a measuring device.","definitionCN":"通过与已知标准比对来标记或调整仪器。它是“调节测量仪器”这一动作里精确的技术部分。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: Latin regula 'straight rod, rule', regulare 'direct by rule', the root *reg-, and the English family regulation, regulator, regulatory, rule and regular.","cn":"只用真实成分与真实同族词：拉丁语 regula“直木条、规则”、regulare“按规则引导”、词根 *reg-，以及英语词族 regulation、regulator、regulatory、rule、regular。"},"normal":[{"en":"A regula was a straight rod used to check whether a line was true. Regulating is holding things against that rod.","cn":"regula 是一根用来检查线条是否笔直的直木条。regulate 就是拿事物贴着这根木条。"},{"en":"The root *reg- means 'move in a straight line', which also gives regere 'rule' and English rule, regular, regime and correct.","cn":"词根 *reg- 意为“沿直线移动”，它还给出 regere“统治”，以及英语的 rule、regular、regime、correct。"},{"en":"The two modern branches are law and level: regulate an industry by rules, regulate a room by thermostat.","cn":"现代的两支是“法律”与“水平”：用规则监管一个行业，用恒温器调节一个房间。"},{"en":"Regulation is the rule or the process; regulator is the agency or the device; regulatory is the adjective.","cn":"regulation 是规章或过程；regulator 是机构或装置；regulatory 是形容词。"},{"en":"Deregulate is not 'regulate less': it means removing the rules altogether.","cn":"deregulate 不是“少管一点”，而是把规则整体撤掉。"}],"abstract":[{"en":"Picture a carpenter's straightedge laid across a row of crooked boards; each board is pushed until its edge touches the rod.","cn":"想象一把木匠的直尺横在一排歪斜的木板上；每块板都被推到边缘贴住直尺。"},{"en":"Sometimes the rod is a law, sometimes a thermostat's set point, sometimes the body's own feedback loop. The gesture is always the same.","cn":"这根直尺有时是法律，有时是恒温器的设定点，有时是身体自身的反馈回路。动作始终一样。"},{"en":"Regulate always implies a line that already exists; without a rule or a standard, there is nothing to regulate towards.","cn":"regulate 始终隐含一条已经存在的线；没有规则或标准，就没有可调节的方向。"}]},"examples":[{"en":"The agency regulates the safety of new medicines.","cn":"该机构监管新药的安全性。"},{"en":"The valve regulates the flow of steam into the turbine.","cn":"阀门调节进入涡轮机的蒸汽流量。"},{"en":"She regulates her screen time with a timer.","cn":"她用计时器控制自己看屏幕的时间。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“热规莱特”——热规莱特给锅炉定好规矩，温度一高就调低、一低就调高 → regulate 调节；监管（只借音，不表词源）","word":"regulate"},"root":"源自晚期拉丁语 regulare“按规则引导”，词根 regula“尺子、规则”，再上溯 regere“引导、统治”，核心是“拿一把直尺把事物量回正轨”。","sensesIntro":{"en":"Nine senses of regulate, all from one gesture: a straightedge is laid against something, and whatever is crooked or drifting is pushed back onto the line.","cn":"regulate 的九个义项都出自同一个动作：把一把直尺贴在某物上，凡是歪斜或漂移的部分，都被推回这条线。"},"semanticMap":{"core":{"en":"CORE IMAGE: a straightedge laid against crooked things, pushing them back into line.","cn":"核心意象：一把直尺贴在歪斜的事物上，把它们推回直线。"},"chain":["A STRAIGHT ROD","A LINE TO FOLLOW","RULES FOR PEOPLE","LIMITS ON PRICES","A LEVEL TO HOLD","A SYSTEM THAT CORRECTS ITSELF"],"branches":[{"senses":"S1 · S2 · S3","en":"RULE BY AUTHORITY: laws, price ceilings and resource limits all lay the public ruler against private activity.","cn":"依法管控：法律、价格上限与资源限额，都是把公共的尺子压在私人活动上。"},{"senses":"S4 · S6","en":"AUTOMATIC CONTROL: a thermostat or a governor reads the level and pulls it back whenever it passes the mark.","cn":"自动控制：恒温器或调速器读出水平，一旦越过刻度就把它拉回来。"},{"senses":"S5","en":"CALIBRATION: a clock is brought onto the standard until the two coincide exactly.","cn":"校准：把钟拉到标准上，直到两者完全重合。"},{"senses":"S7","en":"FLOW: cars and water are spaced evenly along a line instead of allowed to bunch and stop.","cn":"流动：车辆与水流被沿一条线均匀排开，而不是挤成一团、走走停停。"},{"senses":"S8 · S9","en":"SELF-REGULATION: the ruler moves inside the body or the person, where feedback and self-control hold the line.","cn":"自我调节：尺子移进了身体或人内部，由反馈与自控守住这条线。"}]},"affixes":{"intro":{"en":"Regulate is regul- (regula, rule) plus the verb ending -ate. English adds -ion, -or, -ory and the reversing prefix de-. The same root reaches English in rule, regular, regime, correct and direct.","cn":"regulate 由 regul-（regula，规则）加动词词尾 -ate 构成。英语再加上 -ion、-or、-ory 以及表示反转的 de-。同一词根还通过 rule、regular、regime、correct、direct 进入英语。"},"latinIntro":{"en":"Regula 'rule, straight piece of wood' and regulare 'to direct by rule' are ordinary Latin words. Behind them stands regere 'to rule, guide, keep straight', from PIE *reg- 'move in a straight line'. The rod, the rule and the act of ruling are one family.","cn":"regula“规则、直木条”与 regulare“按规则引导”都是普通拉丁词。它们背后是 regere“统治、引导、使笔直”，出自原始印欧语 *reg-“沿直线移动”。直木条、规则与统治行为同属一个词族。"},"items":[{"word":"regulate","structure":"regul- (regula, rule) + -ate (verb)","meaning":"to control or adjust by a rule or standard","meaningCN":"按规则或标准管理、调节（-ate 构成动词）","example":"New laws regulate the disposal of chemical waste.","exampleCN":"新法律对化学废料的处置作出规定。"},{"word":"regulation","structure":"regulate + -ion (noun of action)","meaning":"the act of regulating; an official rule","meaningCN":"调节；管理；规章（-ion 构成行为名词）","example":"Safety regulations changed after the accident.","exampleCN":"事故之后，安全规章发生了改变。"},{"word":"regulator","structure":"regulate + -or (agent noun)","meaning":"one who regulates; a controlling device","meaningCN":"监管者；监管机构；调节器（-or 表示行为者）","example":"The regulator fined the company for unsafe tanks.","exampleCN":"监管机构因储罐不安全而对这家公司罚款。"},{"word":"regulatory","structure":"regulat- + -ory (adjective)","meaning":"relating to regulation","meaningCN":"监管的；规章性的（-ory 构成形容词）","example":"The project was delayed by regulatory checks.","exampleCN":"这个项目因监管审查而延误。"},{"word":"deregulate","structure":"de- (remove) + regulate","meaning":"to remove rules from an industry","meaningCN":"放松管制；解除监管（de- 去除 + regulate）","example":"The government deregulated the airline market.","exampleCN":"政府放松了对航空市场的管制。"},{"word":"regulated","structure":"regulate + -ed (past participle as adjective)","meaning":"controlled by rules or adjusted to a level","meaningCN":"受监管的；已调节的（-ed 构成形容词）","example":"The clinic is a regulated medical facility.","exampleCN":"这家诊所是受监管的医疗机构。"},{"word":"rule","structure":"Old French riule, from Latin regula","meaning":"a principle governing conduct; to govern","meaningCN":"规则；统治（古法语 riule，出自拉丁语 regula）","example":"The first rule is to check the source.","exampleCN":"第一条规则是核对来源。"},{"word":"regular","structure":"regul- (regula) + -ar (adjective)","meaning":"following a fixed pattern; occurring at even intervals","meaningCN":"规则的；定期的（regula + -ar 形容词）","example":"The heart beat in a regular rhythm.","exampleCN":"心脏以规则的节律跳动。"},{"word":"regime","structure":"Latin regimen, from regere (to rule)","meaning":"a system of government or a set routine","meaningCN":"政权；制度；固定 regimen（来自 regere 统治）","example":"The diet regime lasted six weeks.","exampleCN":"这套饮食方案持续了六周。"},{"word":"correct","structure":"cor- (com-, together) + regere (make straight)","meaning":"to make right; accurate","meaningCN":"改正；正确的（cor- 一起 + regere 使笔直）","example":"Please correct the date on the form.","exampleCN":"请改正表格上的日期。"},{"word":"direct","structure":"di- (dis-, apart) + regere (guide straight)","meaning":"to guide or manage; straight","meaningCN":"指导；管理；直接的（di- 分开 + regere 引直）","example":"She directed the traffic around the accident.","exampleCN":"她引导车辆绕开事故现场。"}],"latinEntries":[{"word":"regula","structure":"Latin noun, from PIE *reg-","meaning":"rule, straight piece of wood","meaningCN":"规则；直木条"},{"word":"regulare","structure":"regula + -are (verb)","meaning":"to control by rule, direct","meaningCN":"按规则控制；引导"},{"word":"regere","structure":"Latin verb, from PIE *reg- 'move in a straight line'","meaning":"to rule, guide, keep straight","meaningCN":"统治；引导；使笔直"}]}},{"word":"reinforce","ipa_uk":"/rɪnˈfɔːs/","ipa_us":"/rɪnˈfɔːrs/","definition_zh":"加强；加固；增援；强化（观念、行为）；使（论点、信息）更有力","definition_en":"to make something stronger by adding more force, material, people, or evidence","core_image":"一段快撑不住的墙，外面又浇上一层混凝土、钉上一排钢板","scene":"Workers reinforced the bridge with steel plates before the storm.","sceneCN":"这里 reinforce 是「加固（结构）」（第 2 个义项：用额外支撑让建筑更结实）；句意：暴风雨来临前，工人们用钢板加固了那座桥。场景要点：桥墩、铆钉、吊起的钢板、河面上压过来的风。","pos":[{"tag":"vt.","zh":"加强；加固；增援；强化"}],"collocations":[{"phrase":"reinforce a bridge","zh":"加固桥梁"},{"phrase":"reinforce troops","zh":"增援部队"},{"phrase":"reinforce an argument","zh":"加强论点"},{"phrase":"reinforce a belief","zh":"强化某种信念"},{"phrase":"reinforced concrete","zh":"钢筋混凝土"},{"phrase":"reinforce a message","zh":"反复强调某个信息"},{"phrase":"reinforce positive behaviour","zh":"强化积极行为"}],"forms":[{"label":"三单（he/she/it）","form":"reinforces"},{"label":"过去式（已经发生）","form":"reinforced"},{"label":"过去分词（完成／被动）","form":"reinforced"},{"label":"现在分词（进行体）","form":"reinforcing"}],"derivatives":[{"word":"reinforcement","pos":"n.","zh":"加固；增援；强化；强化措施"},{"word":"reinforced","pos":"adj.","zh":"加固的；加筋的"},{"word":"reinforcing","pos":"adj.","zh":"加固的；起强化作用的"},{"word":"reinforcer","pos":"n.","zh":"强化物；强化因素"},{"word":"re-enforce","pos":"v.","zh":"再次执行（法律、规定）"}],"senses":[{"no":"01","title":"Send more soldiers to a force","titleCN":"向一支部队增派兵力","definition":"to add more soldiers or equipment to a military force so that it becomes stronger","definitionCN":"向一支军事力量增加士兵或装备，使其更为强大","example":"The general reinforced the front line with two battalions.","exampleCN":"将军用两个营增援前线。","why":"The word entered English around 1600 in a military sense: 'add new force, strength, or weight to'. The original picture is more men arriving where the line is thin.","whyCN":"这个词约在 1600 年以军事义进入英语，意为“增加新的力量、强度或分量”。最初的画面是：防线单薄处又赶来了一批人。"},{"no":"02","title":"Add support to a structure","titleCN":"给建筑物加支撑","definition":"to strengthen a building, bridge, or other structure by adding material or support","definitionCN":"通过添加材料或支撑来加强建筑、桥梁或其他结构","example":"Workers reinforced the bridge with steel plates.","exampleCN":"工人们用钢板加固了那座桥。","why":"The military idea of adding weight to a weak point transfers easily to stone and steel: extra material is placed where the structure carries the most load.","whyCN":"“在薄弱处增加分量”这个军事观念很容易转到石头和钢铁上：把额外材料放在结构承重最大的地方。"},{"no":"03","title":"Back an argument with evidence","titleCN":"用证据支撑论点","definition":"to make an argument or case stronger by adding further evidence or reasons","definitionCN":"通过补充证据或理由使论点或主张更有力","example":"The new data reinforced her claim that the drug was safe.","exampleCN":"新数据进一步支持了她关于这种药安全的说法。","why":"An argument is a line that can be pushed. Adding evidence is adding weight at the weak point, exactly as troops or steel are added.","whyCN":"论点是一条可以被推的线。补充证据，就是在薄弱处增加分量，和增兵、加钢板完全一样。"},{"no":"04","title":"Make a belief or feeling stronger","titleCN":"让某种信念或情绪更强","definition":"to make a belief, fear, or prejudice stronger, often without intending to","definitionCN":"使信念、恐惧或偏见变得更强，往往并非有意为之","example":"The incident reinforced fears that the dam was unsafe.","exampleCN":"这起事件加重了人们对大坝不安全的担忧。","why":"Beliefs hold a shape in the mind. Each confirming event adds another layer to that shape, so reinforcement can happen by accident.","whyCN":"信念在头脑里有一个形状。每一个印证的事件都给这个形状再加一层，因此强化可以在无意中发生。"},{"no":"05","title":"Give a person or team more support","titleCN":"给某个人或团队更多支持","definition":"to give additional help, confidence, or resources to a person or group","definitionCN":"向某个人或群体提供额外的帮助、信心或资源","example":"The coach reinforced the young players with extra training and praise.","exampleCN":"教练用额外的训练和表扬给年轻球员撑腰。","why":"The added force is no longer physical: it is help and confidence placed where someone is struggling, the same gesture applied to people.","whyCN":"增加的力量不再是物理性的：而是在某人吃力之处放上帮助与信心，同一个动作被用在了人身上。"},{"no":"06","title":"Put steel into concrete","titleCN":"把钢筋放进混凝土","definition":"to add bars, fibres, or other strong material inside a material so that it can bear more stress","definitionCN":"在某种材料内部加入钢筋、纤维等坚固材料，使其能承受更大应力","example":"The columns are made of reinforced concrete.","exampleCN":"这些柱子由钢筋混凝土制成。","why":"Concrete is strong in compression but weak in tension; steel bars are inserted exactly where it would crack, so the added force works from inside.","whyCN":"混凝土抗压却不抗拉；钢筋被放进最容易开裂的位置，因此增加的力量是从内部起作用的。"},{"no":"07","title":"Reward a behaviour so it repeats","titleCN":"用奖励让一种行为重复","definition":"in psychology, to strengthen a behaviour by giving a reward or removing a punishment","definitionCN":"在心理学中，通过给予奖励或撤除惩罚来强化某种行为","example":"Praise reinforces the habit of speaking up in class.","exampleCN":"表扬会强化在课堂上举手发言的习惯。","why":"A behaviour is a response that either continues or dies out. A reward adds weight to it, so the next occurrence becomes more likely.","whyCN":"行为是一种要么继续、要么消失的反应。奖励给它增加分量，于是下一次发生就更有可能。"},{"no":"08","title":"Repeat a message so it sticks","titleCN":"反复讲同一个信息","definition":"to repeat a message or point so that it becomes clearer or harder to forget","definitionCN":"反复讲述某个信息或要点，使其更清楚、更难被忘记","example":"The campaign reinforced its message with posters on every corner.","exampleCN":"这场宣传活动在每一个街角贴上海报，反复强化它的信息。","why":"A message that is heard once is a thin line. Repetition lays another layer on it each time, until the line holds.","whyCN":"只听过一次的信息是一条细线。重复每讲一遍就再加一层，直到这条线立住。"},{"no":"09","title":"Make a defensive line harder to break","titleCN":"让防线更难被突破","definition":"to make a defensive position or barrier stronger against attack","definitionCN":"使防御阵地或屏障更坚固、更难被攻破","example":"Troops reinforced the wall before the enemy reached the gate.","exampleCN":"敌军到达城门之前，部队加固了城墙。","why":"This is the military sense tightened to its most concrete point: the wall itself is thickened, so the defence can absorb more before it gives way.","whyCN":"这是军事义收紧到最具体的程度：墙本身被加厚，因此防御能在垮掉之前承受更多。"}],"etymology":{"intro":{"en":"Reinforce is not re- plus force as a literal sum. It is re- 'again' plus inforce, a variant of enforce, and enforce itself is en- 'make, put in' plus force, from Latin fortis 'strong'. The chain is re- + enforce < Old French enforcir < en- + force < Latin fortis. Dates follow standard etymological references.","cn":"reinforce 不是 re- 与 force 的字面相加。它是 re-“再次”加 inforce，即 enforce 的变体；而 enforce 本身是 en-“使、放入”加 force，force 上溯拉丁语 fortis“强壮”。完整链条是 re- + enforce < 古法语 enforcir < en- + force < 拉丁语 fortis。年代依据通行词源资料。"},"items":[{"era":"c.1600","en":"Reinforce, also spelt re-enforce, is recorded meaning 'add new force, strength, or weight to', originally in a military sense. It is re- 'again' + inforce, a variant of enforce.","cn":"reinforce 也拼作 re-enforce，约 1600 年记录为“增加新的力量、强度或分量”，最初用于军事。它由 re-“再次”加 inforce（enforce 的变体）构成。"},{"era":"1580s","en":"The parallel form re-enforce is recorded earlier, in the 1580s, meaning 'to give fresh strength to'. It was first used of persons or military units; of buildings and structures from 1883.","cn":"平行形式 re-enforce 更早，1580 年代即记录为“给予新的力量”。它最初用于人或军事单位；1883 年起用于建筑物与结构。"},{"era":"MID-14C.","en":"Enforce, earlier enforcen, meant 'to drive by physical force; try, attempt, strive; to fortify, strengthen a place'. It came from Old French enforcier 'strengthen, reinforce; use force on' (12c.) or was formed natively from en- 'make, put in' + force.","cn":"enforce 早作 enforcen，意为“以物理力量驱动；尝试、努力；设防、加强某地”。它来自古法语 enforcier“加强、增援；对……使用武力”（12 世纪），或由本地的 en-“使、放入”加 force 构成。"},{"era":"OLD FRENCH / LATIN","en":"Force came into English through Old French force, from Vulgar Latin fortia, from Latin fortis 'strong'. So the force inside reinforce is not a free-standing English word added to re-, but the tail of the borrowed verb enforce.","cn":"force 经古法语 force 进入英语，来自通俗拉丁语 fortia，再上溯拉丁语 fortis“强壮”。因此 reinforce 里的 force 并不是一个独立英语词加到 re- 上，而是借来的动词 enforce 的尾巴。"},{"era":"FOWLER'S NOTE","en":"Fowler observed that the ordinary form rein- has become so divorced from the simple verb that it seldom or never means 'to enforce again'. For that sense, re-enforce should be used. This is why reinforce and re-enforce are not freely interchangeable.","cn":"福勒指出，常见的 rein- 形式已经与那个简单动词脱离得太远，以至于它很少甚至从不表示“再次执行”。若要表达这个意思，应使用 re-enforce。这就是 reinforce 与 re-enforce 不能随意互换的原因。"},{"era":"1883–MODERN","en":"The sense 'strengthen a building or structure by additional support' is recorded from 1883, whence reinforced concrete and reinforcement. Modern psychology adds 'strengthen a behaviour by reward', and everyday usage adds 'strengthen a belief, argument, or message'.","cn":"“通过额外支撑加固建筑或结构”的义项记录于 1883 年，由此产生 reinforced concrete 与 reinforcement。现代心理学加上“用奖励强化行为”，日常用法又加上“强化信念、论点或信息”。"}]},"similar":{"note":{"en":"The first group separates reinforce from its own forms and from the spelling that means 'enforce again'. The second group compares it with four verbs of strengthening, including enforce, which sits inside its own history.","cn":"第一组把 reinforce 与它自己的词形分开，并区分那个表示“再次执行”的拼写；第二组把它与四个“加强”动词比较，其中包括 enforce——它本来就在 reinforce 的词源里。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"reinforcement","ipa":"/rɪnˈfɔːsmənt/","tag":"derived noun","definition":"the act of reinforcing, or the extra material, troops, or reward that strengthens something. It names the addition, while reinforce names the act.","definitionCN":"加固的行为，或用来加强某物的额外材料、兵力、奖励。它命名所加的东西，而 reinforce 命名动作。"},{"word":"reinforced","ipa":"/rɪnˈfɔːst/","tag":"past participle as adjective","definition":"strengthened by added material, as in reinforced concrete. It describes the result, not the process.","definitionCN":"通过添加材料而被加强的，如钢筋混凝土。它描述结果，而不是过程。"},{"word":"reinforcer","ipa":"/rɪnˈfɔːsə/","tag":"derived noun: psychology","definition":"a stimulus or reward that strengthens a behaviour. It is the thing doing the reinforcing, not the behaviour itself.","definitionCN":"强化某种行为的刺激或奖励。它是起强化作用的东西，而不是行为本身。"},{"word":"re-enforce","ipa":"/ˌriːɪnˈfɔːs/","tag":"hyphenated variant","definition":"to enforce again, as when a lapsed rule is revived. It is the literal re- + enforce; the unhyphenated reinforce does not normally carry this sense.","definitionCN":"再次执行，如恢复一条失效的规定。它是字面的 re- + enforce；不带连字符的 reinforce 通常不表示这个意思。"}]},{"heading":"NEAR MEANING","entries":[{"word":"enforce","ipa":"/ɪnˈfɔːs/","tag":"make a rule obeyed","definition":"to make people obey a law or rule, or to give something force. It is the verb inside reinforce, but its modern meaning is about compulsion, not added strength.","definitionCN":"使人们遵守法律或规则，或赋予某物效力。它是 reinforce 词源里的那个动词，但现代义讲的是强制，而不是增加强度。"},{"word":"strengthen","ipa":"/ˈstreŋθn/","tag":"general increase in strength","definition":"to make something stronger in any way. It is the broad word; reinforce usually implies adding something extra at a weak point.","definitionCN":"以任何方式使某物更强。它是最宽泛的词；reinforce 通常指在薄弱处额外添加东西。"},{"word":"support","ipa":"/səˈpɔːt/","tag":"hold up","definition":"to bear the weight of something or give help to someone. It can be passive holding, while reinforce is an active addition of strength.","definitionCN":"承托某物的重量，或给予某人帮助。它可以是消极的承托，而 reinforce 是主动地增加强度。"},{"word":"fortify","ipa":"/ˈfɔːtɪfaɪ/","tag":"build defences","definition":"to build walls or defences around a place, or to make someone stronger in body or spirit. It shares the Latin fortis root and often refers to deliberate defensive construction.","definitionCN":"在某个地方筑墙设防，或使人的身体、精神更强。它与 reinforce 共享拉丁语 fortis 词根，常指有意的防御工事。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: re- 'again' + enforce, enforce = en- 'make' + force < Latin fortis 'strong', plus reinforcement, reinforcer and the Latin family fort, fortify, effort and comfort.","cn":"只用真实成分与真实同族词：re-“再次”+ enforce，而 enforce = en-“使”+ force < 拉丁语 fortis“强壮”，再加上 reinforcement、reinforcer，以及拉丁词族 fort、fortify、effort、comfort。"},"normal":[{"en":"The chain is re- + enforce, not re- + force: enforce was borrowed whole, and only then did re- attach to it.","cn":"链条是 re- + enforce，而不是 re- + force：enforce 是整体借来的，之后 re- 才加到它上面。"},{"en":"Enforce is en- 'make, put in' + force; force goes back through Old French to Latin fortis 'strong'. Fort, fortify and fortitude share that root.","cn":"enforce 是 en-“使、放入”+ force；force 经古法语上溯拉丁语 fortis“强壮”。fort、fortify、fortitude 共享这个词根。"},{"en":"The original 1600 sense was military: send more men and material to the point that is about to break.","cn":"1600 年前后的原义是军事性的：把更多人和物资送到快要撑不住的那一点。"},{"en":"Reinforced concrete works because steel is placed where concrete would crack; the strengthening comes from inside.","cn":"钢筋混凝土之所以有效，是因为钢筋被放在混凝土会开裂的位置；加强来自内部。"},{"en":"In psychology a reinforcer is a reward that makes a behaviour more likely to happen again.","cn":"在心理学里，reinforcer 是让某种行为更可能再次发生的奖励。"}],"abstract":[{"en":"Picture a wall with a crack. Instead of replacing it, workers pour another layer on the cracked side and pin it with steel.","cn":"想象一堵有裂缝的墙。工人不拆掉它，而是在开裂的一侧再浇一层，并用钢钉固定。"},{"en":"The same gesture works for an argument, a belief, a habit, and a message: find the weak point, add weight there, and it holds.","cn":"同一个动作也适用于论点、信念、习惯和信息：找到薄弱处，在那里增加分量，它就立住了。"},{"en":"Reinforce always adds to something that already exists; it never creates the wall, the argument, or the habit in the first place.","cn":"reinforce 始终是在已有之物上添加；它从不最先造出那堵墙、那个论点或那个习惯。"}]},"examples":[{"en":"The coach reinforced the team's defence with two new players.","cn":"教练用两名新球员加强了球队的防守。"},{"en":"Repeated drills reinforce good habits.","cn":"反复演练会强化好习惯。"},{"en":"The report reinforced fears that the dam was unsafe.","cn":"这份报告加重了人们对大坝不安全的担忧。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“硬扶”——墙要塌，赶紧硬扶着，再浇一层混凝土、钉上钢板 → reinforce 加固；增援（只借音，不表词源）","word":"reinforce"},"root":"由 re-“再次”加 enforce“加强”构成，enforce 又来自古法语 enforcir（en- 使 + force 力）并上溯拉丁语 fortis“强壮”，核心是“在已有的力量上再加一层”。","sensesIntro":{"en":"Nine senses of reinforce, all from one gesture: find the point that is about to give way and add another layer of men, steel, evidence, help, or reward.","cn":"reinforce 的九个义项都出自同一个动作：找到快要撑不住的那一点，再往上加一层人、钢、证据、帮助或奖励。"},"semanticMap":{"core":{"en":"CORE IMAGE: a weak wall receives another layer of concrete and steel.","cn":"核心意象：一堵薄弱的墙又加上一层混凝土与钢。"},"chain":["FIND THE WEAK POINT","ADD MORE FORCE","ADD MORE MATERIAL","ADD MORE PEOPLE","ADD MORE EVIDENCE","MAKE IT HOLD"],"branches":[{"senses":"S1 · S9","en":"MILITARY AND DEFENCE: more troops arrive, and the wall itself is thickened so the line can absorb the attack.","cn":"军事与防御：更多部队赶到，墙本身也被加厚，好让防线吸收这次进攻。"},{"senses":"S2 · S6","en":"STRUCTURE AND MATERIAL: extra support is added to a bridge, and steel bars are placed inside concrete where it would crack.","cn":"结构与材料：桥上加额外支撑，钢筋被放进混凝土最容易开裂的位置。"},{"senses":"S3 · S8","en":"ARGUMENT AND MESSAGE: evidence adds weight to a claim, and repetition adds a layer to a message until it sticks.","cn":"论点与信息：证据给主张增加分量，重复给信息加层，直到它立住。"},{"senses":"S4 · S5","en":"PEOPLE AND FEELINGS: help and confidence are placed where a person struggles, while confirming events thicken a belief.","cn":"人与情绪：帮助与信心被放在某人吃力之处，而印证的事件则让信念变厚。"},{"senses":"S7","en":"BEHAVIOUR: a reward adds weight to a response, so the next occurrence becomes more likely.","cn":"行为：奖励给一个反应增加分量，于是下一次发生就更有可能。"}]},"affixes":{"intro":{"en":"Reinforce is re- plus enforce, and enforce is en- plus force. English adds -ment, -ed, -ing and -er; the Latin base fortis also gives fort, fortify, effort, comfort and fortitude.","cn":"reinforce 是 re- 加 enforce，而 enforce 是 en- 加 force。英语再加上 -ment、-ed、-ing、-er；拉丁词基 fortis 还给出 fort、fortify、effort、comfort、fortitude。"},"latinIntro":{"en":"Force descends from Latin fortis 'strong', through Vulgar Latin fortia and Old French force. Fortis is a plain Latin adjective; its family includes fortitudo 'strength' and the verb fortificare 'to make strong'.","cn":"force 经通俗拉丁语 fortia 与古法语 force，上溯拉丁语 fortis“强壮”。fortis 是普通的拉丁形容词；其词族包括 fortitudo“力量”与动词 fortificare“使强壮”。"},"items":[{"word":"reinforce","structure":"re- (again) + enforce (strengthen)","meaning":"to add strength to something already there","meaningCN":"在已有之物上再加强度（re- 再次 + enforce 加强）","example":"They reinforced the sea wall with concrete.","exampleCN":"他们用混凝土加固了海堤。"},{"word":"enforce","structure":"en- (make, put in) + force (strength)","meaning":"to give force to; to make a rule obeyed","meaningCN":"赋予力量；使规则得到遵守（en- 使 + force 力量）","example":"The police enforce the speed limit.","exampleCN":"警察执行限速规定。"},{"word":"reinforcement","structure":"reinforce + -ment (noun of action or result)","meaning":"the act of reinforcing; extra strength or support","meaningCN":"加固；增援；强化（-ment 构成行为或结果名词）","example":"The bridge needs reinforcement before winter.","exampleCN":"这座桥在入冬前需要加固。"},{"word":"reinforced","structure":"reinforce + -ed (past participle as adjective)","meaning":"strengthened with added material","meaningCN":"加固的；加筋的（-ed 构成形容词）","example":"The tunnel is lined with reinforced concrete.","exampleCN":"这条隧道内衬钢筋混凝土。"},{"word":"reinforcing","structure":"reinforce + -ing (present participle or adjective)","meaning":"serving to strengthen","meaningCN":"起加固作用的；强化中的（-ing 构成分词或形容词）","example":"The teacher used reinforcing praise after each try.","exampleCN":"每次尝试之后，老师都用表扬来强化。"},{"word":"reinforcer","structure":"reinforce + -er (thing that does)","meaning":"a reward or stimulus that strengthens behaviour","meaningCN":"强化物；强化因素（-er 表示起作用者）","example":"Food is a powerful reinforcer in animal training.","exampleCN":"在动物训练中，食物是强有力的强化物。"},{"word":"force","structure":"Old French force, from Vulgar Latin fortia, from fortis","meaning":"strength or power","meaningCN":"力量；武力（出自拉丁语 fortis“强壮”）","example":"The storm hit the coast with great force.","exampleCN":"风暴以极大的力量袭击了海岸。"},{"word":"fort","structure":"Latin fortis 'strong'","meaning":"a strong fortified place","meaningCN":"堡垒；要塞（拉丁语 fortis“强壮”）","example":"The old fort still stands above the harbour.","exampleCN":"那座旧堡垒仍立在海港上方。"},{"word":"fortify","structure":"fort- (fortis, strong) + -ify (make)","meaning":"to make strong; to build defences","meaningCN":"加强；设防（fort- 强壮 + -ify 使）","example":"They fortified the town with a new wall.","exampleCN":"他们用一道新墙加固了这座城。"},{"word":"effort","structure":"ef- (ex-, out) + fort- (fortis, strength)","meaning":"an attempt requiring strength","meaningCN":"努力；尝试（ef- 出 + fortis 力量）","example":"It took little effort to lift the box.","exampleCN":"抬起那只箱子没费什么力气。"},{"word":"comfort","structure":"com- (together, intensive) + fort- (fortis, strong)","meaning":"to strengthen; ease and consolation","meaningCN":"安慰；舒适（com- 加强 + fortis 强壮，原义“大大加强”）","example":"Her letter comforted him during the winter.","exampleCN":"那个冬天，她的来信给了他安慰。"},{"word":"fortitude","structure":"fort- (fortis, strong) + -tude (state)","meaning":"strength of mind in difficulty","meaningCN":"坚毅；刚强（fort- 强壮 + -tude 状态）","example":"She bore the loss with quiet fortitude.","exampleCN":"她以平静的坚毅承受了这次失去。"}],"latinEntries":[{"word":"fortis","structure":"Latin adjective","meaning":"strong, powerful","meaningCN":"强壮的；有力的"},{"word":"fortia","structure":"Vulgar Latin noun from fortis","meaning":"strength, force","meaningCN":"力量；武力"},{"word":"fortitudo","structure":"fortis + -tudo (state noun)","meaning":"strength, courage","meaningCN":"力量；勇气"}]}},{"word":"reject","ipa_uk":"/rɪˈdʒekt/","ipa_us":"/rɪˈdʒekt/","definition_zh":"拒绝；不接受；否决；驳回；排斥；丢弃；退回","definition_en":"to refuse to accept, take, or believe something, or to push it away","core_image":"有人把递到面前的东西抬手一挡，原样扔回对方怀里","scene":"The editor rejected the manuscript because its claims could not be checked.","sceneCN":"这里 reject 是「拒绝接受」（第 1 个义项：不接受递来的东西）；句意：编辑拒绝了这份稿子，因为其中的说法无从核实。场景要点：堆满稿件的书桌、退回的牛皮纸袋、红笔批注、窗外的邮筒。","pos":[{"tag":"vt.","zh":"拒绝；不接受；否决；排斥；丢弃"},{"tag":"n.","zh":"被拒绝者；退回的次品"}],"collocations":[{"phrase":"reject an offer","zh":"拒绝一项提议"},{"phrase":"reject an application","zh":"拒绝一份申请"},{"phrase":"reject a theory","zh":"拒绝接受某种理论"},{"phrase":"reject a transplant","zh":"排斥移植器官"},{"phrase":"reject a claim","zh":"驳回索赔或主张"},{"phrase":"reject a proposal","zh":"否决一项提案"},{"phrase":"reject out of hand","zh":"一口回绝"}],"forms":[{"label":"三单（he/she/it）","form":"rejects"},{"label":"过去式（已经发生）","form":"rejected"},{"label":"过去分词（完成／被动）","form":"rejected"},{"label":"现在分词（进行体）","form":"rejecting"},{"label":"名词复数","form":"rejects"}],"derivatives":[{"word":"rejection","pos":"n.","zh":"拒绝；否决；排斥反应"},{"word":"rejected","pos":"adj.","zh":"被拒绝的；被退回的"},{"word":"reject","pos":"n.","zh":"被拒者；次品；退回的货"},{"word":"rejecting","pos":"adj.","zh":"拒绝的；排斥的"},{"word":"rejective","pos":"adj.","zh":"拒绝的；排斥的"}],"senses":[{"no":"01","title":"Refuse an offer or invitation","titleCN":"拒绝提议或邀请","definition":"to refuse to accept something that is offered or proposed to you","definitionCN":"拒绝接受别人提供或提议给你的东西","example":"She rejected the job offer because it meant moving abroad.","exampleCN":"她拒绝了那份工作，因为那意味着要搬到国外。","why":"Latin reicere meant 'throw back'. An offer is held out to you; rejecting it is the physical refusal to take it, so the thing goes back to the person who offered it.","whyCN":"拉丁语 reicere 意为“扔回去”。提议是别人递到你面前的；拒绝就是身体上不接受，于是那东西被送回给它原来的主人。"},{"no":"02","title":"Turn down an applicant","titleCN":"把申请者刷下去","definition":"to refuse to accept a person for a job, place, or course","definitionCN":"拒绝录用、接收某人参加工作、入学或课程","example":"The committee rejected three of the twelve candidates.","exampleCN":"委员会在十二名候选人中刷掉了三名。","why":"The thing thrown back is now a person's application. The candidate is not taken into the group, so the hand that would have admitted them stays closed.","whyCN":"被扔回去的东西现在是一份申请。申请者不被纳入群体，那只原本要接纳他的手便保持握紧。"},{"no":"03","title":"Refuse to believe an idea","titleCN":"拒绝相信某个说法","definition":"to refuse to accept an idea, theory, or explanation as true","definitionCN":"拒绝把某种观念、理论或解释当作真的接受","example":"Most physicists rejected the theory when it was first published.","exampleCN":"这个理论首次发表时，大多数物理学家都不接受它。","why":"An idea is offered to the mind like an object to the hand. To reject it is to push it away before it can settle into belief.","whyCN":"观念被递到心智面前，就像物件被递到手边。拒绝它，就是在它落进信念之前把它推开。"},{"no":"04","title":"Rebuff a person's advances","titleCN":"回绝别人的追求","definition":"to refuse a person who makes romantic or social advances, often abruptly","definitionCN":"拒绝在感情或社交上主动靠近自己的人，往往很干脆","example":"He asked her to dinner, and she rejected him gently.","exampleCN":"他请她吃晚饭，她温和地回绝了他。","why":"This sense is recorded from the 1560s, especially of a woman refusing a man as a lover. The offered thing is the person's approach, and it is thrown back at them.","whyCN":"这个义项记录于 16 世纪 60 年代，尤指女性拒绝男性作为恋人。被递过来的是这个人的靠近，而它被原样扔了回去。"},{"no":"05","title":"Throw something away as useless","titleCN":"把没用的东西扔掉","definition":"to throw away or discard something as undesirable or useless","definitionCN":"把某物当作不受欢迎或无用之物丢弃","example":"The sorting machine rejects any fruit with a bruise.","exampleCN":"分选机把任何有碰伤的果子都剔除掉。","why":"This is the most literal branch, recorded by the 1530s: the thing is judged worthless and is cast aside, exactly as reicere described throwing something back or away.","whyCN":"这是最字面的一支，记录于 16 世纪 30 年代：东西被判定为无价值而丢到一边，正是 reicere 所说的“扔回去或扔掉”。"},{"no":"06","title":"The body attacks a transplanted organ","titleCN":"身体攻击移植来的器官","definition":"of an immune system, to attack and refuse tissue transplanted from another body","definitionCN":"指免疫系统攻击并排斥来自另一身体的移植组织","example":"The body may reject a donated organ within days.","exampleCN":"身体可能在几天之内就排斥捐赠的器官。","why":"The medical sense, recorded from 1953, treats the organ as foreign matter that the body throws back. It is the same refusal, now carried out by cells.","whyCN":"医学义记录于 1953 年，把器官当作被身体扔回去的外来物。这还是同一种拒绝，只是执行者变成了细胞。"},{"no":"07","title":"A filter blocks a signal","titleCN":"滤波器挡掉信号","definition":"of a device or circuit, to block or remove a signal, frequency, or particle that is not wanted","definitionCN":"指装置或电路阻挡、去除不需要的信号、频率或粒子","example":"The filter rejects noise below fifty hertz.","exampleCN":"这个滤波器挡掉五十赫兹以下的噪声。","why":"A filter is a sieve that lets some things through and throws the rest back. The technical use extends the same physical refusal to waves and particles.","whyCN":"滤波器是一张筛子，让一部分东西通过，把其余的挡回去。这个技术义把同一种物理拒绝扩展到波与粒子。"},{"no":"08","title":"A court dismisses a claim","titleCN":"法院驳回一项主张","definition":"of a court or official body, to refuse to accept a claim, appeal, or request","definitionCN":"指法院或官方机构拒绝接受某项主张、上诉或请求","example":"The court rejected the appeal without a hearing.","exampleCN":"法院未经听证就驳回了上诉。","why":"A claim is formally presented for acceptance. When the authority refuses it, the paper is sent back with the same gesture, now backed by law.","whyCN":"主张被正式提交，等待被接受。当局拒绝它时，文件被以同样的动作退回，只是这次背后有法律作支撑。"},{"no":"09","title":"A factory fails a defective item","titleCN":"工厂把次品判废","definition":"to fail an item at inspection because it does not meet the required standard","definitionCN":"在检验中判定某件产品不合格，因为它未达到要求的标准","example":"The quality team rejected twelve bottles with cracked caps.","exampleCN":"质检组把十二只瓶盖开裂的瓶子判为不合格。","why":"The item is measured against a standard and then cast aside. Here the throw-back is bureaucratic rather than physical: the reject is the object that failed the line.","whyCN":"产品被拿去对照标准，然后被丢到一边。这里的“扔回”是程序性的而非物理性的：被拒之物就是没能过线的那一件。"}],"etymology":{"intro":{"en":"Reject comes from Latin reicere 'to throw back', re- 'back' + iacere 'to throw', through its frequentative reiectare and past participle reiectus. English took it from Old French rejecter and directly from Latin in the early fifteenth century. Dates follow standard etymological references.","cn":"reject 来自拉丁语 reicere“扔回去”，由 re-“回”加 iacere“投、扔”构成，经其反复动词 reiectare 与过去分词 reiectus 传入。英语在 15 世纪早期从古法语 rejecter 并直接由拉丁语借入。年代依据通行词源资料。"},"items":[{"era":"EARLY 15C.","en":"First recorded as rejecten, 'eject, set aside, block from inheritance'. The oldest English sense is legal and physical, not conversational.","cn":"最早记录为 rejecten，意为“逐出、搁置、排除继承权”。英语里最古老的义项是法律与物理性的，而不是日常对话里的拒绝。"},{"era":"LATE 15C.","en":"By the late 15th century it also meant 'refuse to acquiesce or submit to'. The idea of refusing a demand or authority appears here.","cn":"到 15 世纪晚期，它也有了“拒绝默许或服从”的意思。拒绝要求或权威的观念在这里出现。"},{"era":"OLD FRENCH / LATIN","en":"From Old French rejecter and directly from Latin reiectus, past participle of reiectare 'throw away, cast away, vomit', a frequentative of reicere 'to throw back'.","cn":"来自古法语 rejecter，并直接来自拉丁语 reiectus，即 reiectare 的过去分词；reiectare 意为“扔掉、丢弃、呕吐”，是 reicere“扔回去”的反复动词。"},{"era":"LATIN / PIE","en":"Reicere is re- 'back' + -icere, the combining form of iacere 'to throw', from PIE *ye- 'to throw, impel'. Literally, to reject is to throw something back to where it came from.","cn":"reicere 是 re-“回”加 -icere，即 iacere“投、扔”的组合形式，后者出自原始印欧语 *ye-“投掷、推动”。字面上，reject 就是把东西扔回它来的地方。"},{"era":"1530s–1660s","en":"The sense 'throw away as undesirable or useless' is recorded by the 1530s; 'repel or rebuff a person' from the 1560s; 'refuse something offered' by the 1660s. The everyday modern senses are late arrivals.","cn":"“作为不受欢迎或无用之物扔掉”的义项记录于 16 世纪 30 年代；“击退或回绝某人”始于 16 世纪 60 年代；“拒绝被提供的东西”到 17 世纪 60 年代已出现。现代日常义项都是较晚才到的。"},{"era":"1953–MODERN","en":"The medical sense 'show immune response to a transplanted organ' is from 1953. The noun reject is older: 'a castaway' from the 1550s, 'a thing cast aside as unsatisfactory' from 1893, and 'a person considered worthless' from 1925.","cn":"医学义“对移植器官产生免疫排斥”始于 1953 年。名词 reject 更早：16 世纪 50 年代指“被抛弃者”，1893 年指“因不合格而被丢弃之物”，1925 年指“被视为无价值的人”。"}]},"similar":{"note":{"en":"The first group separates reject from its derived forms and from the noun that names a cast-off object. The second group compares four verbs of refusal that differ in tone, target, and force.","cn":"第一组把 reject 与它的派生形式分开，也区分那个指“被丢弃之物”的名词；第二组比较四个在语气、对象与力度上不同的“拒绝”动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"rejection","ipa":"/rɪˈdʒekʃn/","tag":"derived noun","definition":"the act of rejecting, or the state of being refused. It also names the immune response to a transplant.","definitionCN":"拒绝的行为，或被拒绝的状态。它也指对移植物的免疫排斥。"},{"word":"rejected","ipa":"/rɪˈdʒektɪd/","tag":"past participle as adjective","definition":"refused or cast aside. It describes the object or person that suffered the refusal.","definitionCN":"被拒绝的；被丢弃的。它描述承受这次拒绝的物或人。"},{"word":"reject","ipa":"/ˈriːdʒekt/","tag":"noun with different stress","definition":"a person or thing that has been rejected, especially a defective product. As a noun it shifts the stress to the first syllable.","definitionCN":"被拒绝的人或物，尤指次品。作名词时重音移到第一个音节。"},{"word":"rejective","ipa":"/rɪˈdʒektɪv/","tag":"derived adjective","definition":"tending to reject or refuse. It is rare and mostly technical, unlike the everyday verb.","definitionCN":"倾向于拒绝或排斥的。它较少见，多用于技术语境，与日常动词不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"refuse","ipa":"/rɪˈfjuːz/","tag":"general unwillingness","definition":"to say no to something you are asked to do or given. It is the broad everyday word and often softer than reject, which can sound final.","definitionCN":"对别人的请求或给予说“不”。它是最宽泛的日常词，通常比 reject 温和，而 reject 可能显得决绝。"},{"word":"decline","ipa":"/dɪˈklaɪn/","tag":"polite refusal","definition":"to refuse something politely, especially an invitation or offer. It is formal and courteous, while reject can be blunt.","definitionCN":"礼貌地拒绝，尤指邀请或提议。它正式而客气，而 reject 可能很直接。"},{"word":"deny","ipa":"/dɪˈnaɪ/","tag":"say it is not true","definition":"to say that something is not true, or to refuse to give something. It attacks the truth of a statement or withholds a request, rather than throwing an offer back.","definitionCN":"说某事不真实，或拒绝给予某物。它针对陈述的真实性，或扣住请求不给，而不是把提议扔回去。"},{"word":"repel","ipa":"/rɪˈpel/","tag":"push away physically","definition":"to drive something back or keep it away by force. It is physical or military, while reject can be purely verbal or procedural.","definitionCN":"以力量把某物击退或挡在外面。它是物理或军事性的，而 reject 可以纯粹是口头或程序上的。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: Latin re- 'back' + iacere 'throw', the frequentative reiectare, and the English family rejection, rejected, eject, inject, project and object.","cn":"只用真实成分与真实同族词：拉丁语 re-“回”加 iacere“投、扔”、反复动词 reiectare，以及英语词族 rejection、rejected、eject、inject、project、object。"},"normal":[{"en":"reicere is literally 'throw back': re- 'back' + iacere 'throw'. Reject is the hand that returns what was offered.","cn":"reicere 字面就是“扔回去”：re-“回”+ iacere“扔”。reject 就是那只把递来之物退回的手。"},{"en":"The same iacere gives eject (throw out), inject (throw in), project (throw forward) and object (throw against).","cn":"同一个 iacere 还给出 eject（扔出）、inject（扔进）、project（向前扔）、object（扔向对面）。"},{"en":"The oldest English sense was legal: to set aside or block from inheritance. Refusal came later.","cn":"英语里最古老的义项是法律性的：搁置或排除继承权。拒绝的意思来得更晚。"},{"en":"The verb is stressed on the second syllable, the noun on the first: re-JECT versus a RE-ject.","cn":"动词重音在第二音节，名词重音在第一音节：re-JECT 对 a RE-ject。"},{"en":"In medicine, rejection is the body throwing back a transplanted organ; in quality control, a reject is the item thrown aside.","cn":"医学里，rejection 是身体把移植器官扔回去；质检里，a reject 是被丢到一边的那件产品。"}],"abstract":[{"en":"Picture a hand held out with a letter. The other hand comes up, blocks it, and pushes it back toward the sender.","cn":"想象一只手递出一封信。另一只手抬起来挡住，把它推回给递信的人。"},{"en":"The thing pushed back can be an offer, a person, an idea, an organ, a signal, or a defective bottle; the gesture never changes.","cn":"被推回去的东西可以是一个提议、一个人、一个观念、一个器官、一段信号或一只次品瓶子；动作始终不变。"},{"en":"Reject is stronger and more final than refuse or decline: it closes the door rather than postponing an answer.","cn":"reject 比 refuse 或 decline 更强、更决绝：它是把门关上，而不是把回答往后拖。"}]},"examples":[{"en":"She rejected the job offer because it meant moving abroad.","cn":"她拒绝了那份工作，因为那意味着要搬到国外。"},{"en":"The body may reject a donated organ within days.","cn":"身体可能在几天之内就排斥捐赠的器官。"},{"en":"The quality team rejected twelve bottles with cracked caps.","cn":"质检组把十二只瓶盖开裂的瓶子判为不合格。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“瑞杰克特”——瑞杰克特把退回来的次品一件件截下，扔回废料筐 → reject 拒绝；退回（只借音，不表词源）","word":"reject"},"root":"源自拉丁语 reicere“扔回去”（re- 回 + iacere 投掷），核心是“把递过来的东西原样扔回去”。","sensesIntro":{"en":"Nine senses of reject, all from one gesture: something is held out, the hand refuses it, and it goes back to where it came from.","cn":"reject 的九个义项都出自同一个动作：某物被递到面前，手拒绝接收，它便被送回原来的地方。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand blocks what is offered and pushes it back.","cn":"核心意象：一只手挡住递来的东西，并把它推回去。"},"chain":["SOMETHING IS OFFERED","THE HAND REFUSES","IT IS PUSHED BACK","IT IS NOT ADMITTED","IT IS DISCARDED","THE BODY OR SYSTEM REPELS IT"],"branches":[{"senses":"S1 · S2","en":"REFUSE WHAT IS OFFERED: an offer, a proposal, or a candidate is not taken in, so the hand stays closed.","cn":"拒绝递来之物：提议、方案或候选人未被接纳，那只手便保持握紧。"},{"senses":"S3 · S8","en":"REFUSE TO ACCEPT A CLAIM: a theory or a legal claim is presented for acceptance and sent back unsupported.","cn":"拒绝接受主张：理论或法律主张被提交上来等待接受，又被原样退回。"},{"senses":"S4","en":"REBUFF A PERSON: the thing offered is someone's approach, and it is thrown back at them.","cn":"回绝某人：被递过来的是某人的靠近，而它被扔回给对方。"},{"senses":"S5 · S9","en":"DISCARD: what is judged useless or defective is cast aside, from bruised fruit to a failed bottle.","cn":"丢弃：被判为无用或不合格的东西被丢到一边，从碰伤的果子到没过的瓶子。"},{"senses":"S6 · S7","en":"REPEL: the immune system and a filter both push foreign matter back, one with cells and one with circuits.","cn":"排斥：免疫系统与滤波器都在把外来物推回去，一个用细胞，一个用电路。"}]},"affixes":{"intro":{"en":"Reject is re- 'back' plus the Latin verb iacere 'throw', seen through its combining form -icere. English adds -ion, -ed, -ing and -ive; the same iacere family gives eject, inject, project, object, subject and trajectory.","cn":"reject 是 re-“回”加拉丁语动词 iacere“投、扔”，经由其组合形式 -icere 出现。英语再加上 -ion、-ed、-ing、-ive；同一个 iacere 词族还给出 eject、inject、project、object、subject、trajectory。"},"latinIntro":{"en":"Iacere 'to throw, cast' is a common Latin verb, reconstructed to PIE *ye- 'to throw, impel'. With different prefixes it produces a whole family of English verbs about directed motion: eject, inject, project, object, subject, and reject itself.","cn":"iacere“投、扔”是常见的拉丁语动词，可重构到原始印欧语 *ye-“投掷、推动”。加上不同的前缀，它产生了一整族表示有方向运动的英语动词：eject、inject、project、object、subject，以及 reject 本身。"},"items":[{"word":"reject","structure":"re- (back) + -icere (iacere, to throw)","meaning":"to throw back; to refuse","meaningCN":"扔回去；拒绝（re- 回 + iacere 投掷）","example":"The board rejected the merger plan.","exampleCN":"董事会否决了合并计划。"},{"word":"rejection","structure":"reject + -ion (noun of action)","meaning":"the act of refusing; immune refusal","meaningCN":"拒绝；驳回；排斥反应（-ion 构成行为名词）","example":"The rejection letter arrived two weeks later.","exampleCN":"拒绝信两周后到了。"},{"word":"rejected","structure":"reject + -ed (past participle as adjective)","meaning":"refused or cast aside","meaningCN":"被拒绝的；被退回的（-ed 构成形容词）","example":"The rejected plan was never resubmitted.","exampleCN":"被否决的方案再也没有重新提交。"},{"word":"rejecting","structure":"reject + -ing (present participle)","meaning":"the act of refusing, or tending to refuse","meaningCN":"拒绝的行为；排斥的（-ing 构成分词）","example":"The rejecting committee gave no reasons.","exampleCN":"那个拒绝的委员会没有给出理由。"},{"word":"rejective","structure":"reject + -ive (adjective)","meaning":"having a tendency to reject","meaningCN":"拒绝的；排斥的（-ive 构成形容词）","example":"The test measures rejective attitudes toward outsiders.","exampleCN":"这项测试测量对外来者的排斥态度。"},{"word":"eject","structure":"e- (ex-, out) + iacere (throw)","meaning":"to throw out","meaningCN":"逐出；弹出（e- 出 + iacere 扔）","example":"The pilot ejected from the burning plane.","exampleCN":"飞行员从燃烧的飞机中弹射出来。"},{"word":"inject","structure":"in- (into) + iacere (throw)","meaning":"to throw or put something in","meaningCN":"注入；注射（in- 进入 + iacere 投）","example":"The nurse injected the vaccine into his arm.","exampleCN":"护士把疫苗注射进他的手臂。"},{"word":"project","structure":"pro- (forward) + iacere (throw)","meaning":"to throw forward; a planned undertaking","meaningCN":"投射；项目（pro- 向前 + iacere 投）","example":"The light projected the map onto the wall.","exampleCN":"灯光把地图投射到墙上。"},{"word":"object","structure":"ob- (against) + iacere (throw)","meaning":"to throw against; a thing put before the mind","meaningCN":"反对；物体（ob- 对着 + iacere 投）","example":"Several residents objected to the new road.","exampleCN":"几位居民反对这条新路。"},{"word":"subject","structure":"sub- (under) + iacere (throw)","meaning":"to throw under; a topic or person under authority","meaningCN":"使服从；主题；臣民（sub- 在下 + iacere 投）","example":"The topic was subjected to close scrutiny.","exampleCN":"这个课题受到了仔细审查。"},{"word":"trajectory","structure":"tra- (trans-, across) + iacere (throw) + -ory","meaning":"the path of something thrown across","meaningCN":"轨迹；弹道（tra- 横越 + iacere 投 + -ory）","example":"The rocket's trajectory was tracked by radar.","exampleCN":"火箭的轨迹由雷达追踪。"},{"word":"adjective","structure":"ad- (to, toward) + iacere (throw) + -ive","meaning":"a word thrown alongside a noun","meaningCN":"形容词（ad- 向 + iacere 投 + -ive，即“投到名词旁边的东西”）","example":"The adjective 'cold' describes the wind.","exampleCN":"形容词 cold 描述这阵风。"}],"latinEntries":[{"word":"reicere","structure":"re- (back) + iacere (throw)","meaning":"to throw back, cast away","meaningCN":"扔回去；抛弃"},{"word":"iacere","structure":"Latin verb, from PIE *ye- 'throw'","meaning":"to throw, cast","meaningCN":"投；扔；掷"},{"word":"reiectus","structure":"past participle of reicere","meaning":"thrown back; rejected","meaningCN":"被扔回的；被拒绝的"}]}},{"word":"relate","ipa_uk":"/rɪˈleɪt/","ipa_us":"/rɪˈleɪt/","definition_zh":"叙述；讲述；与……有关；使有联系；建立关联；认同；相处","definition_en":"to tell a story or give an account of events, to be connected with something, or to bring two things into connection in thought or speech","core_image":"把消息从远处带回来，再把两样东西摆到同一张桌上","scene":"At the family reunion, the oldest aunt related how the village had been evacuated in a single night.","sceneCN":"这里 relate 是「讲述、叙述」（第 1 个义项：把发生的事一件件讲出来）；句意：家庭聚会上，最年长的姑妈讲述了全村如何在一夜之间撤离。场景要点：老屋的堂屋、围坐的家人、姑妈比划的手势、桌上摊开的旧照片。","pos":[{"tag":"vt.","zh":"叙述；讲述；使有联系；把……与……关联"},{"tag":"vi.","zh":"有关；涉及；认同；与人相处"}],"collocations":[{"phrase":"relate to","zh":"与……有关；涉及；对……产生共鸣"},{"phrase":"be related to","zh":"与……有联系；是……的亲属"},{"phrase":"relate A to B","zh":"把 A 与 B 联系起来"},{"phrase":"relate a story","zh":"讲述一个故事"},{"phrase":"relate well to","zh":"与……相处融洽"},{"phrase":"relate to a character","zh":"对某个角色产生共鸣"},{"phrase":"relate one's experience","zh":"讲述自己的经历"}],"forms":[{"label":"三单（he/she/it）","form":"relates"},{"label":"过去式（已经发生）","form":"related"},{"label":"过去分词（完成／被动）","form":"related"},{"label":"现在分词（进行体）","form":"relating"}],"derivatives":[{"word":"related","pos":"adj.","zh":"相关的；有亲属关系的"},{"word":"relation","pos":"n.","zh":"关系；联系；亲属；叙述"},{"word":"relationship","pos":"n.","zh":"关系；人际关系；亲属关系"},{"word":"relative","pos":"adj./n.","zh":"相对的；比较的；亲属"},{"word":"relatively","pos":"adv.","zh":"相对地；比较而言"},{"word":"relatable","pos":"adj.","zh":"能引起共鸣的；令人感同身受的"}],"senses":[{"no":"01","title":"Carry the story back: recount","titleCN":"把故事带回来：叙述、讲述","definition":"to give an account of events, telling them in speech or writing in the order they happened","definitionCN":"按事情发生的顺序，用口语或文字把事情讲出来","example":"She related the events of that night to the police.","exampleCN":"她把那天夜里发生的事讲给了警察。","why":"Latin relatus was the past participle of referre, 'to carry back'. The oldest English sense is exactly that: a person carries news of what happened back to listeners who were not there.","whyCN":"拉丁语 relatus 是 referre“带回”的过去分词。英语最早的意思正是这样：一个人把发生之事的消息带回来，讲给不在场的人听。"},{"no":"02","title":"What the account is about: concern","titleCN":"所述之事指向什么：涉及、关乎","definition":"in relate to, to have something as its subject or be about a particular matter","definitionCN":"用于 relate to，表示以某事为主题，或与某件事有关","example":"The questions relate to the safety of the new bridge.","exampleCN":"这些问题涉及新桥的安全。","why":"A report carries back one particular piece of the world. Whatever that piece is, the report 'relates to' it — the subject is the thing the message points back at.","whyCN":"一份报告带回来的是世界的某一个片段。无论那个片段是什么，报告都“指向”它——所述之事就是消息指回去的那个对象。"},{"no":"03","title":"Lie side by side: be connected","titleCN":"被摆在一起：有联系、相关","definition":"to be connected with something, especially in a way that one helps explain the other","definitionCN":"与某事存在联系，尤指一方能帮助解释另一方","example":"Her headaches are related to the noise at the factory.","exampleCN":"她的头痛与工厂的噪音有关。","why":"Once two things are carried from the same source, they can be laid beside each other. The connection is not physical: it is the fact that both belong to one story.","whyCN":"两样东西一旦来自同一个源头，就可以被摆在一起。这种联系并不是物理上的，而是它们都属于同一个故事。"},{"no":"04","title":"Put them on one table: link in thought","titleCN":"摆到同一张桌上：把两事物联系起来","definition":"to bring one thing into connection with another in speech, writing, or reasoning","definitionCN":"在说话、写作或推理中，把一事物与另一事物联系起来","example":"The report relates the rise in asthma to air pollution.","exampleCN":"这份报告把哮喘发病率上升与空气污染联系起来。","why":"Now the carrying becomes an action of the speaker: you take one fact and set it down next to another so that the listener sees the line between them.","whyCN":"这时“带”变成了说话者的动作：你拿起一个事实，把它放到另一个事实旁边，让听者看见两者之间的那条线。"},{"no":"05","title":"Draw the line: establish a connection","titleCN":"画出那条线：建立关联、对应","definition":"to show or establish a connection between two sets of facts, often in a formal account","definitionCN":"在正式论述中显示或建立两组事实之间的关联","example":"The study relates temperature data to crop yields.","exampleCN":"这项研究把气温数据与农作物产量对应起来。","why":"The transitive use from the 1690s hardens the image: the two things are now deliberately aligned, so that one can stand for or predict the other.","whyCN":"17 世纪 90 年代起的及物用法让这个意象凝固下来：两样东西被有意对齐，于是一方可以代表或预测另一方。"},{"no":"06","title":"Carried from one ancestor: kinship","titleCN":"出自同一祖先：亲属关系","definition":"in be related to, to be a member of the same family as someone","definitionCN":"用于 be related to，表示与某人是同一家庭的成员","example":"She is related to the composer through her mother.","exampleCN":"她通过母亲一方与那位作曲家有亲属关系。","why":"Two people are carried back to one common ancestor. The same 'brought back to a shared point' that links facts also links bloodlines.","whyCN":"两个人被追溯到一个共同的祖先。把事实连在一起的“回溯到同一点”，也同样把血脉连在一起。"},{"no":"07","title":"Bring it home: identify with","titleCN":"带回自己身上：产生共鸣、认同","definition":"to feel that you understand a character, story, or experience because it matches your own life","definitionCN":"因某个角色、故事或经历与自己的生活相似而觉得理解它","example":"Many readers relate to the narrator's fear of failure.","exampleCN":"许多读者对叙述者害怕失败的心情产生共鸣。","why":"The account is carried back a second time: from the page into the reader's own memory. What returns is no longer a story but a recognition of oneself.","whyCN":"这段叙述被第二次“带回”：从书页带回读者自己的记忆里。带回来的已不是故事，而是对自己的辨认。"},{"no":"08","title":"Take in another's account: understand","titleCN":"接住别人的叙述：理解、体谅","definition":"to understand and sympathize with someone's situation or feelings","definitionCN":"理解并体谅某人的处境或感受","example":"I can relate to how tired you are after night shifts.","exampleCN":"我能理解你上完夜班后有多累。","why":"Here the carrying runs the other way: you receive the other person's account and bring it back to something you have lived through, so understanding replaces mere hearing.","whyCN":"这里“带”的方向反了过来：你接住对方的叙述，把它带回自己经历过的事，于是理解取代了单纯的听见。"},{"no":"09","title":"Keep messages moving: get on with people","titleCN":"让消息来回流通：与人相处","definition":"to interact well with other people, so that communication passes easily between you","definitionCN":"与别人相处得好，彼此之间交流顺畅","example":"He relates well to the younger staff on the team.","exampleCN":"他与团队里较年轻的员工相处得很好。","why":"Two people who relate keep carrying messages back and forth without friction. The original image of a safe return becomes social ease.","whyCN":"两个人“相处得好”，就是消息在彼此之间来回传递而不受阻。原本“平安带回”的意象，变成了社交上的顺畅。"}],"etymology":{"intro":{"en":"Relate entered English in the 1520s from French and Latin. Its Latin past participle relatus belongs to the verb referre, not to a verb of its own, and the deeper origin of relatus is disputed. Dates are approximate.","cn":"relate 于 16 世纪 20 年代经由法语和拉丁语进入英语。它的拉丁过去分词 relatus 属于动词 referre，而不是某个独立动词；relatus 更深层的来源存在争议。年代为大致估计。"},"items":[{"era":"1520s","en":"First recorded in English as 'to recount, tell', from French relater 'refer, report' (14c.) and directly from Latin relatus, used as the past participle of referre.","cn":"英语最早记录为“叙述、讲述”，来自 14 世纪法语 relater“转述、报告”，并直接来自拉丁语 relatus——它被用作 referre 的过去分词。"},{"era":"OLD FRENCH","en":"Old French relater (14c.) meant 'refer, report'. The French verb supplied the -ate ending and the reporting sense; the relational senses grew later inside English.","cn":"古法语 relater（14 世纪）意为“转述、报告”。法语动词提供了 -ate 词尾与“报告”义；表示“关系”的各义项是后来在英语内部生长出来的。"},{"era":"LATIN relatus","en":"Relatus is not a regular participle. It is a suppletive form: the missing participle of referre was supplied by latus, taken from another verb. Relation (c. 1300) and relative come down the same line.","cn":"relatus 不是规则分词，而是补充形式：referre 缺失的过去分词由另一个动词的 latus 顶替。relation（约 1300 年）与 relative 同属这条线。"},{"era":"referre","en":"Latin referre meant 'to carry back, bear back', from re- 'back, again' + ferre 'to carry, bear'. Ferre goes back to PIE *bher- (1) 'to carry', also 'to bear children'.","cn":"拉丁语 referre 意为“带回来、携回”，由 re-“向后、再”+ ferre“携带、承载”构成。ferre 可追溯到原始印欧语 *bher-（1）“携带”，也指“生育”。"},{"era":"latus","en":"Latin latus 'borne, carried' is the suppletive participle shared by ferre and its compounds. Watkins derived it from *tlatos, from PIE *tele- 'to bear, carry'; de Vaan writes 'No good etymology available'. The deepest root is therefore source uncertain.","cn":"拉丁语 latus“被携带的”是 ferre 及其复合词共用的补充分词。Watkins 将其追溯到 *tlatos，再上溯原始印欧语 *tele-“承载、携带”；de Vaan 则写“没有可靠的词源”。故最深层词根来源不确定。"},{"era":"MODERN ENGLISH","en":"The sense 'stand in some relation' is from the 1640s; the transitive 'bring into relation with' from the 1690s; 'establish a relation between' from 1771. The psychological sense 'feel connected or sympathetic to' is attested from 1950.","cn":"“处于某种关系”义始于 17 世纪 40 年代；及物的“使与……发生关系”始于 17 世纪 90 年代；“建立两者间的关系”始于 1771 年。心理学术语中“感到有联系、能共鸣”的义项记录于 1950 年。"}]},"similar":{"note":{"en":"Group one separates relate from the nouns and adjectives built on it; group two separates the verbs of telling from the verbs of connecting. Note the two patterns: relate to means 'concern or empathize', while be related to means 'be connected or be kin'.","cn":"第一组把 relate 与由它构成的名词、形容词分开；第二组把“讲述”类动词与“连接”类动词分开。要特别注意两个搭配：relate to 表示“涉及、共鸣”，be related to 表示“有联系、是亲属”。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"relation","ipa":"/rɪˈleɪʃn/","tag":"noun: abstract connection","definition":"the way in which two things are connected, or an account of events. It names the link itself, while relate names the act of making or telling it.","definitionCN":"两事物相连的方式，或对事件的叙述。它指“联系”本身，而 relate 指建立或讲述联系的动作。"},{"word":"relationship","ipa":"/rɪˈleɪʃnʃɪp/","tag":"noun: between people","definition":"the state of being connected, especially between people or groups. It is warmer and more personal than relation, which is often abstract.","definitionCN":"相连的状态，尤指人或群体之间。它比常指抽象关系的 relation 更带人情味。"},{"word":"relative","ipa":"/ˈrelətɪv/","tag":"adjective and noun","definition":"as an adjective, 'compared with something else'; as a noun, 'a family member'. It keeps the Latin participle stem but has moved away from the verb's 'tell' sense.","definitionCN":"作形容词是“相对的、比较的”；作名词是“亲属”。它保留拉丁分词词干，但已远离动词“讲述”的意思。"},{"word":"related","ipa":"/rɪˈleɪtɪd/","tag":"adjective: connected","definition":"connected by origin, family, or subject. It describes the state, while relate describes the act that produces or reports it.","definitionCN":"因来源、家庭或主题而相连的。它描述状态，而 relate 描述产生或讲述这种状态的动作。"}]},{"heading":"NEAR MEANING","entries":[{"word":"connect","ipa":"/kəˈnekt/","tag":"join two things","definition":"to join or link things, often physically or through a clear logical link. Connect stresses the join; relate stresses the meaningful correspondence between them.","definitionCN":"把事物连接起来，常指物理连接或清晰的逻辑连接。connect 强调“接上”，relate 强调两者之间有意义的对应。"},{"word":"associate","ipa":"/əˈsəʊsieɪt/","tag":"link in the mind","definition":"to connect one idea with another in the mind, often by habit or repeated experience. It is more psychological and less factual than relate.","definitionCN":"在头脑中把一个想法与另一个联系起来，常因习惯或反复经验。它比 relate 更偏心理联想，事实性更弱。"},{"word":"tell","ipa":"/tel/","tag":"pass information","definition":"to give information to someone in speech or writing. It is one-way and does not imply that the pieces form a connected account, which relate does.","definitionCN":"用口语或文字把信息给某人。它是单向传递，并不暗示各部分构成一个相互关联的整体，而 relate 有这层意思。"},{"word":"pertain","ipa":"/pəˈteɪn/","tag":"belong to, concern","definition":"to belong or be connected to a matter, used mostly of facts and formal contexts. It is narrower and more formal than relate to.","definitionCN":"属于或关联到某事项，多用于事实和正式语境。它比 relate to 更窄、更正式。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: Latin referre 'carry back', its suppletive participle relatus, and the English family relation, relationship, relative, related.","cn":"只用真实成分与真实同族词：拉丁语 referre“带回”、它的补充分词 relatus，以及英语词族 relation、relationship、relative、related。"},"normal":[{"en":"re- means 'back' and latus means 'carried': relate is literally 'carried back'. The first job of the word was to bring news home.","cn":"re- 意为“回”，latus 意为“被携带”：relate 字面上就是“被带回来”。这个词最早的工作就是把消息带回家。"},{"en":"relation came first (c. 1300) with the sense 'connection'; relate followed in the 1520s with 'tell'. The verb's relational senses are later growths.","cn":"relation 先出现（约 1300 年），意为“联系”；relate 于 16 世纪 20 年代才出现，意为“讲述”。动词的“关系”诸义是后来长出来的。"},{"en":"relate to = concern or empathize; be related to = be connected or be kin. Learners who mix them produce sentences that sound wrong even when the meaning is close.","cn":"relate to＝涉及或共鸣；be related to＝有联系或是亲属。混用这两个搭配，即使意思接近，句子也会显得不对。"},{"en":"The 1950 sense 'relate to a character' is psychology jargon that became everyday: the story is carried back into your own life.","cn":"1950 年出现的“对角色产生共鸣”原是心理学术语，后来成了日常说法：故事被带回你自己的生活里。"},{"en":"Compare with connect and associate: connect joins, associate associates in the mind, relate shows a meaningful correspondence and can also simply mean 'tell'.","cn":"与 connect、associate 对比：connect 是接上，associate 是在脑中联想，relate 显示有意义的对应，也可以只是“讲述”。"}],"abstract":[{"en":"Picture a messenger returning with a written report. The first thing he does is read it aloud; that is relate in its oldest sense.","cn":"想象一个信使带着书面报告回来。他做的第一件事是大声念出来——这就是 relate 最古老的意思。"},{"en":"Then he lays two pages side by side on the table and draws a line between them. The same word now means 'show a connection'.","cn":"然后他把两页纸并排铺在桌上，在中间画一条线。同一个词这时表示“显示联系”。"},{"en":"Finally the listener says, 'That is my story too.' The report has been carried all the way into another person's memory, which is the modern sense 'identify with'.","cn":"最后听者说：“那也是我的故事。”报告一路被带进了另一个人的记忆——这就是现代的“共鸣”义。"}]},"examples":[{"en":"The guide related the history of the temple in a low, steady voice.","cn":"向导用低沉平稳的声音讲述了这座寺庙的历史。"},{"en":"These symptoms are often related to lack of sleep.","cn":"这些症状常常与睡眠不足有关。"},{"en":"Good teachers relate new ideas to what students already know.","cn":"好老师会把新知识与学生已知的内容联系起来。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“瑞雷特”——瑞雷特把两家的旧事一件件讲给大家听，讲完还把事情串了起来 → relate 叙述；联系","word":"relate"},"root":"源自拉丁语 referre“带回、携回”的补充过去分词 relatus，核心是“把消息带回来，再把两样东西摆到一起”。","sensesIntro":{"en":"Nine senses of relate, all built on one movement: something is carried back, and then set beside something else so that a link becomes visible.","cn":"relate 的九个义项都建立在同一个动作上：某物被带回来，然后被放到另一物旁边，让一条联系显现出来。"},"semanticMap":{"core":{"en":"CORE IMAGE: a messenger brings something back and lays it beside another thing.","cn":"核心意象：信使把某物带回来，并把它放到另一件东西旁边。"},"chain":["CARRY BACK","TELL THE ACCOUNT","POINT AT A SUBJECT","LIE BESIDE ANOTHER","DRAW THE LINE","FEEL THE LINK"],"branches":[{"senses":"S1 · S2","en":"REPORTING: the carried message is spoken aloud, and it always points back at the matter it is about.","cn":"报告：被带回的消息被说出来，而它总是指向自己所讲述的那件事。"},{"senses":"S3 · S4","en":"CONNECTION: two things from one source lie side by side, and a speaker can deliberately place them together.","cn":"联系：来自同一源头的两样东西并排躺着，说话者也可以有意把它们摆到一起。"},{"senses":"S5","en":"ESTABLISHED LINK: the pairing becomes a formal, drawn correspondence between two sets of facts.","cn":"建立的关联：这种配对变成两组事实之间正式画出的一条对应线。"},{"senses":"S6","en":"KINSHIP: people are traced back to one ancestor, using the same 'brought back to a shared point' image.","cn":"亲属：人被回溯到一个共同的祖先，用的正是同一个“回到同一点”的意象。"},{"senses":"S7 · S8 · S9","en":"INWARD AND SOCIAL: the account is carried into one's own memory as sympathy, and between people as easy communication.","cn":"向内与向外：叙述被带进自己的记忆成为共鸣，也在人与人之间成为顺畅的交流。"}]},"affixes":{"intro":{"en":"Relate is a Latin verb whose participle came from another verb. English builds on it with -ed, -ion, -ship, -ive and -able, and also uses the Latin stem lat- in words such as translate and correlate.","cn":"relate 是一个拉丁动词，它的分词却来自另一个动词。英语用 -ed、-ion、-ship、-ive、-able 在它之上构词，也用拉丁词干 lat- 构成 translate、correlate 等词。"},"latinIntro":{"en":"The Latin family is referre 'carry back', its suppletive participle relatus 'carried back', the action noun relatio 'a bringing back, a report', and latus 'borne'. Relation, relative and translate all descend from this group.","cn":"拉丁词族包括 referre“带回”、其补充分词 relatus“被带回的”、行为名词 relatio“带回、报告”，以及 latus“被承载的”。relation、relative、translate 都出自这一组。"},"items":[{"word":"related","structure":"relate + -ed (past participle used as adjective)","meaning":"connected by family, origin, or subject","meaningCN":"有亲属关系的；相关的（-ed 构成形容词）","example":"The two languages are closely related.","exampleCN":"这两种语言关系很近。"},{"word":"relation","structure":"relat- (Latin relatus) + -ion (noun of action or result)","meaning":"a connection, or an account given in words","meaningCN":"关系；联系；叙述（-ion 构成行为或结果名词）","example":"The relation between the two events is still unclear.","exampleCN":"这两件事之间的关系仍不清楚。"},{"word":"relationship","structure":"relation + -ship (state or condition)","meaning":"the state of being connected, especially between people","meaningCN":"关系；人际关系（-ship 构成状态名词）","example":"They built a working relationship over ten years.","exampleCN":"他们用十年建立起了工作关系。"},{"word":"relative","structure":"relat- (Latin relatus) + -ive (adjective and noun)","meaning":"compared with something else; a family member","meaningCN":"相对的；亲属（-ive 构成形容词，也可作名词）","example":"He is a distant relative on my father's side.","exampleCN":"他是我父亲那边的远亲。"},{"word":"relatively","structure":"relative + -ly (adverb)","meaning":"in comparison with something else","meaningCN":"相对地；比较而言（-ly 构成副词）","example":"The test was relatively easy for most students.","exampleCN":"这次测验对多数学生来说相对容易。"},{"word":"relatable","structure":"relate + -able (capable of being)","meaning":"able to be identified with; easy to feel sympathy for","meaningCN":"能引起共鸣的；令人感同身受的（-able 构成形容词）","example":"Her story is relatable to anyone who has moved abroad.","exampleCN":"任何搬去过国外的人都能对她的故事产生共鸣。"},{"word":"interrelate","structure":"inter- (between, mutual) + relate","meaning":"to connect with one another mutually","meaningCN":"相互关联；相互作用（inter- 表示相互）","example":"Climate, soil, and crops interrelate in complex ways.","exampleCN":"气候、土壤与作物以复杂的方式相互关联。"},{"word":"unrelated","structure":"un- (not) + related","meaning":"not connected; not belonging to the same family","meaningCN":"无关的；无亲属关系的（un- 表示否定）","example":"The two complaints are unrelated to each other.","exampleCN":"这两起投诉彼此无关。"},{"word":"correlate","structure":"cor- (together, from com-) + relate","meaning":"to have or show a mutual relation","meaningCN":"相关；使相互关联（cor- 表示共同）","example":"Income correlates strongly with years of schooling.","exampleCN":"收入与受教育年限高度相关。"},{"word":"translate","structure":"trans- (across) + lat- (latus, carried) + -e","meaning":"to carry meaning across from one language to another","meaningCN":"翻译；转化（trans- 越过 + lat- 携带）","example":"The poem is hard to translate without losing its rhythm.","exampleCN":"这首诗很难在翻译时不丢掉节奏。"},{"word":"refer","structure":"re- (back) + fer (ferre, carry)","meaning":"to send back for information or decision; to mention","meaningCN":"把……转交；查询；提及（re- 回 + fer 携带，同出 referre）","example":"The doctor referred her to a specialist.","exampleCN":"医生把她转给了专科医生。"}],"latinEntries":[{"word":"relatus","structure":"suppletive past participle of referre, built on latus","meaning":"carried back; reported","meaningCN":"被带回的；被叙述的"},{"word":"referre","structure":"re- (back) + ferre (to carry)","meaning":"to carry back, bring back, report","meaningCN":"带回；携回；报告"},{"word":"relatio","structure":"relat- (carried back) + -io (action noun)","meaning":"a bringing back; a report, relation","meaningCN":"带回；报告；关系"},{"word":"latus","structure":"suppletive participle, origin disputed","meaning":"borne, carried","meaningCN":"被承载的；被携带的"}]}},{"word":"relevant","ipa_uk":"/ˈreləvənt/","ipa_us":"/ˈreləvənt/","definition_zh":"相关的；切题的；适用的；有现实意义的；有关的","definition_en":"closely connected with the matter being discussed, and therefore able to help or to be applied to it","core_image":"一只手把压在问题上的重物抬起来，让这件事变轻一点","scene":"In the interview she cut every anecdote that was not relevant to the job and kept only the two that showed how she handled a crisis.","sceneCN":"这里 relevant 是「切题的、与正题相关」（第 1 个义项：与正在讨论的事情直接相关）；句意：面试时她删掉了所有与这份工作无关的轶事，只留下两个能说明她如何处理危机的。场景要点：面试桌、摊开的简历、被划掉的段落、面试官点头的动作。","pos":[{"tag":"adj.","zh":"相关的；切题的；适用的；有现实意义的"}],"collocations":[{"phrase":"relevant to","zh":"与……相关；对……切题"},{"phrase":"highly relevant","zh":"高度相关的"},{"phrase":"relevant information","zh":"相关信息"},{"phrase":"relevant experience","zh":"相关经验"},{"phrase":"the relevant authorities","zh":"有关主管部门；有关方面"},{"phrase":"relevant to the case","zh":"与本案相关的"},{"phrase":"stay relevant","zh":"保持相关性；不被时代淘汰"}],"forms":[{"label":"比较级（更切题的）","form":"more relevant"}],"derivatives":[{"word":"relevance","pos":"n.","zh":"相关性；切题；现实意义"},{"word":"relevancy","pos":"n.","zh":"相关性（多用于法律与正式文体）"},{"word":"relevantly","pos":"adv.","zh":"相关地；切题地"},{"word":"irrelevant","pos":"adj.","zh":"不相关的；无关紧要的"},{"word":"irrelevance","pos":"n.","zh":"不相关；无关紧要"}],"senses":[{"no":"01","title":"To the point: pertinent to the matter","titleCN":"打在点上：切题、与正题相关","definition":"directly connected with the subject being discussed, so that it deserves to be considered","definitionCN":"与正在讨论的主题直接相连，因而值得被考虑","example":"Only three of the questions asked were relevant to the topic.","exampleCN":"所提的问题中只有三个与主题相关。","why":"The French word meant 'helpful'. A remark that helps the matter in hand is one that bears on it directly; 'helpful' narrows into 'to the point'.","whyCN":"这个词的法语原义是“有帮助的”。一句能帮上正在讨论之事的话，必然是直接落在事情上的话；于是“有帮助”收窄成了“切题”。"},{"no":"02","title":"Fits this case: applicable","titleCN":"对得上这件事：适用的","definition":"able to be applied to a particular case or situation, because the conditions match","definitionCN":"因条件相符而能应用于某一具体情况","example":"The rule is relevant only to contracts signed after 2020.","exampleCN":"这条规则只适用于 2020 年之后签订的合同。","why":"If a fact lifts part of the burden from this case, it must fit this case. Applicability is the practical face of being helpful.","whyCN":"如果一个事实能替这桩案子卸下一部分负担，它就必须对得上这桩案子。“适用”就是“有帮助”在实践中的一面。"},{"no":"03","title":"Still matters now: of present importance","titleCN":"此刻仍然要紧：有现实意义","definition":"important to the present time or situation rather than only to the past","definitionCN":"对当下或当前处境重要，而不只是对过去重要","example":"The novel's questions about surveillance are still relevant today.","exampleCN":"这部小说关于监视的追问在今天仍有现实意义。","why":"A helpful idea must help someone now. When the weight being lifted is today's problem, relevant means 'not obsolete'.","whyCN":"一个有用的想法必须在此刻帮到人。当被抬起的重量是今天的问题时，relevant 就表示“没有过时”。"},{"no":"04","title":"Lifts your own load: personally meaningful","titleCN":"减轻你自己的负担：对个人有切身意义","definition":"meaningful to a particular person because it speaks to that person's own life or needs","definitionCN":"对某个人有意义，因为它触及这个人自己的生活或需要","example":"The workshop felt relevant to young parents returning to work.","exampleCN":"这个工作坊让重返职场的年轻父母觉得与自己切身相关。","why":"The same relief can be felt by one person rather than by a whole debate. What lightens your own burden is, for you, relevant.","whyCN":"同一种“减负”可以由一个人感受到，而不是由整场讨论感受到。能减轻你自己负担的东西，对你来说就是 relevant。"},{"no":"05","title":"The oldest sense: helpful, of service","titleCN":"最古老的意思：有帮助、能派上用场","definition":"giving help or relief to the matter at hand, the word's original French sense","definitionCN":"给手头的事情提供帮助或缓解，这是该词最早的法语义","example":"Her calm summary was relevant in the chaos: it let the team think again.","exampleCN":"混乱中她那番冷静的归纳帮上了忙：它让团队重新思考。","why":"Medieval Latin relevare meant 'to raise, lighten, free from a burden'. A relevant thing is literally a thing that lifts weight off the problem.","whyCN":"中世纪拉丁语 relevare 意为“抬起、减轻、卸下负担”。relevant 的东西，字面上就是把重量从问题上抬走的东西。"},{"no":"06","title":"Admissible: relevant in law","titleCN":"可以进法庭：法律上的相关性","definition":"in law, having a tendency to prove or disprove a fact that matters to the case, and so admissible as evidence","definitionCN":"在法律上，能够证明或反驳对案件有意义的事实，因而可作为证据采纳","example":"The judge ruled that the old email was relevant and allowed it as evidence.","exampleCN":"法官裁定那封旧邮件具有相关性，允许作为证据。","why":"A court asks one question of every item: does it lighten or clarify the case? If it can move the fact in dispute, it is relevant and may be heard.","whyCN":"法庭对每份材料只问一件事：它能否让案子变轻或变清楚？如果它能推动争议事实，它就具有相关性，可以被听取。"},{"no":"07","title":"The office concerned: relevant authorities","titleCN":"管这件事的部门：有关主管方","definition":"in official usage, the body or person that has the duty to deal with a particular matter","definitionCN":"在官方用语中，指有职责处理某一事项的机构或人员","example":"The complaint was passed to the relevant authorities.","exampleCN":"投诉被转给了有关主管部门。","why":"Here the word points to whoever the matter bears on. The office that must carry the burden is the 'relevant' one, a fixed phrase in public notices.","whyCN":"这里这个词指向事情落在谁头上。必须承担这件事的部门就是“有关的”那个部门，是公告中的固定说法。"},{"no":"08","title":"Connected to real life: relevant education","titleCN":"接上真实生活：贴近实际的课程","definition":"in education, connected to pupils' lives and to the skills they will actually need","definitionCN":"在教育中，与学生的生活以及他们真正需要的技能相连","example":"The school made maths relevant by teaching it through household budgets.","exampleCN":"学校通过家庭预算来教数学，让这门课贴近实际。","why":"The burden a pupil feels is 'why learn this?'. Material that lifts that burden by connecting to daily life is called relevant.","whyCN":"学生感到的负担是“学这个有什么用”。能把这份负担卸下、与日常生活接上的材料，就被称为 relevant。"},{"no":"09","title":"Keep up with the times: stay relevant","titleCN":"跟上时代：保持相关性、不被淘汰","definition":"to keep adapting so that a person, brand, or institution still matters to present-day people","definitionCN":"持续调整，使个人、品牌或机构对当下的人仍然重要","example":"The old department store stayed relevant by opening small local shops.","exampleCN":"那家老百货通过开设社区小店，保持着自身的存在感。","why":"When 'now' changes, what lifted yesterday's burden may lift nothing today. Staying relevant means continuing to be the thing that helps the present.","whyCN":"当“现在”改变，昨天能减负的东西今天可能什么也减不了。保持 relevant，就是继续做那个对当下有帮助的东西。"}],"etymology":{"intro":{"en":"Relevant is often mistaken for a relative of relate. It is not. Etymonline traces it through French relevant to Latin relevare 'to lift, lighten', the same verb behind relieve. The word was recorded in the 1550s but did not come into general use until after 1800. Dates are approximate.","cn":"relevant 常被误认为是 relate 的同族词，其实不是。etymonline 把它经法语 relevant 追溯到拉丁语 relevare“抬起、减轻”，也就是 relieve 背后的同一个动词。该词 16 世纪 50 年代已有记录，但直到 1800 年以后才普遍使用。年代为大致估计。"},"items":[{"era":"1550s","en":"First recorded in English as 'to the purpose, applicable, pertinent to the matter at hand'. Etymonline adds that it was 'not generally used until after 1800'.","cn":"英语最早记录为“合乎目的、适用、与手头之事相关”。etymonline 补充说它“直到 1800 年以后才普遍使用”。"},{"era":"OLD FRENCH","en":"From French relevant 'depending upon', originally 'helpful'. The French adjective came from the present participle stem of relever, 'to raise, relieve'.","cn":"来自法语 relevant“取决于”，原义为“有帮助的”。这个法语形容词出自 relever“抬起、减轻”的现在分词词干。"},{"era":"MEDIEVAL LATIN","en":"Medieval Latin relevantem (nominative relevans) is the present participle of relevare. Its literal sense is 'raising up', and its practical sense is 'helping, assisting, comforting'.","cn":"中世纪拉丁语 relevantem（主格 relevans）是 relevare 的现在分词。字面义是“抬起”，实际义是“帮助、援助、安慰”。"},{"era":"LATIN relevare","en":"Relevare meant 'to raise, alleviate, lift up, free from a burden'. It is re-, here perhaps intensive, + levare 'to lift up, lighten'.","cn":"relevare 意为“抬起、缓解、举起、卸下负担”。它由 re-（此处或为加强前缀）+ levare“抬起、减轻”构成。"},{"era":"levare / levis","en":"Levare comes from levis 'not heavy', from PIE *legwh- 'not heavy, having little weight'. The root is about weight, not about carrying or referring.","cn":"levare 来自 levis“不重的”，再上溯原始印欧语 *legwh-“不重、重量很小”。这个词根讲的是重量，而不是携带或指称。"},{"era":"1680s / MODERN","en":"Irrelevant is recorded from the 1680s, from in- 'not' + relevant. Fowler pointed out that irrelevant and relieving are historically the same word: what does not relieve the matter in hand throws no light on it.","cn":"irrelevant 记录于 17 世纪 80 年代，由 in-“不”+ relevant 构成。Fowler 指出，irrelevant 与 relieving 在历史上是同一个词：不能替手头之事减负的东西，也就照不亮它。"}]},"similar":{"note":{"en":"The first group is about origin: relevant belongs with relieve and relief, NOT with relate. The second group is about meaning: related says 'connected', pertinent says 'exactly on the point', applicable says 'usable in this case', irrelevant says 'not connected at all'.","cn":"第一组讲词源：relevant 与 relieve、relief 同族，而与 relate 不同源。第二组讲词义：related 是“有联系的”，pertinent 是“正打在点上的”，applicable 是“可适用于此的”，irrelevant 是“完全不相干的”。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"relieve","ipa":"/rɪˈliːv/","tag":"same Latin verb","definition":"to lessen pain or burden. It comes from the same Latin relevare as relevant, so the two are true relatives even though they look different.","definitionCN":"减轻痛苦或负担。它与 relevant 同出拉丁语 relevare，因此虽外形不同，却是真正的同族词。"},{"word":"relief","ipa":"/rɪˈliːf/","tag":"noun of the same family","definition":"the feeling or fact of a burden being lifted. It keeps the literal 'lightening' image that also lies under relevant.","definitionCN":"负担被卸下时的感觉或事实。它保留了同样藏在 relevant 底下的“变轻”意象。"},{"word":"relate","ipa":"/rɪˈleɪt/","tag":"false relative","definition":"to tell or to connect, from Latin referre 'carry back'. It is NOT the source of relevant: the two only share the re- prefix.","definitionCN":"叙述或联系，来自拉丁语 referre“带回”。它并不是 relevant 的来源：两者只共用 re- 这一前缀。"},{"word":"relative","ipa":"/ˈrelətɪv/","tag":"belongs to relate","definition":"a family member, or 'compared with something else'. It comes down the referre line, so it is not a relative of relevant either.","definitionCN":"亲属，或“相对的”。它出自 referre 这一线，所以也不是 relevant 的同族词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"related","ipa":"/rɪˈleɪtɪd/","tag":"merely connected","definition":"connected in some way, by family, origin, or subject. It is broader and weaker than relevant: two facts can be related without either helping the question.","definitionCN":"以某种方式相连，或因家庭、来源、主题相连。它比 relevant 更宽也更弱：两件事可以“有联系”，却都对问题没有帮助。"},{"word":"pertinent","ipa":"/ˈpɜːtɪnənt/","tag":"exactly on the point","definition":"directly and precisely to the point. It is sharper than relevant: pertinent remarks hit the very question, while relevant ones merely bear on it.","definitionCN":"直接而准确地对准要点。它比 relevant 更锐利：pertinent 的话正中问题本身，relevant 的话只是落在问题上。"},{"word":"applicable","ipa":"/əˈplɪkəbl/","tag":"usable in this case","definition":"able to be put into use in a particular situation. It stresses usefulness in practice, while relevant can also mean 'important to the discussion'.","definitionCN":"能在某一具体情况中投入使用。它强调实践中的可用性，而 relevant 也可指“对讨论重要”。"},{"word":"irrelevant","ipa":"/ɪˈreləvənt/","tag":"opposite","definition":"not connected with the matter at hand and therefore of no help. It is the direct negation of relevant, recorded from the 1680s.","definitionCN":"与手头之事无关，因而帮不上忙。它是 relevant 的直接否定，记录于 17 世纪 80 年代。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: Latin relevare 'lift, lighten', levare, levis 'light', and the English family relieve, relief, relevance, irrelevant.","cn":"只用真实成分与真实同族词：拉丁语 relevare“抬起、减轻”、levare、levis“轻的”，以及英语词族 relieve、relief、relevance、irrelevant。"},"normal":[{"en":"relevant comes from relevare 'to lift a burden', the same verb as relieve. It is not built on relate, despite the shared re-.","cn":"relevant 出自 relevare“卸下负担”，与 relieve 是同一个动词。尽管共用 re-，它并不是由 relate 构成的。"},{"en":"The root is levis 'light', from PIE *legwh-. A relevant fact is one that makes the problem lighter.","cn":"词根是 levis“轻的”，来自原始印欧语 *legwh-。一个 relevant 的事实，就是能让问题变轻的事实。"},{"en":"The word is recorded in the 1550s but only became common after 1800, which is why it feels more modern than relate.","cn":"这个词 16 世纪 50 年代已有记录，但 1800 年以后才通行，所以它感觉比 relate 更现代。"},{"en":"Fowler's line is worth keeping: irrelevant and relieving are the same word — what does not relieve the matter throws no light on it.","cn":"Fowler 那句话值得记住：irrelevant 与 relieving 是同一个词——不能替事情减负的东西，也照不亮它。"},{"en":"related means 'connected'; relevant means 'connected in a way that helps'. That is why a related fact can still be irrelevant.","cn":"related 是“有联系”；relevant 是“联系得帮上忙”。正因如此，一个“相关”的事实仍可能是不切题的。"}],"abstract":[{"en":"Picture a hand lifting a heavy stone off a document so that the words underneath can be read. Relevant is that lifting hand.","cn":"想象一只手把压在文件上的石头抬开，让下面的字能读出来。relevant 就是那只抬起重物的手。"},{"en":"The stone may be a confusion, a doubt, or a pile of unimportant details. Anything that lifts it is relevant, whether it is a fact, an example, or a question.","cn":"那块石头可能是一团混乱、一个疑问，或一堆无关紧要的细节。任何能把它抬走的东西都是 relevant，无论是一个事实、一个例子还是一个提问。"},{"en":"When nothing is lifted, the word flips to irrelevant — the same hand, doing nothing.","cn":"当什么也没被抬起，这个词就翻转成 irrelevant——同一只手，什么也没做。"}]},"examples":[{"en":"Please keep your comments relevant to the proposal on the table.","cn":"请让您的发言与桌上这份提案相关。"},{"en":"Her experience in rural clinics was directly relevant to the job.","cn":"她在乡村诊所的经验与这份工作直接相关。"},{"en":"The committee asked the relevant authorities to explain the delay.","cn":"委员会要求有关主管部门解释延误的原因。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“瑞乐万”——瑞乐万每句话都正好替大家卸下一个难题 → relevant 相关的、切题的","word":"relevant"},"root":"源自拉丁语 relevare“抬起、减轻负担”（re- + levare“举起”），与 relieve 同族，而与 relate 不同源，核心是“能替这件事减负、所以切题”。","sensesIntro":{"en":"Nine senses of relevant, all built on one gesture: something lifts weight off the matter in hand, and so earns a place in the discussion.","cn":"relevant 的九个义项都建立在同一个动作上：某物替手头的事情抬起重量，因此有资格进入讨论。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand lifts a weight off the problem, and the problem becomes lighter.","cn":"核心意象：一只手把重量从问题上抬起，问题因此变轻。"},"chain":["LIFT","LIGHTEN","HELP","BEAR ON THE MATTER","FIT THE CASE","STILL MATTER"],"branches":[{"senses":"S1 · S2","en":"ON THE POINT: what helps must bear on the question, and it must fit the case being discussed.","cn":"落在点上：能帮忙的东西必须落在问题上，也必须对得上正在讨论的这件事。"},{"senses":"S3 · S4","en":"WEIGHT LIFTED NOW: the relief can be for the present moment, or for one particular person's own load.","cn":"此刻被卸下的重量：这种减负可以针对当下，也可以针对某一个人自己的负担。"},{"senses":"S5","en":"ORIGINAL HELP: the oldest sense is simply 'of service', the literal relief the Latin verb names.","cn":"原初的帮助：最古老的意思就是“能派上用场”，即拉丁动词字面所说的“减负”。"},{"senses":"S6 · S7","en":"INSTITUTIONS: a court asks whether an item lightens the case; an office is 'relevant' when the matter falls to it.","cn":"机构：法庭问一份材料能否让案子变轻；当事情落到某个部门头上，那个部门就是“有关的”。"},{"senses":"S8 · S9","en":"EVERYDAY RELEVANCE: lessons must lighten the 'why learn this' burden, and a brand must keep lightening today's needs.","cn":"日常的相关性：课程要卸下“学这个有什么用”的负担，品牌要持续卸下当下的需求。"}]},"affixes":{"intro":{"en":"Relevant is a present participle turned adjective: Latin relevare + -ant. English adds -ance, -ancy, -ly, and the negative in-. The stem lev- 'light' also appears in elevate and lever.","cn":"relevant 是由现在分词转成的形容词：拉丁语 relevare + -ant。英语再加上 -ance、-ancy、-ly 和否定前缀 in-。词干 lev-“轻”也出现在 elevate、lever 中。"},"latinIntro":{"en":"The Latin family is relevare 'lift, relieve', levare 'to lift', levis 'light', and relevans 'lifting, helping'. Relieve and relief descend from the same verb, which is why relevant is NOT related to relate.","cn":"拉丁词族包括 relevare“抬起、减轻”、levare“举起”、levis“轻的”，以及 relevans“抬起、帮助”。relieve 与 relief 出自同一个动词，这正是 relevant 与 relate 不同源的原因。"},"items":[{"word":"relevance","structure":"relevant + -ance (noun of state)","meaning":"the quality of being connected to the matter in hand","meaningCN":"相关性；切题（-ance 构成状态名词）","example":"The judge questioned the relevance of the photograph.","exampleCN":"法官质疑那张照片的相关性。"},{"word":"relevancy","structure":"relevant + -ancy (noun of state)","meaning":"the same as relevance, used chiefly in law and formal writing","meaningCN":"相关性（与 relevance 同义，主要用于法律与正式文体）","example":"Counsel disputed the relevancy of the witness's answer.","exampleCN":"律师对证人回答的相关性提出异议。"},{"word":"relevantly","structure":"relevant + -ly (adverb)","meaning":"in a way that bears on the matter","meaningCN":"相关地；切题地（-ly 构成副词）","example":"He spoke briefly and relevantly.","exampleCN":"他发言简短而切题。"},{"word":"irrelevant","structure":"ir- (in-, not) + relevant","meaning":"not connected with the matter and of no help","meaningCN":"不相关的；无关紧要的（ir- 是否定前缀）","example":"The colour of the car is irrelevant to the accident.","exampleCN":"车的颜色与这起事故无关。"},{"word":"irrelevance","structure":"ir- + relevance","meaning":"the state of being unrelated to the matter","meaningCN":"不相关；无关紧要（ir- + relevance）","example":"The report was criticized for its irrelevance to local needs.","exampleCN":"这份报告因与本地需求无关而受到批评。"},{"word":"relieve","structure":"re- (intensive) + lieve (levare, to lift)","meaning":"to lessen pain, burden, or pressure","meaningCN":"减轻；缓解（re- 加强 + lieve 抬起）","example":"The medicine relieved her headache within an hour.","exampleCN":"这种药一小时内缓解了她的头痛。"},{"word":"relief","structure":"Old French relief, from relever 'to raise, relieve'","meaning":"the lessening of pain or burden","meaningCN":"宽慰；缓解；救济（经古法语 relief 来自 relever）","example":"The news brought relief to the whole village.","exampleCN":"这个消息让整个村子松了一口气。"},{"word":"relevant","structure":"relev- (Latin relevare) + -ant (present participle adjective)","meaning":"bearing on the matter in hand","meaningCN":"切题的；相关的（-ant 构成现在分词形容词）","example":"Only relevant facts were allowed into the record.","exampleCN":"只有相关事实被允许记入记录。"},{"word":"elevate","structure":"e- (ex-, out, up) + lev- (levare, lift) + -ate","meaning":"to raise to a higher position","meaningCN":"提升；举起（e- 向上 + lev- 举起）","example":"The platform elevated the speaker above the crowd.","exampleCN":"这个平台把演讲者升到人群之上。"},{"word":"lever","structure":"lev- (levare, to lift) + -er (instrument)","meaning":"a bar used to lift or move something","meaningCN":"杠杆；撬棒（lev- 举起 + -er 工具）","example":"He used a long lever to lift the stone.","exampleCN":"他用一根长杠杆撬起那块石头。"},{"word":"alleviate","structure":"al- (ad-, to) + levi- (levis, light) + -ate","meaning":"to make pain or a problem less severe","meaningCN":"减轻；缓和（al- 向 + levi- 轻 + -ate）","example":"The new drainage system alleviated the flooding.","exampleCN":"新的排水系统缓解了积水问题。"}],"latinEntries":[{"word":"relevare","structure":"re- (intensive) + levare (to lift)","meaning":"to raise, lighten, free from a burden","meaningCN":"抬起；减轻；卸下负担"},{"word":"levare","structure":"from levis 'light'","meaning":"to lift up, raise","meaningCN":"举起；抬起"},{"word":"levis","structure":"PIE *legwh- 'not heavy'","meaning":"light in weight","meaningCN":"轻的；重量小的"},{"word":"relevans","structure":"present participle of relevare","meaning":"lifting, helping","meaningCN":"抬起中的；有帮助的"}]}},{"word":"reliable","ipa_uk":"/rɪˈlaɪəbl/","ipa_us":"/rɪˈlaɪəbl/","definition_zh":"可靠的；可信赖的；稳定不出故障的；准确可信的；经久耐用的","definition_en":"able to be trusted or depended on, because it works, behaves, or reports consistently and does not fail","core_image":"一根被反复拉紧却始终不断的绳子，全部重量压上去也不会松脱","scene":"When the storm cut the power, the hospital switched to its reliable backup generator without losing a single ventilator.","sceneCN":"这里 reliable 是「稳定可靠、不出故障」（第 2 个义项：机器或系统每次都能正常工作）；句意：暴风雨切断电源时，医院切换到那台可靠的备用发电机，没有一台呼吸机断电。场景要点：漆黑的走廊、亮起的应急灯、轰鸣的发电机、仍在运转的呼吸机。","pos":[{"tag":"adj.","zh":"可靠的；可信赖的；稳定可靠的；准确可信的"}],"collocations":[{"phrase":"reliable source","zh":"可靠的消息来源"},{"phrase":"reliable information","zh":"可靠的信息"},{"phrase":"a reliable person","zh":"可靠的人"},{"phrase":"highly reliable","zh":"高度可靠的"},{"phrase":"a reliable estimate","zh":"可靠的估计"},{"phrase":"reliable service","zh":"稳定可靠的服务"},{"phrase":"prove reliable","zh":"证明是可靠的"}],"forms":[{"label":"比较级（更可靠的）","form":"more reliable"}],"derivatives":[{"word":"reliability","pos":"n.","zh":"可靠性；可信度"},{"word":"reliably","pos":"adv.","zh":"可靠地；稳妥地"},{"word":"unreliable","pos":"adj.","zh":"不可靠的；不可信的"},{"word":"unreliability","pos":"n.","zh":"不可靠；不可信"},{"word":"reliant","pos":"adj.","zh":"依赖的；依靠的"}],"senses":[{"no":"01","title":"A person you can lean on","titleCN":"可以托付的人：可信赖的","definition":"of a person, consistently honest and dependable, so that others can trust what they say and do","definitionCN":"指人一贯诚实可靠，别人可以相信其言行","example":"She is the most reliable colleague I have ever worked with.","exampleCN":"她是我共事过的最可靠的同事。","why":"Latin religare meant 'to bind fast'. A reliable person is one you can tie your plans to: the bond holds even when something pulls at it.","whyCN":"拉丁语 religare 意为“绑紧”。一个 reliable 的人，就是你可以把计划拴在其身上的人：即使有外力拉扯，这个结也不会松。"},{"no":"02","title":"A machine that does not fail","titleCN":"不会掉链子的机器：稳定可靠","definition":"of a device, system, or service, working well every time it is needed, without breakdowns","definitionCN":"指设备、系统或服务每次需要时都能正常工作，不出故障","example":"The lab relies on a reliable freezer to keep samples at minus eighty.","exampleCN":"实验室靠一台可靠的冰柜把样本保持在零下八十度。","why":"The binding image moves from people to objects: a machine is reliable when its parts stay fastened together under load, so it can be depended on at any moment.","whyCN":"“绑紧”的意象从人转到物：一台机器可靠，就是它的部件在负荷下始终扣在一起，因此任何时候都能指望它。"},{"no":"03","title":"Numbers you can act on","titleCN":"可以据以行动的数据：准确可信","definition":"of information, data, or a report, accurate and trustworthy enough to be used for decisions","definitionCN":"指信息、数据或报告准确可信，足以用来做决定","example":"We need reliable figures before we set the budget.","exampleCN":"定预算之前，我们需要可靠的数据。","why":"If you bind a decision to a number, the number must not slip. Reliable information is information that carries the weight of a decision without breaking.","whyCN":"如果你把一个决定拴在一个数字上，这个数字就不能滑脱。可靠的信息，就是能承受一个决定的重量而不折断的信息。"},{"no":"04","title":"The same person every day","titleCN":"每天都一样的人：一贯守约","definition":"behaving in the same good way over time, keeping promises and meeting obligations","definitionCN":"长期保持同样良好的行为，守承诺、尽义务","example":"His reliable habit of arriving ten minutes early steadied the whole team.","exampleCN":"他每天早到十分钟的可靠习惯，让整个团队都安定下来。","why":"Reliability is not one strong pull but many repeated pulls. The bond is proven by holding the same way day after day.","whyCN":"可靠不是拉一次很用力，而是许多次反复的拉。这个结是靠日复一日保持同样的紧度而被证明的。"},{"no":"05","title":"Built to last: durable quality","titleCN":"做得经得住用：质量可靠、耐用","definition":"of goods or materials, well made and durable, not likely to break or wear out quickly","definitionCN":"指货物或材料做工扎实、耐用，不容易坏或很快磨损","example":"These boots are reliable enough for three winters on the farm.","exampleCN":"这双靴子够结实，能在农场熬过三个冬天。","why":"A durable object keeps its parts bound together through wear. The same fastening that makes a person trustworthy makes a thing long-lasting.","whyCN":"耐用的物件在磨损中仍让各部件牢牢相连。使一个人可信的那种“绑紧”，同样使一件东西经久。"},{"no":"06","title":"The same result twice: statistical reliability","titleCN":"两次结果相同：测量信度","definition":"in statistics and testing, producing consistent results when repeated, so that the measurement can be trusted","definitionCN":"在统计与测试中，重复时产生一致结果，因而测量可信","example":"The scale's reliability was checked by weighing the same sample five times.","exampleCN":"通过五次称量同一样本，检验了这台秤的信度。","why":"A measurement is reliable when repeated trials 'bind' to the same value. Consistency across repetitions is the technical form of not slipping.","whyCN":"一个测量可靠，就是重复试验都“绑”到同一个值上。跨重复的一致性，就是“不滑脱”的技术形态。"},{"no":"07","title":"A forecast you can plan on","titleCN":"可以据此安排的计划：有把握的估计","definition":"of an estimate, forecast, or prediction, close enough to the truth to be used with confidence","definitionCN":"指估计、预报或预测足够接近事实，可以放心采用","example":"The survey gives a reliable estimate of how many households will move.","exampleCN":"这项调查对将有多少家庭搬迁给出了可靠的估计。","why":"A forecast is a rope thrown into the future. If the rope holds when the future arrives, the estimate was reliable.","whyCN":"预测是一根抛向未来的绳子。若未来到来时这根绳仍拉得住，这个估计就是可靠的。"},{"no":"08","title":"Old reliable: the dependable stand-by","titleCN":"可靠的老伙计：名词用法","definition":"as a noun, a person or thing that has proved dependable over time, often in the phrase old reliable","definitionCN":"作名词，指经过时间检验而可靠的人或物，常见于 old reliable 这一说法","example":"When the new app crashed, everyone turned to old reliable: the paper roster.","exampleCN":"新应用崩溃时，大家都转向可靠的老办法：纸质名册。","why":"English began using reliable as a noun by 1890, usually with old. The adjective's 'thing that holds' becomes a name for the stand-by you reach for when everything else fails.","whyCN":"英语在 1890 年前后开始把 reliable 用作名词，通常与 old 连用。形容词所指的“拉得住的东西”，变成了别的东西都失灵时你会去抓的那个老依靠。"},{"no":"09","title":"A sign that does not lie","titleCN":"不会骗人的迹象：可靠的指标","definition":"of a sign, symptom, or indicator, consistently pointing to the true state of something","definitionCN":"指迹象、症状或指标始终指向事物的真实状态","example":"A steady drop in pressure is a reliable sign that a tyre is leaking.","exampleCN":"气压持续下降是轮胎漏气的可靠迹象。","why":"An indicator is a rope between what you see and what is true. If that rope holds every time, the sign is reliable.","whyCN":"指标是你所见与真实情况之间的一根绳。如果这根绳每次都拉得住，这个迹象就是可靠的。"}],"etymology":{"intro":{"en":"Reliable is rely + -able, but the date usually given needs care: it is recorded from the 1560s in Scottish writing, not the nineteenth century. It was rare before 1850 and was then attacked in Britain as an Americanism. Dates are approximate.","cn":"reliable 由 rely + -able 构成，但常见年代需要修正：它最早记录于 16 世纪 60 年代的苏格兰文献，而不是 19 世纪。它在 1850 年以前很少见，之后在英国被指为美国用法而受到批评。年代为大致估计。"},"items":[{"era":"1560s","en":"First recorded as Scottish raliabill, 'that may be relied on, fit to be depended on, trustworthy'.","cn":"最早以苏格兰拼写 raliabill 记录，意为“可以被依靠的、值得信赖的、可信的”。"},{"era":"rely + -able","en":"The word is rely plus the suffix -able. Rely itself dates from the mid-14c., originally 'to gather, assemble' an army, then 'to attach one's trust to' from the 1570s.","cn":"这个词是 rely 加后缀 -able。rely 本身始于 14 世纪中期，原义为“集结、聚集”军队，16 世纪 70 年代起才表示“把信任系于”。"},{"era":"OLD FRENCH","en":"Rely comes from Old French relier 'assemble, put together; fasten, fasten again, attach, rally, oblige'.","cn":"rely 来自古法语 relier“聚集、拼合；系紧、重新系上、附着、集结、使承担义务”。"},{"era":"LATIN religare","en":"Old French relier goes back to Latin religare 'fasten, bind fast', from re-, here perhaps intensive, + ligare 'to bind'. Religion comes from the same verb, though its sense has long since split away.","cn":"古法语 relier 可追溯到拉丁语 religare“系紧、绑牢”，由 re-（此处或为加强前缀）+ ligare“捆绑”构成。religion 出自同一个动词，但其词义早已分叉。"},{"era":"ligare / PIE *leig-","en":"Ligare 'to bind' goes back to PIE *leig- 'to tie, bind'. The same root gives league, liable, and ligament, all words about being tied to something.","cn":"ligare“捆绑”可追溯到原始印欧语 *leig-“系、捆”。同一词根还给出 league、liable、ligament，都是“被系在某物上”的词。"},{"era":"1850 / 1890","en":"Not common before 1850; British critics then called it an Americanism because -able was used differently from provable. OED and others defended it through available and dependable. The noun use 'a reliable person or thing' appears by 1890.","cn":"1850 年前不常见；此后英国批评者称它为美国用法，因为 -able 的用法与 provable 不同。OED 等以 available、dependable 为例为它辩护。名词用法“可靠的人或物”于 1890 年前后出现。"}]},"similar":{"note":{"en":"Group one keeps the family apart: rely is the verb, reliance the noun of trusting, reliability the quality, reliant the adjective of depending. Group two compares the adjectives learners mix up. Note that reliable describes the thing trusted, not the person trusting.","cn":"第一组区分同族词：rely 是动词，reliance 是“信赖”这一名词，reliability 是“可靠性”这一性质，reliant 是“依赖的”形容词。第二组比较学习者容易混用的形容词。注意 reliable 形容“被信赖的那一方”，而不是“去信赖的人”。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"rely","ipa":"/rɪˈlaɪ/","tag":"verb","definition":"to depend on someone or something with trust. It is the action; reliable describes the quality that makes that action safe.","definitionCN":"带着信任依靠某人或某物。它是动作；reliable 描述使这个动作安全的那种性质。"},{"word":"reliance","ipa":"/rɪˈlaɪəns/","tag":"noun: the act of trusting","definition":"the state of depending on someone or something. It names the dependence, while reliable names the fitness to be depended on.","definitionCN":"依赖某人或某物的状态。它指“依赖”本身，而 reliable 指“值得被依赖”的资质。"},{"word":"reliability","ipa":"/rɪˌlaɪəˈbɪləti/","tag":"noun: the quality","definition":"the quality of being reliable, or the consistency of a measurement. It is the abstract noun, recorded from 1816.","definitionCN":"可靠的性质，或测量的一致性。它是抽象名词，记录于 1816 年。"},{"word":"reliant","ipa":"/rɪˈlaɪənt/","tag":"adjective: depending","definition":"depending on someone or something. It points outward from the dependent party, the reverse direction of reliable.","definitionCN":"依赖某人或某物的。它从依赖者一方指向外，方向与 reliable 相反。"}]},{"heading":"NEAR MEANING","entries":[{"word":"dependable","ipa":"/dɪˈpendəbl/","tag":"never lets you down","definition":"able to be depended on, especially in a practical way. It is close to reliable but sounds more like a judgement of character or performance than of technical consistency.","definitionCN":"可以被依靠的，尤其在实际层面。它接近 reliable，但更像是对人品或表现的判断，而不是技术上的稳定性。"},{"word":"trustworthy","ipa":"/ˈtrʌstwɜːði/","tag":"deserving trust","definition":"deserving to be trusted, usually of a person's honesty. It is moral where reliable is often functional: a reliable bus may not be trustworthy with secrets.","definitionCN":"值得信任的，通常指人的诚实。它偏道德评价，而 reliable 常是功能性的：一辆可靠的公交车未必能替你保守秘密。"},{"word":"consistent","ipa":"/kənˈsɪstənt/","tag":"same every time","definition":"always behaving or producing results in the same way. It stresses sameness over time; reliable adds the judgement that this sameness can be safely used.","definitionCN":"始终以同样方式行事或产生同样结果。它强调时间上的一致；reliable 则多一层判断：这种一致可以放心采用。"},{"word":"unfailing","ipa":"/ʌnˈfeɪlɪŋ/","tag":"never failing","definition":"never failing or weakening, used of support, supply, or effort. It is stronger and more emotional than reliable.","definitionCN":"从不失效或减弱的，多用于支持、供应或努力。它比 reliable 更强，也更带感情。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: rely + -able, Latin religare 'bind fast', ligare 'bind', and the English family reliance, reliability, reliant, religion.","cn":"只用真实成分与真实同族词：rely + -able、拉丁语 religare“绑紧”、ligare“捆绑”，以及英语词族 reliance、reliability、reliant、religion。"},"normal":[{"en":"rely + -able = 'able to be relied on'. The suffix does not mean 'having the quality' here but 'fit to be —', as in available and dependable.","cn":"rely + -able＝“可以被依靠的”。这里的后缀不表示“具有某种性质”，而表示“适合被……”，如同 available 与 dependable。"},{"en":"The root is Latin religare 'bind fast'. A reliable thing is something you can tie your plans to without the knot slipping.","cn":"词根是拉丁语 religare“绑紧”。一个 reliable 的东西，就是你可以把计划拴上去而结不会滑脱的东西。"},{"en":"religion shares the same root but has long since split off. Do not derive reliable from religion: the modern senses are far apart.","cn":"religion 同根，但早已分叉。不要把 reliable 归到 religion 名下：两者的现代词义相去甚远。"},{"en":"Dates: rely mid-14c., reliable 1560s in Scotland, reliability 1816, common use after 1850. The '19th century' date usually quoted is the spread, not the first record.","cn":"年代：rely 14 世纪中期，reliable 16 世纪 60 年代见于苏格兰，reliability 1816 年，1850 年后才通行。常说的“19 世纪”是它普及的年代，不是最早记录。"},{"en":"reliable describes the thing trusted; reliant describes the one trusting. A reliable bridge and a reliant village are opposite ends of the same relation.","cn":"reliable 形容被信赖的那一方；reliant 形容去依赖的那一方。可靠的桥与依赖这座桥的村庄，是同一关系相反的两端。"}],"abstract":[{"en":"Picture a rope tied to a ring in a wall. The test is not how it looks but whether it holds when a whole person hangs from it.","cn":"想象一根绳子系在墙上的铁环上。检验的不是它看起来怎样，而是整个人吊上去时它是否还拉得住。"},{"en":"People, machines, numbers, and goods are all tested the same way: put weight on the connection and see whether it slips.","cn":"人、机器、数字和货物都接受同样的检验：把重量压到那根连接上，看它会不会滑脱。"},{"en":"A reliable thing is not exciting. It is simply still there, still holding, on the day you need it.","cn":"可靠的东西并不令人兴奋。它只是在你需要的那天，仍然在那里，仍然拉得住。"}]},"examples":[{"en":"We need a reliable courier who will not lose the samples.","cn":"我们需要一位不会弄丢样本的可靠快递员。"},{"en":"The old clock is not beautiful, but it is reliable.","cn":"那座老钟不好看，但走得很准。"},{"en":"Always check whether the source of the statistic is reliable.","cn":"一定要核查这个统计数据的来源是否可靠。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“瑞来宝”——瑞来宝这块招牌几十年没塌过，有事找它准没错 → reliable 可靠的","word":"reliable"},"root":"由 rely（古法语 relier < 拉丁语 religare“绑紧、捆牢”）加 -able 构成，核心是“拴得住、拉不断”。","sensesIntro":{"en":"Nine senses of reliable, all built on one test: put weight on the connection and see whether it holds — for a person, a machine, a number, a habit, a product, a measurement, a forecast, an old stand-by, or a sign.","cn":"reliable 的九个义项都建立在同一种检验上：把重量压到那根连接上，看它是否拉得住——对象可以是人、机器、数字、习惯、产品、测量、预报、老依靠或迹象。"},"semanticMap":{"core":{"en":"CORE IMAGE: a knot that holds when the full weight is hung on it.","cn":"核心意象：全部重量吊上去也不会松开的结。"},"chain":["BIND FAST","HOLD UNDER LOAD","NOT SLIP","BE COUNTED ON","SAME RESULT AGAIN","TRUSTED STAND-BY"],"branches":[{"senses":"S1 · S4","en":"PEOPLE: trust in a person is a bond that holds through temptation and through repetition, day after day.","cn":"人：对人的信任是一根结，能经受诱惑，也能经受日复一日的重复。"},{"senses":"S2 · S5","en":"OBJECTS: a machine or a product proves reliable by keeping its parts fastened under load and wear.","cn":"物：机器或产品靠部件在负荷与磨损中始终相连，证明自己可靠。"},{"senses":"S3 · S9","en":"EVIDENCE: numbers, reports, and signs are reliable when the link between what is shown and what is true does not slip.","cn":"证据：数据、报告与迹象之所以可靠，是因为“所显示的”与“真实的”之间那根连接不会滑脱。"},{"senses":"S6 · S7","en":"REPETITION AND FUTURE: the same result twice is reliability in measurement; a rope that holds into the future is a reliable forecast.","cn":"重复与未来：两次结果相同是测量上的信度；一根拉向未来仍不松的绳，就是可靠的预报。"},{"senses":"S8","en":"THE STAND-BY: the quality hardens into a name for the old thing you reach for when everything else fails.","cn":"老依靠：这种性质凝固成一个名字，指别的东西都失灵时你会去抓的那件旧物。"}]},"affixes":{"intro":{"en":"Reliable is rely plus -able, and the Latin stem is relig- 'bind'. The same root reaches English through religion, league, liable, and ligament, while -ability and un- build the abstract and negative forms.","cn":"reliable 是 rely 加 -able，拉丁词干为 relig-“捆绑”。同一词根还通过 religion、league、liable、ligament 进入英语，而 -ability 与 un- 构成抽象名词和否定形式。"},"latinIntro":{"en":"The Latin family is religare 'bind fast', ligare 'to bind', and ligamen 'a band'. Religion belongs here too, from religare in the sense of binding a person to obligation; its modern sense split off long ago.","cn":"拉丁词族包括 religare“绑紧”、ligare“捆绑”、ligamen“束带”。religion 也属于这里，出自 religare“把人绑在义务上”的意思；它的现代词义早已分叉。"},"items":[{"word":"reliable","structure":"rely + -able (fit to be ——)","meaning":"fit to be relied on; trustworthy","meaningCN":"可以被依靠的；可信赖的（-able 表示“适合被……”）","example":"This is the most reliable route into the valley.","exampleCN":"这是进山谷最可靠的一条路线。"},{"word":"reliability","structure":"reliable + -ity (noun of quality)","meaning":"the quality of being reliable; consistency","meaningCN":"可靠性；一致性（-ity 构成性质名词）","example":"Engineers tested the reliability of the pump for a month.","exampleCN":"工程师用一个月测试了这台泵的可靠性。"},{"word":"reliably","structure":"reliable + -ly (adverb)","meaning":"in a dependable way","meaningCN":"可靠地；稳妥地（-ly 构成副词）","example":"The system reliably logs every delivery.","exampleCN":"这个系统可靠地记录每一次配送。"},{"word":"unreliable","structure":"un- (not) + reliable","meaning":"not able to be trusted or depended on","meaningCN":"不可靠的；不可信的（un- 表示否定）","example":"The witness proved unreliable and was dismissed.","exampleCN":"那名证人被证明不可靠，随后被排除。"},{"word":"unreliability","structure":"un- + reliability","meaning":"the quality of not being reliable","meaningCN":"不可靠；不可信（un- + reliability）","example":"The unreliability of the ferry forced commuters onto the road.","exampleCN":"渡船的不靠谱迫使通勤者改走公路。"},{"word":"reliant","structure":"rely + -ant (adjective of agent)","meaning":"depending on someone or something","meaningCN":"依赖的；依靠的（-ant 构成形容词）","example":"The town is heavily reliant on the mine.","exampleCN":"这座小镇严重依赖那座矿。"},{"word":"reliance","structure":"rely + -ance (noun of state)","meaning":"the state of depending on someone or something","meaningCN":"依赖；信赖（-ance 构成状态名词）","example":"The country's reliance on imported grain is growing.","exampleCN":"这个国家对进口粮食的依赖正在加深。"},{"word":"religion","structure":"re- (intensive) + ligare (to bind) + -ion","meaning":"a system of faith and worship, literally 'binding'","meaningCN":"宗教（字面为“捆绑”，与 rely 同根但词义已分叉）","example":"Religion and law were once the same body of rules.","exampleCN":"宗教与法律曾经是同一套规则。"},{"word":"league","structure":"from ligare 'to bind', through Old French ligue","meaning":"a group bound together by agreement","meaningCN":"联盟；联合会（由“捆绑”引申为结盟）","example":"The two ports formed a shipping league.","exampleCN":"两座港口组成了一个航运联盟。"},{"word":"liable","structure":"from ligare 'to bind', through Old French lier","meaning":"legally bound or responsible","meaningCN":"有法律责任的；须负责任的（由“被绑住”引申）","example":"The driver is liable for the damage.","exampleCN":"司机对损坏负有责任。"},{"word":"ligament","structure":"ligare (to bind) + -ment (instrument)","meaning":"a band that binds bones together","meaningCN":"韧带（ligare 捆绑 + -ment 工具）","example":"He tore a ligament in his knee.","exampleCN":"他膝盖的一条韧带撕裂了。"}],"latinEntries":[{"word":"religare","structure":"re- (intensive) + ligare (to bind)","meaning":"to fasten, bind fast","meaningCN":"系紧；绑牢"},{"word":"ligare","structure":"PIE *leig- 'to tie, bind'","meaning":"to bind, tie","meaningCN":"捆绑；系"},{"word":"religio","structure":"from religare, 'binding'","meaning":"scruple, obligation, religion","meaningCN":"顾忌；义务；宗教"}]}},{"word":"rely","ipa_uk":"/rɪˈlaɪ/","ipa_us":"/rɪˈlaɪ/","definition_zh":"依靠；依赖；信赖；指望；依据；自立","definition_en":"to depend on someone or something with trust, or to base a claim or plan on something","core_image":"把自己系在另一根桩上，然后把全身重量交给那根绳子","scene":"The hill farmers rely on a single diesel pump to bring water up from the valley every summer.","sceneCN":"这里 rely 是「依赖（设备）」（第 3 个义项：依靠工具或系统才能办成事）；句意：每年夏天，山上的农户都依赖一台柴油泵把水从山谷抽上来。场景要点：山坡上的蓄水池、轰鸣的柴油泵、顺着管道往上爬的水、干裂的田地。","pos":[{"tag":"vi.","zh":"依靠；依赖；信赖；指望"},{"tag":"vi.","zh":"（论证）依据；以……为基础"}],"collocations":[{"phrase":"rely on","zh":"依靠；依赖；信赖"},{"phrase":"rely upon","zh":"依靠（较正式的书面变体）"},{"phrase":"rely heavily on","zh":"严重依赖；高度依靠"},{"phrase":"rely on sb to do sth","zh":"指望某人做某事"},{"phrase":"rely on oneself","zh":"依靠自己"},{"phrase":"rely on evidence","zh":"依据证据"},{"phrase":"can rely on","zh":"可以信赖；可以指望"}],"forms":[{"label":"三单（he/she/it）","form":"relies"},{"label":"过去式（已经发生）","form":"relied"},{"label":"过去分词（完成／被动）","form":"relied"},{"label":"现在分词（进行体）","form":"relying"}],"derivatives":[{"word":"reliance","pos":"n.","zh":"依赖；信赖"},{"word":"reliant","pos":"adj.","zh":"依赖的；依靠的"},{"word":"reliable","pos":"adj.","zh":"可靠的；可信赖的"},{"word":"reliably","pos":"adv.","zh":"可靠地；稳妥地"},{"word":"reliability","pos":"n.","zh":"可靠性；可信度"},{"word":"unreliable","pos":"adj.","zh":"不可靠的；不可信的"}],"senses":[{"no":"01","title":"Tie your trust to a person","titleCN":"把信任系在一个人身上：信赖","definition":"to trust someone completely, especially their honesty and judgement","definitionCN":"完全信任某人，尤指信任其诚实与判断","example":"You can rely on her to tell you the truth, even when it is uncomfortable.","exampleCN":"你可以信赖她会跟你说实话，即使实话不好听。","why":"Latin religare meant 'bind fast'. To rely is to fasten your trust to a person as to a post; the 1570s sense is 'attach one's faith to'.","whyCN":"拉丁语 religare 意为“绑紧”。rely 就是把信任系到一个人身上，如同系到一根桩上；16 世纪 70 年代的义项正是“把信念系于”。"},{"no":"02","title":"Lean on someone for support","titleCN":"把重量交给别人：依靠、指望帮衬","definition":"to depend on someone for practical help, money, or care","definitionCN":"在实际帮助、金钱或照料上依赖某人","example":"After the injury he relied on his brother to drive him to work.","exampleCN":"受伤后，他依靠弟弟开车送他上班。","why":"The image becomes physical: a body that cannot stand alone leans its weight on another. The bond now carries real load, not only trust.","whyCN":"意象变成身体性的：一个无法独自站立的躯体把重量压到另一个身上。此时这根连接承载的是真实的重量，而不只是信任。"},{"no":"03","title":"Let the machine carry the weight","titleCN":"让机器替你出力：依赖工具或系统","definition":"to depend on a device, system, or service in order to do something","definitionCN":"依靠设备、系统或服务来完成某事","example":"The whole clinic relies on one generator during the storm season.","exampleCN":"整个诊所在风暴季都依赖一台发电机。","why":"The post you tie to can be a machine. Once your work is fastened to it, its failure becomes your failure, which is why reliance on tools feels risky.","whyCN":"你系住的那根桩可以是一台机器。工作一旦系在它上面，它出故障就成了你的故障——这正是依赖工具让人觉得有风险的原因。"},{"no":"04","title":"Expect it to happen","titleCN":"把它当成会发生：指望、预期","definition":"to be confident that something will happen or that someone will act in a certain way","definitionCN":"确信某事会发生，或某人会以某种方式行动","example":"We rely on the ferry leaving at seven, so we plan the whole day around it.","exampleCN":"我们指望渡船七点开，所以一整天的安排都围着它转。","why":"Trust projected forward becomes expectation. You fasten your plans to a future event, and if it does not arrive, the plans come loose.","whyCN":"把信任投向未来，就成了预期。你把计划系在一个未来事件上；它若不发生，计划就松脱了。"},{"no":"05","title":"Rest the argument on evidence","titleCN":"让论证落在证据上：依据","definition":"to base a claim, argument, or conclusion on a particular source of support","definitionCN":"把主张、论证或结论建立在某一支撑来源上","example":"The paper relies on ten years of weather records.","exampleCN":"这篇论文依据十年的气象记录。","why":"Here the rope runs from a conclusion back to its support. If the evidence is cut, the conclusion falls; relying is the weight the argument puts on it.","whyCN":"这里绳子从结论反系到支撑它的东西。证据一断，结论就掉下来；rely 就是论证压在证据上的那份重量。"},{"no":"06","title":"A town tied to one industry","titleCN":"整座城系在一个产业上：经济依赖","definition":"of a place, economy, or institution, to be economically dependent on a particular source","definitionCN":"指地方、经济或机构在经济上依赖某一来源","example":"The port relies on grain exports for a third of its income.","exampleCN":"这个港口三分之一的收入依赖粮食出口。","why":"A whole community can be fastened to one source of income. The larger the body, the heavier the load on that single bond.","whyCN":"整个社区都可以被系在单一收入来源上。被系住的一方越大，压在这根单独连接上的重量就越重。"},{"no":"07","title":"Be your own post: self-reliance","titleCN":"自己做那根桩：自立","definition":"in rely on oneself, to depend on one's own effort and judgement rather than on others","definitionCN":"用于 rely on oneself，表示依靠自己的努力与判断，而不是依靠别人","example":"She learned early to rely on herself when the nearest neighbour was a mile away.","exampleCN":"最近的邻居也在一英里外，她很早就学会依靠自己。","why":"The reflexive form turns the rope inward: the post you tie to is your own capacity. Self-reliance is the same binding, with the load and the support in one person.","whyCN":"反身形式把绳子转向内部：你系住的那根桩就是你自己的能力。自立是同一种捆绑，只是重量与支撑都在一个人身上。"},{"no":"08","title":"Follow the same track: rely on a method","titleCN":"沿着同一条路走：依循方法或规则","definition":"to depend on a fixed method, rule, or routine in order to work consistently","definitionCN":"依靠固定的方法、规则或流程，以便稳定地做事","example":"The crew relies on a written checklist before every take-off.","exampleCN":"机组每次起飞前都依循一份书面清单。","why":"A routine is a rope laid down in advance. Relying on it means walking the same fastened line each time, so that memory does not have to carry the whole load.","whyCN":"流程是一根事先铺好的绳。依循它，就是每次都走这条已经系牢的线，于是记忆不必独自承担全部重量。"}],"etymology":{"intro":{"en":"Rely began as a word for gathering troops, then became 'fasten one's trust to'. It comes from Latin religare 'bind fast', the same verb behind religion, but the two senses split apart long ago. Dates are approximate.","cn":"rely 最初指“集结军队”，后来才变成“把信任系于”。它来自拉丁语 religare“绑紧”，也是 religion 背后的同一个动词，但两者的词义很久以前就分开了。年代为大致估计。"},"items":[{"era":"MID-14C.","en":"First recorded as relien, 'to gather, assemble' an army, followers, or a host, used both transitively and intransitively.","cn":"最早记录为 relien，意为“集结、聚集”军队、追随者或人群，及物与不及物用法都有。"},{"era":"OLD FRENCH","en":"From Old French relier 'assemble, put together; fasten, fasten again, attach, rally, oblige'. The 'gather' and 'fasten' senses were already one word in French.","cn":"来自古法语 relier“聚集、拼合；系紧、重新系上、附着、集结、使承担义务”。“聚集”与“系紧”在法语里已经是同一个词。"},{"era":"LATIN religare","en":"Latin religare meant 'fasten, bind fast', from re-, here perhaps an intensive prefix, + ligare 'to bind'.","cn":"拉丁语 religare 意为“系紧、绑牢”，由 re-（此处或为加强前缀）+ ligare“捆绑”构成。"},{"era":"ligare / PIE *leig-","en":"Ligare 'to bind' goes back to PIE *leig- 'to tie, bind'. The family includes ligament, liable, league, and religion.","cn":"ligare“捆绑”可追溯到原始印欧语 *leig-“系、捆”。同族词包括 ligament、liable、league 与 religion。"},{"era":"1570s","en":"The modern sense 'depend on with full trust and confidence, attach one's faith to' is from the 1570s, perhaps through the notion 'rally to, fall back on'. It is typically used with on, perhaps by influence of the unrelated verb lie 'rest horizontally'.","cn":"现代义“带着完全的信任依赖、把信念系于”始于 16 世纪 70 年代，或许经由“向……集结、退守到……”的观念。它通常与 on 连用，可能是因为受到了无关动词 lie“横躺、休息”的影响。"},{"era":"MODERN ENGLISH","en":"The older 'gather, fasten' senses are now obsolete. Reliance is recorded from c. 1600, reliable from the 1560s, reliability from 1816. Religion keeps the same root but names a system of faith.","cn":"较早的“聚集、系紧”义现在已废弃。reliance 记录于约 1600 年，reliable 记录于 16 世纪 60 年代，reliability 于 1816 年。religion 保留同一词根，但指的是信仰体系。"}]},"similar":{"note":{"en":"Group one separates rely from its noun and adjective relatives and from religion, which shares the root but not the sense. Group two compares the verbs of dependence. Rely is almost always followed by on or upon; without that preposition it is no longer the same verb.","cn":"第一组把 rely 与它的名词、形容词同族词分开，也与 religion 分开——后者同根但不同义。第二组比较表示“依赖”的动词。rely 几乎总跟 on 或 upon；没有这个介词，它就不再是这个动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"reliance","ipa":"/rɪˈlaɪəns/","tag":"noun: the dependence","definition":"the state of depending on someone or something. It is the noun of the relation, while rely is the act.","definitionCN":"依赖某人或某物的状态。它是这种关系的名词，而 rely 是动作。"},{"word":"reliant","ipa":"/rɪˈlaɪənt/","tag":"adjective: depending","definition":"depending on someone or something, often as a lasting condition. It describes the dependent side, not the trusted side.","definitionCN":"依赖某人或某物的，常指一种持续状态。它描述依赖的一方，而不是被信赖的一方。"},{"word":"reliable","ipa":"/rɪˈlaɪəbl/","tag":"adjective: trustworthy","definition":"fit to be relied on. It is built from rely + -able and describes the thing or person trusted.","definitionCN":"值得被依靠的。它由 rely + -able 构成，描述被信赖的人或物。"},{"word":"religion","ipa":"/rɪˈlɪdʒən/","tag":"same root, different sense","definition":"a system of faith and worship. It comes from the same Latin religare 'bind fast', but it names a binding to the sacred, not an act of trusting a person.","definitionCN":"信仰与礼拜体系。它出自同一个拉丁语 religare“绑紧”，但指的是“被绑于神圣”，而不是信赖某人。"}]},{"heading":"NEAR MEANING","entries":[{"word":"depend","ipa":"/dɪˈpend/","tag":"need for support","definition":"to need someone or something in order to live or work. It comes from pendere 'hang', and pictures a thing hanging from another; rely adds trust to the need.","definitionCN":"为了生存或运作而需要某人某物。它来自 pendere“悬挂”，画面是一物挂在另一物下面；rely 在“需要”之外多了“信任”。"},{"word":"count on","ipa":"/kaʊnt ɒn/","tag":"expect confidently","definition":"to expect something to happen or someone to act, and plan accordingly. It is more about confident expectation than about long-term support.","definitionCN":"确信某事会发生或某人会行动，并据此安排。它更偏“有把握的预期”，而不是长期支撑。"},{"word":"trust","ipa":"/trʌst/","tag":"believe in honesty","definition":"to believe that someone is honest and will not harm you. It is the inner belief; rely is that belief put into practice by depending on someone.","definitionCN":"相信某人诚实、不会伤害你。它是内心的信念；rely 是把这种信念付诸实践，实际去依靠某人。"},{"word":"lean on","ipa":"/liːn ɒn/","tag":"physical or emotional support","definition":"to rest your weight on something, or to depend on someone for emotional support. It keeps the physical image that rely also carries, but stays more concrete.","definitionCN":"把重量靠在某物上，或在情感上依赖某人。它保留了 rely 也有的身体意象，但更具体。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: Latin religare 'bind fast', ligare 'bind', and the English family reliance, reliant, reliable, religion.","cn":"只用真实成分与真实同族词：拉丁语 religare“绑紧”、ligare“捆绑”，以及英语词族 reliance、reliant、reliable、religion。"},"normal":[{"en":"rely is literally 'bind fast': you tie your trust to a person or thing, as to a post.","cn":"rely 字面上就是“绑紧”：你把信任系到一个人或一样东西上，如同系到一根桩上。"},{"en":"The oldest sense was 'gather, assemble an army'. The modern 'trust' sense arrived in the 1570s, probably through 'rally to, fall back on'.","cn":"最古老的意思是“集结、聚集军队”。现代“信赖”义于 16 世纪 70 年代出现，可能经由“向……集结、退守到……”。"},{"en":"rely on and rely upon are fixed: the preposition is part of the verb. You cannot say 'I rely him'.","cn":"rely on 与 rely upon 是固定搭配：介词是这个动词的一部分。不能说 I rely him。"},{"en":"religion shares the root religare, but it means a binding to the sacred. The modern senses of rely and religion have fully separated.","cn":"religion 同出 religare 词根，但意思是“被绑于神圣”。rely 与 religion 的现代词义已经完全分开。"},{"en":"rely is the act, reliance the state, reliant the adjective for the dependent side, reliable the adjective for the trusted side.","cn":"rely 是动作，reliance 是状态，reliant 形容依赖的一方，reliable 形容被信赖的一方。"}],"abstract":[{"en":"Picture a climber clipped to a rope. Rely is the click of the carabiner: a deliberate act of attaching your weight to something else.","cn":"想象一个攀岩者把锁扣扣在绳上。rely 就是那声“咔嗒”：一个有意把自己重量挂到别处去的动作。"},{"en":"The rope can be a person, a machine, an income, a piece of evidence, or a checklist. In every case the question is the same: will it hold?","cn":"那根绳可以是人、机器、收入、证据或一份清单。无论哪种情况，问题都一样：它拉得住吗？"},{"en":"Self-reliance turns the rope around: you become the post you tie to, carrying both the weight and the support.","cn":"自立把绳子转向了自己：你成为自己系住的那根桩，同时承担重量与支撑。"}]},"examples":[{"en":"Small businesses here rely on tourists during the summer months.","cn":"这里的小企业夏天依靠游客。"},{"en":"You can rely on him to keep the schedule running.","cn":"你可以指望他让日程照常推进。"},{"en":"The argument relies on a single unproven assumption.","cn":"这个论证依据一个未经证明的单一假设。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“瑞赖”——遇事就赖上瑞叔，因为他最靠得住 → rely 依靠、信赖","word":"rely"},"root":"源自古法语 relier < 拉丁语 religare“绑紧、捆牢”（re- + ligare“捆绑”），与 religion 同根，核心是“把重量与信任系在别处”。","sensesIntro":{"en":"Eight senses of rely, all one act: fastening your trust or your weight to something outside yourself, then finding out whether that bond holds.","cn":"rely 的八个义项都是同一个动作：把信任或重量系到自己之外的东西上，然后看这根连接是否拉得住。"},"semanticMap":{"core":{"en":"CORE IMAGE: a rope tied to a post, taking a person's full weight.","cn":"核心意象：一根系在桩上的绳，承受一个人的全部重量。"},"chain":["BIND FAST","ATTACH TRUST","TAKE THE WEIGHT","EXPECT SUPPORT","BASE A CLAIM","BE ONE'S OWN POST"],"branches":[{"senses":"S1","en":"TRUST IN A PERSON: the bond is first moral — you fasten your belief to someone's honesty.","cn":"对人的信任：这根连接首先是道德性的——你把信念系在某人的诚实上。"},{"senses":"S2 · S6","en":"MATERIAL SUPPORT: a person or a whole town can hang its living on another's help or on one industry.","cn":"物质支撑：一个人乃至一整座城，都可以把自己的生计挂在别人的帮衬或单一产业上。"},{"senses":"S3 · S8","en":"TOOLS AND RULES: work is fastened to a machine, or to a checklist that walks the same line every time.","cn":"工具与规则：工作被系在机器上，或被系在每次走同一条线的清单上。"},{"senses":"S4","en":"EXPECTATION: trust thrown forward becomes the confidence that an event will arrive on time.","cn":"预期：投向未来的信任，变成“某事会按时到来”的把握。"},{"senses":"S5 · S7","en":"EVIDENCE AND SELF: the rope can run back to a proof, or turn inward until you are your own post.","cn":"证据与自我：绳子可以反系到证据上，也可以转向内部，直到你自己成为那根桩。"}]},"affixes":{"intro":{"en":"Rely is a French verb built on Latin religare 'bind fast'. English adds -ance, -ant, -able and -ability, and un- for the negative. The root lig- also gives ligament, liable, and league.","cn":"rely 是基于拉丁语 religare“绑紧”的法语动词。英语加上 -ance、-ant、-able、-ability，以及否定前缀 un-。词根 lig- 还给出 ligament、liable、league。"},"latinIntro":{"en":"The Latin family is religare 'bind fast', ligare 'to bind', and religio 'binding, obligation, religion'. Religion and rely are therefore true relatives, but their senses diverged centuries ago.","cn":"拉丁词族包括 religare“绑紧”、ligare“捆绑”、religio“束缚、义务、宗教”。因此 religion 与 rely 是真正的同族词，但它们的词义在几百年前就分开了。"},"items":[{"word":"rely","structure":"re- (intensive) + ly (ligare, to bind)","meaning":"to bind one's trust to; depend on","meaningCN":"把信任系于；依靠（re- 加强 + ly 捆绑）","example":"We rely on the river for drinking water.","exampleCN":"我们依靠这条河获取饮用水。"},{"word":"reliance","structure":"rely + -ance (noun of state)","meaning":"the state of depending on someone or something","meaningCN":"依赖；信赖（-ance 构成状态名词）","example":"The region's reliance on coal is declining.","exampleCN":"该地区对煤炭的依赖正在下降。"},{"word":"reliant","structure":"rely + -ant (adjective)","meaning":"depending on someone or something","meaningCN":"依赖的；依靠的（-ant 构成形容词）","example":"Older residents are reliant on public transport.","exampleCN":"年长居民依赖公共交通。"},{"word":"reliable","structure":"rely + -able (fit to be ——)","meaning":"fit to be relied on","meaningCN":"可靠的；值得依靠的（-able 表示“适合被……”）","example":"The service is cheap and reliable.","exampleCN":"这项服务便宜又可靠。"},{"word":"reliably","structure":"reliable + -ly (adverb)","meaning":"in a dependable way","meaningCN":"可靠地（-ly 构成副词）","example":"The sensor reliably reports the temperature.","exampleCN":"这个传感器可靠地报告温度。"},{"word":"reliability","structure":"reliable + -ity (noun of quality)","meaning":"the quality of being reliable","meaningCN":"可靠性（-ity 构成性质名词）","example":"Reliability matters more than speed here.","exampleCN":"在这里，可靠性比速度更重要。"},{"word":"unreliable","structure":"un- (not) + reliable","meaning":"not fit to be relied on","meaningCN":"不可靠的（un- 表示否定）","example":"The old ferry is unreliable in winter.","exampleCN":"那艘旧渡船冬天不可靠。"},{"word":"religion","structure":"re- (intensive) + ligare (bind) + -ion","meaning":"a system of faith, literally a 'binding'","meaningCN":"宗教（字面为“捆绑”，同根不同义）","example":"The word religion once meant an obligation, not a creed.","exampleCN":"religion 一词曾经指一种义务，而不是信条。"},{"word":"ligament","structure":"ligare (to bind) + -ment (instrument)","meaning":"a band of tissue that binds bones","meaningCN":"韧带（ligare 捆绑 + -ment 工具）","example":"The ligament holds the knee joint together.","exampleCN":"韧带把膝关节连在一起。"},{"word":"liable","structure":"from ligare, through Old French lier","meaning":"bound by law; responsible","meaningCN":"负有法律责任的（由“被绑住”引申）","example":"The company is liable for the clean-up.","exampleCN":"公司对清理工作负有责任。"},{"word":"league","structure":"from ligare, through Old French ligue","meaning":"a group bound together by agreement","meaningCN":"联盟（由“捆绑”引申为结盟）","example":"Five towns formed a league against the flood.","exampleCN":"五座城镇结成一个抗洪联盟。"}],"latinEntries":[{"word":"religare","structure":"re- (intensive) + ligare (to bind)","meaning":"to fasten, bind fast","meaningCN":"系紧；绑牢"},{"word":"ligare","structure":"PIE *leig- 'to tie, bind'","meaning":"to bind, tie","meaningCN":"捆绑；系"},{"word":"religio","structure":"from religare, 'binding'","meaning":"obligation, scruple, religion","meaningCN":"义务；顾忌；宗教"}]}},{"word":"remove","ipa_uk":"/rɪˈmuːv/","ipa_us":"/rɪˈmuːv/","definition_zh":"移走；拿走；脱下；清除；免除；撤职；切除；距离；间距","definition_en":"to take something away from its place, get rid of it, or dismiss someone from a position","core_image":"把一件东西从原来的位置搬开，原地留下一个空位","scene":"The technician removed the damaged panel from the wing and laid it on the hangar floor.","sceneCN":"这里 remove 是「移走、拆下」（第 1 个义项：把东西从原来的位置拿走）；句意：技术员把损坏的面板从机翼上拆下，放在机库地板上。场景要点：机翼上的空槽、拆下的金属面板、机库地面、技术员的手套。","pos":[{"tag":"vt.","zh":"移走；拿走；脱下；清除；撤职；切除"},{"tag":"n.","zh":"距离；间距；搬移（多用于正式或英式语境）"}],"collocations":[{"phrase":"remove from","zh":"从……移走；从……撤职"},{"phrase":"remove a stain","zh":"去除污渍"},{"phrase":"remove doubts","zh":"消除疑虑"},{"phrase":"remove sb from office","zh":"免除某人的职务"},{"phrase":"remove one's shoes","zh":"脱下鞋子"},{"phrase":"remove a tumour","zh":"切除肿瘤"},{"phrase":"be far removed from","zh":"与……相去甚远"}],"forms":[{"label":"三单（he/she/it）","form":"removes"},{"label":"过去式（已经发生）","form":"removed"},{"label":"过去分词（完成／被动）","form":"removed"},{"label":"现在分词（进行体）","form":"removing"},{"label":"名词复数","form":"removes"}],"derivatives":[{"word":"removal","pos":"n.","zh":"移除；去除；搬迁；免职"},{"word":"removable","pos":"adj.","zh":"可移动的；可拆除的"},{"word":"removed","pos":"adj.","zh":"远离的；隔代的；已删除的"},{"word":"remover","pos":"n.","zh":"去除剂；搬运者"},{"word":"irremovable","pos":"adj.","zh":"不可移动的；不可撤职的"}],"senses":[{"no":"01","title":"Take it off its place","titleCN":"从原位拿走：移走、拆下","definition":"to take an object away from the place where it was, leaving that place empty","definitionCN":"把物体从原来所在的位置拿走，使原处空出来","example":"Please remove the boxes from the doorway before the delivery arrives.","exampleCN":"送货的来之前，请把箱子从门口挪走。","why":"Latin removere is re- 'away' + movere 'to move'. The core is a movement away: the thing is still whole, but it is no longer here.","whyCN":"拉丁语 removere 是 re-“离开”+ movere“移动”。核心是“移开”：东西仍然完整，只是不再在这里了。"},{"no":"02","title":"Take it off your body","titleCN":"从身上取下：脱下、摘除","definition":"to take off clothing, glasses, a covering, or something worn","definitionCN":"脱下衣物、摘下眼镜或取下穿戴覆盖之物","example":"Visitors must remove their shoes before entering the shrine.","exampleCN":"访客进殿前必须脱鞋。","why":"Clothing is 'on' a person the way an object is 'at' a place. Taking it off is the same away-movement, applied to the body as the original location.","whyCN":"衣物“在”人身上，正如物体“在”某个位置。把它取下，仍是同一种“移开”，只是原位置变成了身体。"},{"no":"03","title":"Make it disappear: get rid of","titleCN":"让它消失：清除、排除","definition":"to get rid of something unwanted, such as a stain, an obstacle, a doubt, or a risk","definitionCN":"去掉不想要的东西，如污渍、障碍、疑虑或风险","example":"A little vinegar will remove the stain from the tablecloth.","exampleCN":"一点醋就能去掉桌布上的污渍。","why":"The away-movement is applied to something that should not remain at all. What is moved away no longer exists in that place, so 'remove' becomes 'eliminate'.","whyCN":"这种“移开”作用于根本不该留下的东西。被移走的东西不再存在于原处，于是“移开”变成了“消除”。"},{"no":"04","title":"Take the person out of the post","titleCN":"把人从职位上移开：免职","definition":"to dismiss someone from an office, position, or job","definitionCN":"把某人从职务、岗位或工作中撤下","example":"The board removed the director after the audit.","exampleCN":"审计之后，董事会撤掉了那位董事。","why":"A post is a place a person occupies. Removing the person is moving them out of that place, exactly like lifting an object from a shelf.","whyCN":"职位是一个人占据的位置。把人 remove，就是把人从那个位置移出去，就像把物件从架子上拿下来一样。"},{"no":"05","title":"Take it out of the body","titleCN":"从身体里取出：手术切除","definition":"to cut out and take away a part of the body, such as a tumour or a tooth","definitionCN":"切除并取出身体的一部分，如肿瘤或牙齿","example":"Surgeons removed the appendix before it ruptured.","exampleCN":"外科医生在阑尾破裂前把它切除了。","why":"The body is the place, the organ the object. Surgery is the most literal form of the core image: the thing is carried out and the place is closed.","whyCN":"身体是位置，器官是物件。手术是核心意象最字面的形态：东西被取出来，原处再被缝上。"},{"no":"06","title":"The act itself: a removal","titleCN":"动作本身：搬移、移除（名词）","definition":"as a noun, the act of removing a person from office or a thing from a place, recorded from the 1550s","definitionCN":"作名词，指把人撤职或把东西移开的动作，记录于 16 世纪 50 年代","example":"The removal of the old statue divided the town.","exampleCN":"移走那座旧雕像的事让全镇产生了分歧。","why":"English turned the verb into a noun in the 1550s. The action of moving something away becomes a thing you can name and argue about.","whyCN":"英语在 16 世纪 50 年代把这个动词转成了名词。把东西移开的动作，变成了可以被命名、被争论的一件事。"},{"no":"07","title":"The space left between: distance","titleCN":"中间留下的那段：距离、差距","definition":"as a noun, the distance or degree by which one thing is separated from another, recorded from the 1620s","definitionCN":"作名词，指一物与另一物隔开的距离或程度，记录于 17 世纪 20 年代","example":"The cousin is three removes from the main line of the family.","exampleCN":"这位表亲与家族主线隔了三代。","why":"Once something is moved away, the gap it leaves becomes measurable. The noun shifts from the act to the distance produced by the act.","whyCN":"东西一旦被移开，它留下的空隙就变得可以度量。名词从“动作”转到了“动作造成的距离”。"},{"no":"08","title":"Move yourself out: withdraw","titleCN":"把自己移出去：离席、退出","definition":"in remove oneself, to leave a room, meeting, or situation deliberately","definitionCN":"用于 remove oneself，表示有意离开房间、会议或某种处境","example":"He removed himself from the meeting before the vote was taken.","exampleCN":"表决之前，他退出了会议。","why":"The reflexive form makes the person both the mover and the thing moved. To remove oneself is to treat your own presence as an object that can be taken away.","whyCN":"反身形式让人既是移动者又是被移动之物。remove oneself 就是把自己的“在场”当成一件可以拿走的东西。"},{"no":"09","title":"Take it down from the screen","titleCN":"从屏幕上撤下：删除、下架","definition":"to delete or take down digital content, such as a post, video, or file, from a platform or device","definitionCN":"把帖子、视频或文件等数字内容从平台或设备上删除、下架","example":"The moderator removed the post within ten minutes of it appearing.","exampleCN":"帖子发出后十分钟内，版主就把它删除了。","why":"A post occupies a place on a page the way a box occupies a doorway. Taking it down repeats the oldest sense of the word in a new kind of space.","whyCN":"一条帖子占据页面上的一个位置，正如箱子占据门口。把它撤下，就是这个词最古老的意思在一种新的空间里重演。"}],"etymology":{"intro":{"en":"Remove came into English in the early 14th century from Old French and Latin, where it already meant both 'move away' and 'dismiss from office'. The noun followed in the 16th century. Dates are approximate.","cn":"remove 于 14 世纪初经由古法语和拉丁语进入英语，在那里它已经同时表示“移开”和“撤职”。名词用法在 16 世纪接踵而来。年代为大致估计。"},"items":[{"era":"EARLY 14C.","en":"First recorded as remouven, remuvien, remēven, 'to take something away; to dismiss from an office, post, or situation'.","cn":"最早记录为 remouven、remuvien、remēven，意为“把某物拿走；把人从职务、岗位或处境中撤下”。"},{"era":"OLD FRENCH","en":"From Old French removoir 'move, stir; leave, depart; take away'. The French verb already carried both the physical and the official senses.","cn":"来自古法语 removoir“移动、挪动；离开、启程；拿走”。法语动词已经同时带有物理与职务两方面的意思。"},{"era":"LATIN removere","en":"Latin removere meant 'move back or away, take away, put out of view, subtract'.","cn":"拉丁语 removere 意为“向后或向外移动、拿走、移出视线、减去”。"},{"era":"re- + movere","en":"Removere is re- 'back, away' + movere 'to move'. The English word therefore contains a double movement: the base verb moves, and the prefix moves it away.","cn":"removere 由 re-“向后、离开”+ movere“移动”构成。因此英语这个词里有一层双重移动：词干表示移动，前缀表示移开。"},{"era":"PIE *meue-","en":"Movere goes back to PIE *meue- 'to push away'. The same root lies behind move, movie, and motive, all words of setting something in motion.","cn":"movere 可追溯到原始印欧语 *meue-“推开”。同一词根也在 move、movie、motive 背后，都是“让某物动起来”的词。"},{"era":"1550s / 1620s","en":"The noun is recorded from the 1550s as 'act of removing' and from the 1580s as 'change of place'; the sense 'distance by which a thing is removed' is from the 1620s. Removed as 'distant in relationship' dates from the 1540s.","cn":"名词于 16 世纪 50 年代记录为“移除的动作”，16 世纪 80 年代记录为“位置的改变”；“被移开的距离”义始于 17 世纪 20 年代。removed 表示“关系疏远、隔代”始于 16 世纪 40 年代。"}]},"similar":{"note":{"en":"Group one separates remove from the forms built on it, especially removal, which is the noun learners most often confuse with the verb. Group two compares the verbs of taking away: delete, eliminate, take away, dismiss.","cn":"第一组把 remove 与由它构成的形式分开，尤其是 removal——学习者最常把它与动词混用。第二组比较“拿走”类动词：delete、eliminate、take away、dismiss。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"removal","ipa":"/rɪˈmuːvl/","tag":"noun of the action","definition":"the act of removing something or someone, or a move to a new home. It is the noun; remove is the verb.","definitionCN":"把某物或某人移开的动作，或搬家的行为。它是名词；remove 是动词。"},{"word":"removable","ipa":"/rɪˈmuːvəbl/","tag":"adjective: can be taken off","definition":"able to be taken off or out, often by design. It describes the object, not the act.","definitionCN":"可以被取下或拆出的，常指设计上如此。它描述物件，而不是动作。"},{"word":"removed","ipa":"/rɪˈmuːvd/","tag":"adjective: distant","definition":"far away, distant in relationship, or already deleted. It is the past participle used as an adjective.","definitionCN":"远离的、关系隔代的，或已被删除的。它是过去分词作形容词。"},{"word":"remover","ipa":"/rɪˈmuːvə/","tag":"noun: agent or substance","definition":"a person who removes something, or a product that removes it, such as a stain remover.","definitionCN":"移除某物的人，或去除某物的产品，如去污剂。"}]},{"heading":"NEAR MEANING","entries":[{"word":"delete","ipa":"/dɪˈliːt/","tag":"erase text or data","definition":"to erase written or digital material so that it no longer exists. It is narrower than remove, which can also mean moving or dismissing.","definitionCN":"抹去文字或数字内容，使其不再存在。它比 remove 窄，因为 remove 还可指搬走或撤职。"},{"word":"eliminate","ipa":"/ɪˈlɪmɪneɪt/","tag":"get rid of completely","definition":"to remove something completely, especially a problem, rival, or waste. It stresses that nothing is left, while remove only says it is taken away.","definitionCN":"彻底去掉某物，尤指问题、对手或废物。它强调一点不剩，而 remove 只说“被拿开”。"},{"word":"take away","ipa":"/teɪk əˈweɪ/","tag":"carry off","definition":"to carry something off from a place. It is the plain physical core of remove, without the official or surgical extensions.","definitionCN":"把东西从某处拿走。它是 remove 最朴素的物理核心，没有职务或手术方面的引申。"},{"word":"dismiss","ipa":"/dɪsˈmɪs/","tag":"send away from a post","definition":"to send someone away from a job or duty. It covers only the official sense of remove, and often adds the idea of formal rejection.","definitionCN":"让某人离开工作岗位或职务。它只覆盖 remove 的职务义，且常多一层正式驳回的意味。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: re- 'away' + movere 'move', and the English family removal, removable, removed, remover, plus move and motive from the same root.","cn":"只用真实成分与真实同族词：re-“离开”+ movere“移动”，以及英语词族 removal、removable、removed、remover，还有同根的 move 与 motive。"},"normal":[{"en":"re- means 'away' and movere means 'move': remove is simply 'move away'. Everything else grows from that.","cn":"re- 意为“离开”，movere 意为“移动”：remove 就是“移开”。其余义项都从这里长出来。"},{"en":"The official sense is as old as the word: early 14c. already meant 'dismiss from an office'. A post is a place a person occupies.","cn":"职务义和这个词一样古老：14 世纪初就已表示“撤职”。职位就是一个人占据的位置。"},{"en":"removal is the noun, removable the adjective, removed the participle-adjective. Do not use remove where removal is needed.","cn":"removal 是名词，removable 是形容词，removed 是分词形容词。需要名词时不要用 remove。"},{"en":"The root movere gives move, movie, motive. All of them are about setting something in motion, which is why removal feels like a small journey.","cn":"词根 movere 给出 move、movie、motive，都与“让某物动起来”有关，所以 removal 有一种短途搬迁的感觉。"},{"en":"be far removed from means 'be very different from', not 'be physically far'. The distance here is figurative.","cn":"be far removed from 意为“与……大不相同”，而不是“物理上很远”。这里的距离是比喻性的。"}],"abstract":[{"en":"Picture a hand lifting a cup off a table. The cup is unchanged; what changes is that the table now has an empty ring where it stood.","cn":"想象一只手把杯子从桌上拿开。杯子没有变；变的是桌上留下了一圈空印。"},{"en":"That empty space is the whole word: remove always leaves a place behind, whether it is a shelf, a body, a post, or a page.","cn":"那个空位就是这个词的全部：remove 总会留下一个位置，无论是架子、身体、职位还是页面。"},{"en":"When the empty space is measured, remove becomes a noun meaning distance; when a person moves out of the space, it becomes withdrawal.","cn":"当这个空位被度量，remove 就成了表示距离的名词；当人从那个位置移出去，它就成了“退出”。"}]},"examples":[{"en":"The city removed the fallen tree before the morning rush.","cn":"市政部门在早高峰前移走了倒下的树。"},{"en":"Nothing can remove the fact that the deadline was missed.","cn":"什么也无法消除错过截止日期这一事实。"},{"en":"The manager was removed from her post after the inquiry.","cn":"调查之后，那位经理被免职。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“瑞木屋”——瑞木屋被整体搬走，原地只剩一片空地 → remove 移开、移除","word":"remove"},"root":"源自拉丁语 removere“移开、拿走”（re-“离开”+ movere“移动”），核心是“把东西从原位搬走，留下空位”。","sensesIntro":{"en":"Nine senses of remove, all one gesture: something is moved out of the place it occupied, and the place is left empty — a doorway, a body, a post, a page, or a room.","cn":"remove 的九个义项都是同一个动作：某物被移出它占据的位置，那个位置空了下来——门口、身体、职位、页面或一间屋子。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand lifts a thing out of its place, leaving a gap behind.","cn":"核心意象：一只手把东西从原位拿出，留下一个空位。"},"chain":["MOVE AWAY","LEAVE A GAP","MAKE IT VANISH","TAKE A PERSON OUT","MEASURE THE GAP","WITHDRAW ONESELF"],"branches":[{"senses":"S1 · S2","en":"OUT OF A PLACE: an object leaves a doorway, and clothing leaves a body — the same away-movement at two scales.","cn":"离开位置：物件离开门口，衣物离开身体——同一种“移开”，两种尺度。"},{"senses":"S3 · S9","en":"OUT OF EXISTENCE: a stain or a doubt is moved away until nothing remains; a post is taken down from a page the same way.","cn":"移出存在：污渍或疑虑被移走到一点不剩；帖子也从页面上被同样地撤下。"},{"senses":"S4 · S5","en":"OUT OF A BODY OR A POST: a person is lifted out of a position, and an organ out of the body — both are places someone occupies.","cn":"移出身体或职位：人被从职位上移开，器官被从身体里取出——两者都是某物占据的位置。"},{"senses":"S6 · S7","en":"THE GAP NAMED: English names the act in the 1550s, then names the distance the act leaves in the 1620s.","cn":"空位被命名：英语在 16 世纪 50 年代命名这个动作，17 世纪 20 年代又命名动作留下的距离。"},{"senses":"S8","en":"SELF-REMOVAL: the reflexive form treats your own presence as the object to be taken away.","cn":"自我移除：反身形式把自己的“在场”当作要被拿走的东西。"}]},"affixes":{"intro":{"en":"Remove is re- 'away' plus movere 'move'. English builds removal, removable, removed, remover and irremovable on it, while the root movere also gives move, movement, movie, and motive.","cn":"remove 是 re-“离开”加 movere“移动”。英语在它之上构成 removal、removable、removed、remover、irremovable，而词根 movere 还给出 move、movement、movie、motive。"},"latinIntro":{"en":"The Latin family is removere 'move away', movere 'to move', motus 'a movement', and the prefix re- 'back, away'. Motion, motive, and emotion all belong to the same movere group.","cn":"拉丁词族包括 removere“移开”、movere“移动”、motus“运动”，以及前缀 re-“向后、离开”。motion、motive、emotion 都属于同一个 movere 词群。"},"items":[{"word":"remove","structure":"re- (away) + move (movere, to move)","meaning":"to move something away from its place","meaningCN":"移开；拿走（re- 离开 + move 移动）","example":"Remove the lid before heating the soup.","exampleCN":"加热汤之前先把盖子拿掉。"},{"word":"removal","structure":"remove + -al (noun of action)","meaning":"the act of removing, or a move to a new home","meaningCN":"移除；搬迁（-al 构成动作名词）","example":"The removal of the trees changed the whole street.","exampleCN":"砍掉那些树改变了整条街。"},{"word":"removable","structure":"remove + -able (capable of being)","meaning":"able to be taken off or out","meaningCN":"可移动的；可拆除的（-able 表示“能被……”）","example":"The tablet has a removable battery.","exampleCN":"这台平板有一个可拆卸的电池。"},{"word":"removed","structure":"remove + -ed (past participle as adjective)","meaning":"distant, separated, or deleted","meaningCN":"远离的；隔代的；已删除的（-ed 构成形容词）","example":"His ideas are far removed from ours.","exampleCN":"他的想法与我们的相去甚远。"},{"word":"remover","structure":"remove + -er (person or instrument)","meaning":"a person or substance that removes something","meaningCN":"移除者；去除剂（-er 表示人或工具）","example":"Use a paint remover on the old door.","exampleCN":"在这扇旧门上用去漆剂。"},{"word":"irremovable","structure":"ir- (in-, not) + removable","meaning":"not able to be removed","meaningCN":"不可移动的；不可撤职的（ir- 表示否定）","example":"The stone was irremovable without a crane.","exampleCN":"没有起重机，这块石头移不走。"},{"word":"move","structure":"from movere, through Old French movoir","meaning":"to change place or position","meaningCN":"移动；搬动（与 remove 同出 movere）","example":"Move the chair closer to the window.","exampleCN":"把椅子挪近窗户一点。"},{"word":"movement","structure":"move + -ment (noun of action)","meaning":"an act of changing place, or an organized group","meaningCN":"运动；动作；社会运动（-ment 构成名词）","example":"The movement of the crowd blocked the road.","exampleCN":"人群的移动堵住了道路。"},{"word":"movie","structure":"move + -ie (diminutive, originally 'moving picture')","meaning":"a film","meaningCN":"电影（原为“会动的画面”）","example":"The movie was shot in the old harbour.","exampleCN":"这部电影是在老港口拍摄的。"},{"word":"motive","structure":"mot- (motus, moved) + -ive","meaning":"a reason that drives someone to act","meaningCN":"动机（mot- 被推动 + -ive）","example":"The police could find no motive for the fire.","exampleCN":"警方找不到纵火的动机。"},{"word":"emotion","structure":"e- (ex-, out) + motion (movement)","meaning":"a feeling that moves a person","meaningCN":"情绪；情感（e- 向外 + motion 运动）","example":"Her voice carried no emotion at all.","exampleCN":"她的声音里不带任何情绪。"}],"latinEntries":[{"word":"removere","structure":"re- (away) + movere (to move)","meaning":"to move back or away, take away","meaningCN":"移开；拿走；撤去"},{"word":"movere","structure":"PIE *meue- 'to push away'","meaning":"to move, set in motion","meaningCN":"移动；使动"},{"word":"motus","structure":"past participle of movere","meaning":"a movement; a motion","meaningCN":"运动；移动"}]}},{"word":"require","ipa_uk":"/rɪˈkwaɪə/","ipa_us":"/rɪˈkwaɪər/","definition_zh":"需要；要求；规定；命令；使……成为必要；要求某人具备","definition_en":"to need something for a purpose, to demand it as necessary by rule or authority, or to make it compulsory that someone does something","core_image":"反复敲门、反复追问，直到门里的人不得不把东西交出来","scene":"报名表上空着一格学历证明，窗口的工作人员反复提醒。The clerk pointed at the empty box and said that the rules require the original certificate, not a photocopy.","sceneCN":"这里 require 是「规定要求」（第 4 个义项：规则或标准把某物定为必需）；句意：工作人员指着那个空格说，规定要求交原件，复印件不行。场景要点：贴着表格的窗口、空着的档案格、被退回的复印件、盖着公章的须知。","pos":[{"tag":"vt.","zh":"需要；要求；规定；命令"},{"tag":"v.","zh":"要求（某人）做某事；使成为必要"}],"collocations":[{"phrase":"require approval","zh":"需要批准"},{"phrase":"require attention","zh":"需要关注"},{"phrase":"require a password","zh":"需要密码"},{"phrase":"require somebody to do something","zh":"要求某人做某事"},{"phrase":"require something of somebody","zh":"要求某人具备某物或某种品质"},{"phrase":"be required by law","zh":"法律要求；法定必须"},{"phrase":"as required","zh":"按需；视需要"}],"forms":[{"label":"三单（he/she/it）","form":"requires"},{"label":"过去式（已经发生）","form":"required"},{"label":"过去分词（完成／被动）","form":"required"},{"label":"现在分词（进行体）","form":"requiring"}],"derivatives":[{"word":"requirement","pos":"n.","zh":"要求；必要条件；需求"},{"word":"required","pos":"adj.","zh":"必需的；规定的；必修的"},{"word":"requisite","pos":"adj./n.","zh":"必需的；必需品；必要条件"},{"word":"requisition","pos":"n./v.","zh":"征用；正式申请；征用令"},{"word":"unrequired","pos":"adj.","zh":"不需要的；非必需的"}],"senses":[{"no":"01","title":"Ask a question: inquire","titleCN":"发问：询问","definition":"to ask someone a question; to inquire, a sense recorded in the late 14th century and now obsolete","definitionCN":"向某人提出问题；询问。这一义项记录于 14 世纪晚期，现已废弃","example":"In Middle English, to require a person was simply to ask that person a question.","exampleCN":"在中古英语里，require 一个人就是向那个人提一个问题。","why":"Latin requirere meant 'seek to know, ask'. Before any demand, the word was a movement of inquiry: you go looking for an answer.","whyCN":"拉丁语 requirere 意为“探知、询问”。在任何“要求”出现之前，这个词首先是一个探询的动作：你去找一个答案。"},{"no":"02","title":"Ask for something: request","titleCN":"请求：讨要某物","definition":"to ask for something to be given or done, a common sense in the 16th and 17th centuries that has since been taken over by request","definitionCN":"请求给予或做某事；这一义项在 16、17 世纪很常见，后来被 request 接管","example":"In seventeenth-century usage, to require a favour meant simply to ask for it.","exampleCN":"在 17 世纪的用法里，require a favour 只是请求对方帮忙的意思。","why":"The inquiry turns into a petition: the seeker now names the thing wanted. There is still no threat behind it, only an ask.","whyCN":"探询变成了请托：寻找者现在说出了自己想要的东西。背后仍没有威胁，只是一次请求。"},{"no":"03","title":"Stand in need of: objective need","titleCN":"客观上需要","definition":"to need something because it is necessary for a purpose, without anyone being asked","definitionCN":"因为对某个目的必不可少而需要某物，并不涉及向谁提出请求","example":"Young seedlings require plenty of water in their first week.","exampleCN":"幼苗在第一周需要充足的水。","why":"The Latin phrase was 'ask for something needed'. When the thing needed cannot speak for itself, the need itself becomes the asker, and require simply means need.","whyCN":"拉丁语原义是“为需要的东西开口”。当所需之物自己不能开口时，需要本身就成了发问者，require 也就单纯表示“需要”。"},{"no":"04","title":"Demand as essential by rule","titleCN":"规则把某物定为必需","definition":"to demand something as necessary or essential, especially by a law, rule, code, or standard","definitionCN":"把某物作为必需或必不可少的东西来要求，尤指依据法律、规则、规范或标准","example":"The building code requires a fire exit on every floor.","exampleCN":"建筑规范规定每一层都必须有消防出口。","why":"A rule is a standing voice that keeps asking. What it asks for is not optional but essential, so the verb moves from request to compulsory condition.","whyCN":"规则是一个持续发问的声音。它所要的东西不是可选的，而是必不可少的，于是这个动词从“请求”转为“强制条件”。"},{"no":"05","title":"Demand that someone act","titleCN":"命令某人采取行动","definition":"to order or oblige someone to do something, with authority behind the demand","definitionCN":"命令或迫使某人做某事，要求背后带有权威","example":"The court required him to hand over all the documents.","exampleCN":"法院要求他交出所有文件。","why":"From 1751 the verb took the pattern require someone to do something. The ask has become an obligation: the person is not merely asked but bound to act.","whyCN":"从 1751 年起，这个动词采用了 require someone to do something 的结构。请求变成了义务：对方不只是被询问，而是被约束必须行动。"},{"no":"06","title":"Call for: the task needs it","titleCN":"任务本身提出了需要","definition":"of a job, role, or situation, to need a particular quality, skill, or action","definitionCN":"指工作、角色或处境需要某种品质、技能或行动","example":"This job requires patience and a good memory for names.","exampleCN":"这份工作需要有耐心，并且记名字要准。","why":"Here the demand comes from the work itself rather than from a person or a rule. The task is the one asking, and the worker must supply the answer.","whyCN":"这里的要求来自工作本身，而不是来自某个人或某条规则。任务成了发问的一方，而工作者必须给出答案。"},{"no":"07","title":"Require something of someone","titleCN":"要求某人具备某种品质","definition":"to demand that a person have or show a particular quality, effort, or standard","definitionCN":"要求某人具备或表现出某种品质、努力或水准","example":"The coach requires absolute punctuality of every player.","exampleCN":"教练要求每个球员绝对守时。","why":"The preposition of points the demand at a person's inner stock. What is required is not a thing handed over but a quality the person must already own.","whyCN":"介词 of 把要求对准了人内在的储备。所要的不是递过来的一件东西，而是这个人本身必须具备的一种品质。"},{"no":"08","title":"Fixed as compulsory","titleCN":"被固定为必修、必做","definition":"in fixed phrases, established as necessary and not optional, as in required course or required reading","definitionCN":"在固定短语中，被规定为必需而非可选，如必修课或必读书目","example":"Research methods is a required course for every major in the department.","exampleCN":"研究方法这门课是该系每个专业的必修课。","why":"What the rules require repeatedly becomes a permanent item on a list. The verb turns into an adjective, and the demand hardens into a catalogue entry.","whyCN":"规则反复要求的东西会变成清单上一个固定的条目。动词转为形容词，要求凝固成了一条目录项。"},{"no":"09","title":"As required: whenever needed","titleCN":"按需：在需要时使用","definition":"in the phrase as required, used whenever necessary rather than on a fixed schedule","definitionCN":"用于 as required 这一短语，表示在需要时才使用，而不是按固定时间表","example":"Take one tablet as required, up to four times a day.","exampleCN":"需要时服一片，一天最多四次。","why":"The need sense becomes a standing instruction: no one is demanding the dose now, but the instruction keeps asking whenever the condition appears.","whyCN":"“需要”义变成了一条常备指示：此刻没有人要求服药，但只要条件出现，这条指示就一直在发问。"}],"etymology":{"intro":{"en":"Require comes from Latin requirere, where re- probably means 'repeatedly' and the root is quaerere 'ask, seek'. That makes it a cousin of query, inquire, acquire and conquer, not of recover (capere 'take') or reside (sedere 'sit'). Region is the odd one out in this batch: its re- is part of the root reg-, not a prefix.","cn":"require 来自拉丁语 requirere，其中 re- 很可能表示“反复”，词根是 quaerere“询问、寻求”。因此它与 query、inquire、acquire、conquer 同族，而与 recover（capere“拿取”）、reside（sedere“坐”）不同族。region 是本批的例外：它的 re- 属于词根 reg-，不是前缀。"},"items":[{"era":"LATE 14C.","en":"First recorded in English as 'to ask someone a question, inquire', a sense now obsolete. In the same period it also meant 'to stand in need of, want'.","cn":"英语最早记录为“向某人提问、询问”，该义项现已废弃。同一时期它也表示“需要、缺少”。"},{"era":"OLD FRENCH","en":"From Old French requerre, requerir 'seek, procure; beg, ask, petition; demand', which passed through Vulgar Latin *requaerere.","cn":"来自古法语 requerre、requerir“寻找、取得；乞求、询问、请愿；要求”，经由俗拉丁语 *requaerere。"},{"era":"LATIN","en":"Latin requirere meant 'seek to know, ask, ask for (something needed)'. Re- here is explained as 'repeatedly', which fits a root about asking and seeking again.","cn":"拉丁语 requirere 意为“探知、询问、请求（所需之物）”。这里的 re- 被解释为“反复”，与一个关于反复询问和寻找的词根相合。"},{"era":"QUAERERE","en":"Quaerere 'ask, seek' is also behind query, inquire, inquiry, acquire, conquer and question. Its deeper origin is given in standard references only as uncertain or 'perhaps', so no older root is claimed here.","cn":"quaerere“询问、寻求”也是 query、inquire、inquiry、acquire、conquer、question 的来源。通行资料对其更早的来源只标为不确定或“或许”，因此这里不声称更古老的词根。"},{"era":"15C-17C","en":"The meaning 'demand as necessary or essential on general principles' is from the early 15th century, and 'demand that someone do something' from 1751. The old 'ask or request' sense was taken over by request.","cn":"“依据一般原则要求某物为必需”的义项始于 15 世纪早期，“要求某人做某事”始于 1751 年。古老的“询问或请求”义被 request 接管。"},{"era":"MODERN ENGLISH","en":"Requirement appears in the 1520s, and requisite and requisition follow as formal relatives. Modern require splits into two main branches: an objective need that no one asks for, and a rule or authority that demands.","cn":"requirement 出现于 16 世纪 20 年代，requisite 与 requisition 作为正式同族词随后出现。现代 require 分成两大支：无人开口的客观需要，以及规则或权威提出的要求。"}]},"similar":{"note":{"en":"The first group separates the derived and same-root forms from require; the second compares the four words learners tend to mix with it. The key test is whether the demand comes from a rule, from a task, or simply from a shortage.","cn":"第一组把派生形式与同根形式同 require 分开；第二组比较学习者最容易与它混用的四个词。判断的关键是：这个“需要”来自规则、来自任务，还是仅仅来自匮乏。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"requisite","ipa":"/ˈrekwɪzɪt/","tag":"formal adjective or noun","definition":"necessary for a particular purpose; a thing that is needed. It is a formal relative, not a form of the verb.","definitionCN":"为特定目的所必需的；必需品。它是正式的亲属词，不是这个动词的词形。"},{"word":"prerequisite","ipa":"/ˌpriːˈrekwɪzɪt/","tag":"thing needed first","definition":"something that must exist or be done before something else can happen. The pre- adds the idea of coming first.","definitionCN":"在另一件事发生之前必须先具备或先完成的事物。pre- 增加了“在先”的意思。"},{"word":"requisition","ipa":"/ˌrekwɪˈzɪʃn/","tag":"official demand or seizure","definition":"a formal request for something, or the official taking of property for public use. It is usually a written or military act, not a general need.","definitionCN":"正式的申请，或为公共用途而正式征用财产。它通常是书面或军事行为，不是一般意义上的需要。"},{"word":"query","ipa":"/ˈkwɪəri/","tag":"same root, different word","definition":"a question or a request for information. It shares quaerere 'ask, seek' but has no re- and no sense of demand.","definitionCN":"问题或信息查询。它与 require 共享 quaerere“询问、寻求”，但没有 re-，也没有“要求”的意味。"}]},{"heading":"NEAR MEANING","entries":[{"word":"need","ipa":"/niːd/","tag":"plain necessity","definition":"to require something because it is essential. It is the plainest and most general verb, and unlike require it never means 'demand by rule'.","definitionCN":"因必不可少而需要某物。它是最朴素、最通用的动词，而且不像 require 那样表示“由规则提出要求”。"},{"word":"demand","ipa":"/dɪˈmɑːnd/","tag":"ask with force","definition":"to ask for something firmly, as a right, and refuse to accept a refusal. It is louder and more personal than require, which often has an impersonal rule behind it.","definitionCN":"坚定地、作为权利要求某物，并不接受拒绝。它比 require 更强势、更个人化，而 require 背后常是一条非人的规则。"},{"word":"request","ipa":"/rɪˈkwest/","tag":"polite asking","definition":"to ask for something politely or formally, with the answer still open. Require and request share a source, but request keeps the old 'ask' sense that require lost.","definitionCN":"礼貌或正式地请求某物，对方仍可答应或不答应。require 与 request 同源，但 request 保留了 require 失去的那个古老“询问”义。"},{"word":"requirement","ipa":"/rɪˈkwaɪəmənt/","tag":"derived noun","definition":"a thing that is needed or demanded, or a necessary condition. It names the thing; require names the act of needing or demanding it.","definitionCN":"被需要或被要求的事物，或必要条件。它命名那个东西；require 命名需要或要求这个动作。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: re- 'repeatedly' plus quaerere 'ask, seek', the requirement family, and the two branches — objective need and rule-bound demand.","cn":"只用真实成分与真实同族词：re-“反复”加 quaerere“询问、寻求”、requirement 词族，以及两大分支——客观需要与规则要求。"},"normal":[{"en":"re- is 'repeatedly' and quaerere is 'ask, seek'. Require is to keep asking until the thing is supplied.","cn":"re- 是“反复”，quaerere 是“询问、寻求”。require 就是一直问到东西被提供为止。"},{"en":"The same quaerere root gives query, inquire, acquire, conquer and question — all about seeking, not about taking or sitting.","cn":"同一 quaerere 词根给出 query、inquire、acquire、conquer、question——全都关于“寻求”，与“拿取”或“坐”无关。"},{"en":"Two branches: no one is asked in 'the plant requires water', but a rule is speaking in 'the code requires a fire exit'.","cn":"两个分支：‘植物需要水’里没有人被询问，而‘规范要求消防出口’里是规则在说话。"},{"en":"The family runs require, requirement, requisite, prerequisite and requisition; only the first is the everyday verb.","cn":"词族包括 require、requirement、requisite、prerequisite、requisition；只有第一个是日常动词。"},{"en":"The original sense was simply 'ask', which is why request looks like a twin: request kept the polite asking, require took the compulsory demand.","cn":"最初的意思只是“询问”，所以 request 看起来像双胞胎：request 保留了礼貌的请求，require 拿走了强制性的要求。"}],"abstract":[{"en":"Picture someone knocking on a door again and again. At first it is only a question; by the tenth knock it has become a demand.","cn":"想象一个人一遍遍敲门。起初只是一个问题；敲到第十下时，它已经变成了要求。"},{"en":"A rule is a voice that never stops asking, which is why a building code can require a door without any person being present.","cn":"规则是一个永不停歇的发问声，所以建筑规范可以在没有任何人在场的情况下要求一扇门。"},{"en":"A need is a blank on a form that must be filled: require names that blank, whether a person or the situation is holding the pen.","cn":"需要是表格上一个必须填上的空格：require 指的就是那个空格，无论握笔的是人还是处境本身。"}]},"examples":[{"en":"Most houseplants require bright light but dislike direct midday sun.","cn":"大多数室内植物需要明亮的光线，但不喜欢正午直射的阳光。"},{"en":"The regulations require every worker to wear a helmet on site.","cn":"规定要求每名工人在工地上都必须戴安全帽。"},{"en":"The position requires a good command of two languages.","cn":"这个职位需要熟练掌握两门语言。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「若缺」——若有所缺，就必须补上、必须去要 → require 需要；要求（只借音，不表词源）","word":"require"},"root":"经由古法语 requerre 来自拉丁语 requirere，re- 这里意为“反复”，词根 quaerere 是“询问、寻求”，核心是“反复追问直到必需之物被给出”。","sensesIntro":{"en":"Nine senses of require, moving out from one act: a repeated asking. At one end it is a mere question; at the other it is a rule that binds, a task that calls, and a need that no one has to voice.","cn":"require 的九个义项都从同一个动作展开：反复地询问。一端只是提问；另一端则是约束人的规则、任务提出的召唤，以及无需任何人开口的需要。"},"semanticMap":{"core":{"en":"CORE IMAGE: a repeated knock at a door until what is needed must be given.","cn":"核心意象：反复敲门，直到所需之物不得不被交出。"},"chain":["ASK","ASK AGAIN","NAME THE WANTED THING","CALL IT ESSENTIAL","BIND SOMEONE TO ACT","STAND AS A RULE"],"branches":[{"senses":"S1 · S2","en":"ASKING: the oldest layer is inquiry and request, before the word acquired any force.","cn":"询问：最古老的一层是探询与请求，那时这个词还没有任何强制力。"},{"senses":"S3 · S6","en":"OBJECTIVE NEED: a plant, a job, or a situation can require something without asking anyone.","cn":"客观需要：植物、工作或处境可以在不向任何人开口的情况下需要某物。"},{"senses":"S4 · S5","en":"RULE AND COMMAND: a code demands a thing, and a court demands an action; the ask becomes binding.","cn":"规则与命令：规范索要某物，法院索要某个行动；请求变成了约束。"},{"senses":"S7","en":"A QUALITY FROM A PERSON: require something of someone aims the demand at what the person must be.","cn":"要求某人具备：require something of someone 把要求对准这个人必须具备的品质。"},{"senses":"S8 · S9","en":"FIXED FORMULAS: repeated demands harden into required courses and as required, where the asking is built into the phrase.","cn":"固定说法：反复的要求凝固成必修课与按需使用，发问被写进了短语本身。"}]},"affixes":{"intro":{"en":"Require is re- plus the Latin root quaer-. The prefix here marks repetition, not return, so the word is not a cousin of recover or reside. English builds requirement, required and the formal relatives requisite, prerequisite and requisition on this base.","cn":"require 是 re- 加拉丁词根 quaer-。这里的前缀表示重复，而不是返回，所以它与 recover、reside 不同族。英语在这个词基上构成 requirement、required，以及正式的 requisite、prerequisite、requisition。"},"latinIntro":{"en":"The Latin family is quaerere 'ask, seek', its prefixed forms requirere 'ask for what is needed' and acquirere 'seek to get', and the action noun requisitio. The root's deeper origin is uncertain.","cn":"拉丁语词族包括 quaerere“询问、寻求”、它的加前缀形式 requirere“请求所需之物”与 acquirere“寻求取得”，以及行为名词 requisitio。这个词根的更早来源不确定。"},"items":[{"word":"require","structure":"re- (repeatedly) + quaerere (ask, seek)","meaning":"to ask for what is needed until it must be given","meaningCN":"反复索求所需之物，直到它必须被给予（re- 反复 + quaerere 寻求）","example":"All visitors are required to sign in at the desk.","exampleCN":"所有来访者都必须在服务台登记。"},{"word":"requirement","structure":"require + -ment (noun of result or thing)","meaning":"a thing that is needed or demanded","meaningCN":"要求；必要条件；需求（-ment 构成结果或事物名词）","example":"The entry requirements include two years of experience.","exampleCN":"入职要求包括两年工作经验。"},{"word":"required","structure":"require + -ed (past participle as adjective)","meaning":"made necessary by a rule","meaningCN":"必需的；规定的（-ed 构成形容词）","example":"The required documents must be originals, not copies.","exampleCN":"要求的文件必须是原件，不能是复印件。"},{"word":"requisite","structure":"Latin requisitus, past participle of requirere + -ite","meaning":"necessary for a purpose; a necessary thing","meaningCN":"必需的；必需品（拉丁语 requisitus + -ite）","example":"Patience is a requisite for teaching small children.","exampleCN":"耐心是教幼儿的必要条件。"},{"word":"prerequisite","structure":"pre- (before) + requisite (required thing)","meaning":"something that must come before something else","meaningCN":"先决条件；前提（pre- 在前 + requisite 必需物）","example":"A basic course is a prerequisite for the advanced one.","exampleCN":"基础课程是高级课程的先修条件。"},{"word":"requisition","structure":"Latin requisitio, from requirere + -ition","meaning":"a formal demand, especially for supplies or property","meaningCN":"正式申请；征用（拉丁语 requisitio）","example":"The army sent a requisition for fuel and blankets.","exampleCN":"军队发来了一份燃料与毯子的征用单。"},{"word":"query","structure":"Latin quaerere (ask, seek) + -y","meaning":"a question or request for information","meaningCN":"疑问；查询（quaerere 询问 + -y）","example":"Please send any query about the bill to the finance office.","exampleCN":"对账单有任何疑问，请发给财务办公室。"},{"word":"inquire","structure":"in- (into) + quaerere (ask, seek)","meaning":"to ask for information","meaningCN":"询问；查询（in- 进入 + quaerere 寻求）","example":"She inquired about the times of the morning trains.","exampleCN":"她询问了早班列车的时刻。"},{"word":"inquiry","structure":"inquire + -y (noun of action)","meaning":"an act of asking or investigating","meaningCN":"询问；调查（-y 构成行为名词）","example":"The council opened an inquiry into the accident.","exampleCN":"委员会对这起事故展开了调查。"},{"word":"acquire","structure":"ac- (to) + quaerere (seek)","meaning":"to gain or get something by effort","meaningCN":"获得；取得（ac- 向 + quaerere 寻求）","example":"She acquired the painting at a small country auction.","exampleCN":"她在一场乡下小型拍卖会上得到了这幅画。"},{"word":"conquer","structure":"con- (completely) + quaerere (seek)","meaning":"to take control of a place by force","meaningCN":"征服；攻占（con- 彻底 + quaerere 寻求）","example":"The empire conquered the coast within a single summer.","exampleCN":"帝国在一个夏天之内征服了那片海岸。"},{"word":"request","structure":"re- + quaerere through Old French requeste","meaning":"to ask for something politely","meaningCN":"请求；要求（与 require 同源，保留礼貌询问义）","example":"He requested a seat by the window when booking.","exampleCN":"订票时他请求要一个靠窗的座位。"}],"latinEntries":[{"word":"quaerere","structure":"Latin verb of uncertain deeper origin","meaning":"to ask, seek, search for","meaningCN":"询问；寻求；搜寻"},{"word":"requirere","structure":"re- (repeatedly) + quaerere (ask, seek)","meaning":"to seek to know; ask for what is needed","meaningCN":"探知；请求所需之物"},{"word":"acquirere","structure":"ad- (to) + quaerere (seek)","meaning":"to seek and gain","meaningCN":"寻求并获得"}]}},{"word":"research","ipa_uk":"/rɪˈsɜːtʃ/","ipa_us":"/ˈriːsɜːrtʃ/","definition_zh":"研究；调查；科研；探究；为……搜集资料；深入研究","definition_en":"a careful and systematic investigation aimed at discovering facts, or to investigate a subject closely and repeatedly","core_image":"绕着同一个题目一圈又一圈地走，直到把它整个围住","scene":"为了弄清候鸟为什么绕开新修的风电场，团队在海岸线上架起雷达。Three winters of research on the coast finally showed why the birds turned away from the new turbines.","sceneCN":"这里 research 是「研究、调查」（第 1 个义项：为发现事实而进行的系统调查）；句意：海岸线上三个冬天的研究，终于说明候鸟为什么绕开那些新风机。场景要点：海岸线上的雷达天线、迁徙季的鸟群、贴满标记的风机分布图、记录了三年的数据表。","pos":[{"tag":"n.","zh":"研究；调查；科研（通常不可数）"},{"tag":"v.","zh":"研究；探究；为……搜集资料"}],"collocations":[{"phrase":"conduct research","zh":"开展研究"},{"phrase":"carry out research","zh":"进行研究"},{"phrase":"research on something","zh":"关于某事物的研究"},{"phrase":"research into something","zh":"对某事物的深入调查"},{"phrase":"scientific research","zh":"科学研究"},{"phrase":"market research","zh":"市场调研"},{"phrase":"research findings","zh":"研究结果"}],"forms":[{"label":"三单（he/she/it）","form":"researches"},{"label":"过去式（已经发生）","form":"researched"},{"label":"过去分词（完成／被动）","form":"researched"},{"label":"现在分词（进行体）","form":"researching"},{"label":"名词复数（通常不用，多见于旧式或特指多项研究）","form":"researches"}],"derivatives":[{"word":"researcher","pos":"n.","zh":"研究者；研究员；调查员"},{"word":"researchable","pos":"adj.","zh":"可研究的；值得研究的"},{"word":"researching","pos":"n./adj.","zh":"研究过程；从事研究的"},{"word":"researched","pos":"adj.","zh":"经过研究的；资料充分的"}],"senses":[{"no":"01","title":"Systematic inquiry into facts","titleCN":"为发现事实而做的系统调查","definition":"a careful, systematic investigation aimed at discovering or establishing facts","definitionCN":"为发现或确证事实而进行的细致、系统的调查","example":"Her research focuses on how children learn a second language.","exampleCN":"她的研究聚焦于儿童如何学习第二语言。","why":"The word is re- as an intensifier plus Latin circare 'go about'. To research is to keep going around a subject until no side of it is left unexamined.","whyCN":"这个词是加强语气的 re- 加上拉丁语 circare“四处走动”。做研究就是绕着一个题目不断走，直到它没有一面未被查看过。"},{"no":"02","title":"A particular investigation","titleCN":"某一项具体研究","definition":"a particular investigation of a named subject, usually introduced with on or into","definitionCN":"针对某一具体题目的调查，通常用 on 或 into 引出题目","example":"He is doing research on the effects of sleep loss on memory.","exampleCN":"他正在研究睡眠不足对记忆的影响。","why":"The general activity narrows to one path around one object. The preposition on or into marks the subject that the circling is centred on.","whyCN":"一般性的活动收窄为绕着某一个对象的路径。介词 on 或 into 标出这场绕行所围绕的题目。"},{"no":"03","title":"The habit of close investigation","titleCN":"追根究底的习惯","definition":"the general habit or activity of investigating things closely, not tied to a single project","definitionCN":"对事物进行细致调查的一般习惯或活动，并不限于某一个项目","example":"Good research begins with a question rather than an answer.","exampleCN":"好的研究从问题开始，而不是从答案开始。","why":"The 1690s sense treats the circling as a settled habit rather than a single project. A person who keeps walking around problems is doing research even when no study is named.","whyCN":"17 世纪 90 年代的义项把“绕行”当作一种固定习惯，而不是单个项目。一个总绕着问题走的人，即使没有点明某项研究，也是在从事研究。"},{"no":"04","title":"The accumulated findings","titleCN":"积累起来的研究结果","definition":"the body of findings or published work produced by investigation, treated as a single mass","definitionCN":"调查所产生的成果或已发表作品的整体，被当作一个集合来看待","example":"Recent research shows that the vaccine remains effective for at least a year.","exampleCN":"近期研究显示，这种疫苗至少在一年内仍然有效。","why":"The activity is named by its product. What researchers have found is treated as the research itself, the way a building can stand for the work of building.","whyCN":"活动被它的产物命名。研究者发现的东西被当作研究本身，就像一座建筑可以代表建造它的工作。"},{"no":"05","title":"Used before another noun","titleCN":"放在名词前作定语","definition":"used attributively before a noun to name something used for or produced by research","definitionCN":"放在名词前作定语，指用于研究或由研究产生的事物","example":"She applied for a research grant to continue the fieldwork.","exampleCN":"她申请了一笔研究经费，以继续野外工作。","why":"English lets a noun sit in the adjective slot. The activity labels the money, the paper, or the team, so research becomes a tag rather than a thing being done.","whyCN":"英语允许名词坐在形容词的位置上。这项活动给经费、论文或团队贴上标签，于是 research 变成了一个标签，而不是正在进行的动作。"},{"no":"06","title":"Investigate a subject closely","titleCN":"对一个题目深入调查","definition":"to investigate or study a matter closely and with continued care","definitionCN":"细致而持续地调查或研究某一事项","example":"The historian researched the letters for three years before writing a word.","exampleCN":"这位历史学家研究了那些信件三年，才动笔写一个字。","why":"The verb, recorded from the 1590s, turns the noun's circling into an action done to an object. The subject is the ground walked around.","whyCN":"动词记录于 16 世纪 90 年代，把名词的“绕行”变成作用于某个对象的动作。题目就是被绕着走的那块地。"},{"no":"07","title":"Do research as an activity","titleCN":"从事研究工作","definition":"to make researches; to spend time doing investigation, often without naming an object","definitionCN":"做研究；花时间从事调查，通常不点明对象","example":"He researches in the national archives every summer.","exampleCN":"他每年夏天都在国家档案馆做研究。","why":"Recorded from 1781, the intransitive use shifts attention from the object to the worker's occupation. Circling has become a way of spending one's time.","whyCN":"这一不及物用法记录于 1781 年，把注意力从对象转到研究者的职业活动上。绕行已经变成了一种打发时间的方式。"},{"no":"08","title":"Search again, literally","titleCN":"字面意义上的再次搜寻","definition":"to search a place or source a second time, a literal reading of re- 'again' plus search, now rare outside wordplay","definitionCN":"对某地或某来源进行第二次搜寻，是 re-“再次”加 search 的字面读法，除文字游戏外现已少见","example":"When the first map proved wrong, they had to research the whole valley again.","exampleCN":"第一张地图被证明有误后，他们不得不把整个山谷重新搜寻一遍。","why":"In the main sense re- is intensive, not 'again'. But when a search really is repeated, the prefix recovers its ordinary meaning and the word becomes literal: search again.","whyCN":"在主要义项里，re- 是加强成分，而不是“再次”。但当搜寻真的重复时，前缀恢复了它的平常含义，这个词也就变成字面意思：再搜一遍。"}],"etymology":{"intro":{"en":"Research is French in form and Latin in root: re- (here an intensifier) plus Old French cerchier, from Latin circare 'go about', itself from circus 'circle'. That root is shared with search, circle and circus, but not with recover (capere 'take'), require (quaerere 'ask'), reside (sedere 'sit') or region (reg- 'rule'). Note that region's re- is not a prefix at all.","cn":"research 的外形来自法语，词根来自拉丁语：re-（这里是加强成分）加古法语 cerchier，再往上是拉丁语 circare“四处走动”，而 circare 又出自 circus“圆圈”。这个词根与 search、circle、circus 共享，但与 recover（capere“拿取”）、require（quaerere“询问”）、reside（sedere“坐”）、region（reg-“统治”）都不共享。注意 region 的 re- 根本不是前缀。"},"items":[{"era":"1570s","en":"The noun is first recorded as 'act of searching closely' for a specific person or thing. It came from French recerche (1530s), a back-formation from Old French recercher.","cn":"名词最早记录为“对特定人或物的细致搜寻”，来自法语 recerche（16 世纪 30 年代），后者是古法语 recercher 的反向构词。"},{"era":"OLD FRENCH","en":"Old French recercher meant 'seek out, search closely'. Its re- is described as perhaps an intensive prefix, so it strengthens the searching rather than repeating it.","cn":"古法语 recercher 意为“找出、仔细搜寻”。其中的 re- 被描述为“也许是加强前缀”，因此它是加强搜寻，而不是重复搜寻。"},{"era":"LATIN circare","en":"The French verb goes back to Latin circare 'go about, wander, traverse', in Late Latin 'to wander hither and thither, go round, explore'.","cn":"法语动词可追溯到拉丁语 circare“四处走、漫游、穿行”，在晚期拉丁语中意为“来回游走、绕行、探查”。"},{"era":"circus","en":"Circare comes from circus 'circle, ring', the word behind English circus. The circle is the shape of the search: you walk around the thing until you have covered it.","cn":"circare 来自 circus“圆圈、环”，也就是英语 circus 的来源。圆圈就是搜寻的形状：你绕着那个东西走，直到把它全部覆盖。"},{"era":"1590s / 1630s / 1690s","en":"The verb appears in the 1590s meaning 'investigate or study closely'. The scientific sense of the noun is attested by the 1630s, and the general sense 'habit of making close investigations' by the 1690s.","cn":"动词出现于 16 世纪 90 年代，意为“细致调查或研究”。名词的科学义在 17 世纪 30 年代有记录，泛指“细致调查的习惯”在 17 世纪 90 年代有记录。"},{"era":"MODERN ENGLISH","en":"The intransitive verb 'make researches' is from 1781, and research and development is recorded from 1923. As a noun, research is normally uncountable: one says research or a research project, not a research.","cn":"不及物动词“做研究”始于 1781 年，research and development 记录于 1923 年。作名词时，research 通常不可数：应说 research 或 a research project，而不说 a research。"}]},"similar":{"note":{"en":"The first group separates the derived forms and the hyphenated literal verb from research; the second compares the four words learners use in its place. Two usage facts matter: research is normally uncountable as a noun, and the subject is introduced by on or into. All five words in this batch start with the letters re-, but only four have the prefix.","cn":"第一组把派生形式与带连字符的字面动词同 research 分开；第二组比较学习者用来替换它的四个词。两条用法事实很关键：research 作名词通常不可数，题目用 on 或 into 引出。本批五个词都以 re- 开头，但只有四个带该前缀。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"researcher","ipa":"/rɪˈsɜːtʃə/","tag":"derived noun","definition":"a person who carries out research. It names the person, while research names the activity or its findings.","definitionCN":"从事研究的人。它命名人，而 research 命名活动或其成果。"},{"word":"re-search","ipa":"/ˌriːˈsɜːtʃ/","tag":"literal hyphenated verb","definition":"to search a place or source again. With a hyphen the re- means 'again' plainly, as opposed to the intensifying re- of research.","definitionCN":"再次搜寻某个地方或来源。带连字符时 re- 明白地表示“再次”，与 research 中加强语气的 re- 相对。"},{"word":"researches","ipa":"/rɪˈsɜːtʃɪz/","tag":"form, not a new word","definition":"either the third-person singular of the verb or a rare plural of the noun. It is a form of research, not a separate root.","definitionCN":"或是动词的第三人称单数，或是名词罕见的复数。它是 research 的一种词形，不是另一个词根。"},{"word":"researchable","ipa":"/rɪˈsɜːtʃəbl/","tag":"derived adjective","definition":"able to be investigated with evidence and method. It describes a topic's fitness for research, not the research itself.","definitionCN":"可以用证据与方法加以研究的。它描述题目是否适合研究，而不是研究本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"search","ipa":"/sɜːtʃ/","tag":"same root, no re-","definition":"to look for something by examining a place or a set of sources. It is the shorter parent word: search looks for a missing thing, research circles a subject to explain it.","definitionCN":"通过检查某个地方或一组来源来寻找某物。它是更短的母词：search 找一件缺失的东西，research 绕着题目转以解释它。"},{"word":"study","ipa":"/ˈstʌdi/","tag":"learning or examining","definition":"to spend time learning about a subject, often by reading or attending a course. It can be personal learning, while research aims at producing new findings.","definitionCN":"花时间学习某个科目，常通过阅读或上课。它可以是个人学习，而 research 旨在产生新的发现。"},{"word":"investigation","ipa":"/ˌɪnvestɪˈɡeɪʃn/","tag":"official or systematic inquiry","definition":"an official or systematic examination of facts, especially to find out what happened or who is responsible. It is often about an incident, while research is usually about a question.","definitionCN":"对事实的正式或系统审查，尤为了解发生了什么或谁该负责。它常针对一起事件，而 research 通常针对一个问题。"},{"word":"inquiry","ipa":"/ɪnˈkwaɪəri/","tag":"question or formal probe","definition":"a request for information, or a formal examination of a matter. It is nearer to asking, while research implies method, evidence, and time.","definitionCN":"信息询问，或对某事的正式调查。它更接近“提问”，而 research 意味着方法、证据与时间。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: re- as an intensifier, French cerchier, Latin circare 'go about', circus 'circle', and the uncountable noun pattern.","cn":"只用真实成分与真实同族词：加强语气的 re-、法语 cerchier、拉丁语 circare“四处走动”、circus“圆圈”，以及不可数名词的用法规律。"},"normal":[{"en":"research and search share the Latin circare root: search looks for one thing, research walks all the way around a subject.","cn":"research 与 search 共享拉丁语 circare 词根：search 找一件东西，research 绕着一个题目走一整圈。"},{"en":"Circare comes from circus 'circle', so the shape of research is a ring drawn around a question.","cn":"circare 来自 circus“圆圈”，所以研究的形状就是围绕一个问题画出的一个环。"},{"en":"As a noun it is uncountable: say research, some research, a research project — never a research.","cn":"作名词时不可数：说 research、some research、a research project——绝不说 a research。"},{"en":"The subject takes on or into: research on sleep, research into the cause.","cn":"题目用 on 或 into 引出：research on sleep、research into the cause。"},{"en":"The noun is from the 1570s, the verb from the 1590s, and the intransitive 'do research' from 1781.","cn":"名词始于 16 世纪 70 年代，动词始于 16 世纪 90 年代，不及物用法“做研究”始于 1781 年。"}],"abstract":[{"en":"Picture a detective walking a slow circle around a locked house, checking every wall before touching the door.","cn":"想象一名侦探绕着一栋上锁的房子慢慢走圈，先查看每一面墙，再碰那扇门。"},{"en":"A single search is a straight dash to a lost key; research is the longer orbit that explains why the key was lost.","cn":"一次 search 是直奔丢失钥匙的直线冲刺；research 是更长的轨道运行，用来解释钥匙为什么会丢。"},{"en":"Because the noun names both the walking and what the walking found, 'the research shows' treats a journey as a result.","cn":"因为名词既指走这一圈，也指这一圈找到的东西，所以说 the research shows 时，一段旅程被当成了结果。"}]},"examples":[{"en":"The team spent two years doing research on how the river changes after heavy rain.","cn":"团队花了两年研究这条河在暴雨之后如何变化。"},{"en":"She researched the company's history before the interview.","cn":"面试之前，她仔细查过这家公司的历史。"},{"en":"Recent research suggests that short naps improve afternoon concentration.","cn":"近期研究显示，短暂午睡能提高下午的注意力。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「日搜取」——每天搜索、每天取回一点证据 → research 研究；调查（只借音，不表词源）","word":"research"},"root":"源自中古法语 recerchier，深层是 re-（加强）加晚期拉丁语 circare“四处走动”，而 circare 出自 circus“圆圈”，核心是“围绕一个题目反复兜圈子地找”。","sensesIntro":{"en":"Eight senses of research, all from one path: walking around a subject until it has been covered. The noun is normally uncountable, so the many senses are branches of one activity rather than separate countable things.","cn":"research 的八个义项都来自同一条路径：绕着一个题目走，直到把它覆盖完。名词通常不可数，因此这些义项是一项活动的多个分支，而不是一个个可数的东西。"},"semanticMap":{"core":{"en":"CORE IMAGE: a slow circle walked around a subject until every side has been seen.","cn":"核心意象：绕着一个题目慢慢走一圈又一圈，直到每一面都被看过。"},"chain":["A SUBJECT TO EXAMINE","WALK AROUND IT","LOOK FROM EVERY SIDE","RECORD WHAT IS SEEN","FINDINGS ACCUMULATE","THE SEARCH REPEATS"],"branches":[{"senses":"S1 · S3","en":"THE ACTIVITY: systematic inquiry and the habit of close investigation are the circling itself, without a named product.","cn":"活动本身：系统调查与追根究底的习惯就是这一圈行走，尚未产出被命名的成果。"},{"senses":"S2 · S4","en":"ONE PROJECT AND ITS RESULTS: a named subject narrows the circle, and the findings are what the circle brought back.","cn":"一个项目及其结果：具体题目收窄了这个圈，而研究结果就是这一圈带回来的东西。"},{"senses":"S5","en":"ATTRIBUTIVE USE: the activity becomes a label on grants, papers and teams.","cn":"定语用法：这项活动变成贴在经费、论文与团队上的标签。"},{"senses":"S6 · S7","en":"THE VERBS: transitive research acts on a subject, intransitive research names the occupation.","cn":"动词：及物的 research 作用于某个题目，不及物的 research 指这份职业活动。"},{"senses":"S8","en":"LITERAL AGAIN: when the search genuinely repeats, the prefix returns to its ordinary meaning.","cn":"字面的“再次”：当搜寻真的重复时，前缀回到它平常的含义。"}]},"affixes":{"intro":{"en":"Research is re- plus the French-Latin root circ-. The prefix strengthens rather than repeats, which is why the word is not 'search again' in its main sense. English adds -er, -able and -ing, while the root also supplies search, circle and circus.","cn":"research 是 re- 加上法式拉丁词根 circ-。前缀是加强而不是重复，所以这个词的主要义项并不是“再搜一遍”。英语加 -er、-able、-ing，同一词根还给出 search、circle、circus。"},"latinIntro":{"en":"Latin circare 'go about' is a verb built on circus 'circle, ring'. Circa 'around, about' belongs to the same circle family, which is why so many English words about going around share the circ- shape.","cn":"拉丁语 circare“四处走动”是由 circus“圆圈、环”构成的动词。circa“围绕、大约”属于同一个圆圈词族，这也是为什么英语里许多表示“绕行”的词都带着 circ- 的形状。"},"items":[{"word":"research","structure":"re- (intensive) + Old French cerchier < Latin circare (go about)","meaning":"to go around a subject until it is fully examined","meaningCN":"绕着一个题目走到把它查遍（re- 加强 + circare 绕行）","example":"They researched the market before launching the product.","exampleCN":"他们在推出产品之前先调查了市场。"},{"word":"researcher","structure":"research + -er (one who does)","meaning":"a person who does research","meaningCN":"研究者；研究员（-er 表示行为者）","example":"A researcher from the university tested the water.","exampleCN":"一位大学研究员检测了水质。"},{"word":"researchable","structure":"research + -able (can be done)","meaning":"possible to investigate with evidence","meaningCN":"可研究的（-able 表示能够）","example":"The question is interesting but hardly researchable with current tools.","exampleCN":"这个问题很有趣，但用现有工具几乎无法研究。"},{"word":"researching","structure":"research + -ing (participle or noun)","meaning":"the process of investigating; engaged in research","meaningCN":"研究过程；正在从事研究的（-ing 分词或动名词）","example":"She spent the winter researching in southern archives.","exampleCN":"她整个冬天都在南方的档案馆做研究。"},{"word":"search","structure":"Old French cerchier < Latin circare, without re-","meaning":"to look for something by examining places or sources","meaningCN":"搜寻；寻找（同为 circare 词根，但没有 re-）","example":"They searched the room for the missing key.","exampleCN":"他们在房间里寻找那把丢失的钥匙。"},{"word":"circle","structure":"Latin circulus, diminutive of circus (ring)","meaning":"a round shape or to move around something","meaningCN":"圆圈；环绕（circus 的指小形式）","example":"The children sat in a circle on the floor.","exampleCN":"孩子们在地板上坐成一圈。"},{"word":"circus","structure":"Latin circus (ring, circular arena)","meaning":"a round arena, and later a travelling show","meaningCN":"圆形竞技场；马戏团（拉丁语 circus 圆环）","example":"The old circus building is now a market.","exampleCN":"那座旧圆形剧场如今成了市场。"},{"word":"circular","structure":"circul- (circle) + -ar (adjective)","meaning":"shaped like a circle","meaningCN":"圆形的；环形的（circul- 圆 + -ar 形容词）","example":"The table has a circular top of black stone.","exampleCN":"这张桌子有一个黑色石头的圆形桌面。"},{"word":"circulate","structure":"circul- (circle) + -ate (verb)","meaning":"to move around a closed path or among people","meaningCN":"循环；流传（circul- 圆 + -ate 动词）","example":"Warm air circulates through the pipes.","exampleCN":"暖空气在管道中循环。"},{"word":"circulation","structure":"circulate + -ion (noun of process)","meaning":"movement around a loop, or the spread of something","meaningCN":"循环；流通；发行量（-ion 构成过程名词）","example":"The fans keep the air in circulation.","exampleCN":"风扇让空气保持流通。"},{"word":"circuit","structure":"circum- (around) + ire (go)","meaning":"a route that goes around and returns","meaningCN":"环行；电路（circum- 环绕 + ire 走）","example":"The racing cars completed one circuit of the track.","exampleCN":"赛车在赛道上跑完了一圈。"}],"latinEntries":[{"word":"circare","structure":"verb built on circus (circle, ring)","meaning":"to go about, wander, traverse","meaningCN":"四处走动；漫游；穿行"},{"word":"circus","structure":"Latin noun, from or cognate with Greek kirkos 'circle'","meaning":"circle, ring, circular arena","meaningCN":"圆圈；环；圆形竞技场"},{"word":"circa","structure":"Latin preposition/adverb from circum 'around'","meaning":"around, about, approximately","meaningCN":"围绕；大约"}]}},{"word":"reside","ipa_uk":"/rɪˈsaɪd/","ipa_us":"/rɪˈsaɪd/","definition_zh":"居住；定居；驻在；（权利、权力）归于；（原因、性质）存在于","definition_en":"to live in a place, especially officially or permanently, or of a right, power, cause, or quality, to be located in something","core_image":"在一个地方坐下来，并且一直坐在那里不走","scene":"大使馆的牌子上写着：大使及其家属驻在这座院落内。The plaque by the gate explains that the ambassador and his family reside inside these walls, where they both work and live.","sceneCN":"这里 reside 是「（官员因职务）驻在」（第 4 个义项：官员作为职责住在任职地点）；句意：门口的牌子上写着，大使及其家属驻在这道围墙之内，办公与居住都在其中。场景要点：使馆围墙、门口的名牌、院内的旗杆、亮着灯的办公窗。","pos":[{"tag":"vi.","zh":"居住；定居；驻在"},{"tag":"vi.","zh":"（权利、权力、原因、性质）存在于；归于"}],"collocations":[{"phrase":"reside in","zh":"居住于；（权利、原因）存在于"},{"phrase":"reside at","zh":"住在（某具体地点）"},{"phrase":"reside abroad","zh":"侨居国外"},{"phrase":"reside permanently","zh":"长期定居"},{"phrase":"reside with somebody","zh":"（权力）由某人掌握"},{"phrase":"legally reside","zh":"合法居住"},{"phrase":"reside in the fact that","zh":"在于……这一事实"}],"forms":[{"label":"三单（he/she/it）","form":"resides"},{"label":"过去式（已经发生）","form":"resided"},{"label":"过去分词（完成／被动）","form":"resided"},{"label":"现在分词（进行体）","form":"residing"}],"derivatives":[{"word":"residence","pos":"n.","zh":"住宅；居住；居留"},{"word":"resident","pos":"n./adj.","zh":"居民；住院医师；居住的"},{"word":"residential","pos":"adj.","zh":"住宅的；居住用的"},{"word":"residency","pos":"n.","zh":"居留权；住院医师培训期"},{"word":"residue","pos":"n.","zh":"剩余物；残渣"}],"senses":[{"no":"01","title":"Remain in a place for a time","titleCN":"在某地停留一段时间","definition":"to stay or remain in a place, often for a period, without necessarily settling there for good","definitionCN":"在某地停留或留下，常指一段时间，不一定永久定居","example":"He resided at the inn while the bridge was being repaired.","exampleCN":"桥梁维修期间，他住在旅馆里。","why":"The earliest English sense, from the late 15th century, is simply 'to remain at a place'. The Latin re- adds 'back' and sedere is 'to sit', so the image is sitting down and staying put.","whyCN":"最早的英语义项始于 15 世纪晚期，意思只是“留在某地”。拉丁语 re- 加“回”，sedere 是“坐”，所以意象是坐下来、待在原地不走。"},{"no":"02","title":"Dwell permanently","titleCN":"长期定居","definition":"to live in a place permanently or for a considerable time, as one's home","definitionCN":"永久或长期住在某地，把它当作自己的家","example":"The family resides in a small village outside the city.","exampleCN":"这家人住在城郊的一个小村庄里。","why":"From the 1570s the staying becomes a home. The seated figure no longer just passes time in a chair; the chair is now the one he owns.","whyCN":"从 16 世纪 70 年代起，停留变成了安家。坐着的人不再只是在一把椅子上消磨时间；这把椅子现在归他所有。"},{"no":"03","title":"Have a legal residence","titleCN":"拥有法定居所","definition":"in law and administration, to have one's fixed home or registered place of living in an area","definitionCN":"在法律与行政上，在某地区拥有固定住所或登记居住地","example":"To vote in the district, you must reside there for at least six months.","exampleCN":"要在该区投票，你必须在那里居住至少六个月。","why":"Law turns a physical fact into a status. Sitting in a place long enough is registered as a legal tie, so reside comes to name an official connection rather than a posture.","whyCN":"法律把一个身体事实变成一种身份。在一个地方坐得足够久，就会被登记为法律联系，于是 reside 命名的是正式关系，而不是坐姿。"},{"no":"04","title":"Live at an official post","titleCN":"因职务驻在任所","definition":"of an ambassador, priest, or other official, to live at the place where the duties are performed","definitionCN":"指大使、神职人员或其他官员住在履行职务的地点","example":"The ambassador resides at the embassy in the capital.","exampleCN":"大使驻在首都的大使馆里。","why":"Here the seat is supplied by the job. The official sits where the office is, so residing becomes part of the duty rather than a private choice.","whyCN":"这里的座位由职务提供。官员坐在办公室所在之处，于是居住成了职责的一部分，而不是私人选择。"},{"no":"05","title":"Rights and power reside in somebody","titleCN":"权利与权力归于某人","definition":"of a right, power, or authority, to belong to or be held by a person or body","definitionCN":"指权利、权力或权威属于或被某人、某机构掌握","example":"Sovereignty resides with the people, not with the government.","exampleCN":"主权属于人民，而不属于政府。","why":"The image becomes abstract: a right is thought of as sitting inside its holder. Whoever the power sits in is the one who legitimately holds it.","whyCN":"意象变抽象了：一项权利被想象为坐在它的持有者体内。权力坐在谁那里，谁就是合法持有它的人。"},{"no":"06","title":"A cause or difficulty resides in something","titleCN":"原因或困难存在于某处","definition":"of a cause, problem, or difficulty, to be located in a particular point or element","definitionCN":"指原因、问题或困难位于某个特定环节或要素之中","example":"The real difficulty resides in the final step of the process.","exampleCN":"真正的困难在于流程的最后一步。","why":"A problem is given a place to sit. Saying where it resides is saying where it lives, which is the first step toward removing it.","whyCN":"一个问题被赋予了一个可以坐下的位置。说它 reside 在哪里，就是说它住在哪里，这也是消除它的第一步。"},{"no":"07","title":"A quality or meaning resides in something","titleCN":"品质或意义存在于某物","definition":"of a quality, value, or meaning, to be present in something as its source","definitionCN":"指某种品质、价值或意义作为源头存在于某物之中","example":"The charm of the old house resides in its uneven stone walls.","exampleCN":"这座老房子的魅力在于它参差不齐的石墙。","why":"The same seat is now inside an object. A quality is not spread everywhere but sits in one feature, and that feature is what gives the thing its character.","whyCN":"同一个座位现在位于一个物体内部。品质不是到处散布，而是坐在某一个特征里，正是那个特征赋予事物性格。"},{"no":"08","title":"A faculty resides in a body part","titleCN":"机能存在于某个身体部位","definition":"of a power, function, or faculty, to be located in a particular organ or part of the body","definitionCN":"指某种能力、功能或机能位于某个器官或身体部位","example":"The sense of balance resides in the inner ear.","exampleCN":"平衡感存在于内耳。","why":"Anatomy gives the abstract seat a physical address. The faculty sits in the organ that produces it, and the old image of sitting is now literal again.","whyCN":"解剖学给这个抽象的座位一个物理地址。机能在产生它的器官里“坐着”，古老的“坐”的意象又变得字面化了。"}],"etymology":{"intro":{"en":"Reside is re- 'back, again' plus Latin sedere 'to sit'. The prefix marks position, not repetition or intensity, and the root is the sitting root *sed-. That makes it unrelated to recover (capere 'take'), require (quaerere 'ask') and research (circare 'go about'), even though all four begin with re-. Region does not even have the prefix: its re- belongs to reg- 'direct, rule'.","cn":"reside 是 re-“回、再”加拉丁语 sedere“坐”。这个前缀标记位置，而不是重复或加强，词根是表示“坐”的 *sed-。因此它与 recover（capere“拿取”）、require（quaerere“询问”）、research（circare“绕行”）都不同族，尽管这四个词都以 re- 开头。region 甚至连前缀都没有：它的 re- 属于 reg-“引导、统治”。"},"items":[{"era":"LATE 15C.","en":"First recorded in English as 'to remain at a place', from Old French resider (15c.) and directly from Latin residere.","cn":"英语最早记录为“留在某地”，来自古法语 resider（15 世纪），并直接来自拉丁语 residere。"},{"era":"LATIN residere","en":"Latin residere meant 'sit down, settle; remain behind, rest, linger; be left'. The re- is 'back, again', and sedere is 'to sit'.","cn":"拉丁语 residere 意为“坐下、安顿；留在后面、休息、逗留；被留下”。其中 re- 是“回、再”，sedere 是“坐”。"},{"era":"PIE *sed-","en":"Sedere goes back to PIE *sed- (1) 'to sit', the root behind sediment, session, preside and even saddle. The root describes a body at rest on a surface.","cn":"sedere 可追溯到原始印欧语 *sed-（1）“坐”，这一词根也是 sediment、session、preside 乃至 saddle 的来源。这个词根描述的是一具停在某个表面上的身体。"},{"era":"1570s","en":"The sense 'to dwell permanently or for a considerable time' is attested by the 1570s, turning a temporary stay into a home.","cn":"“永久或长期居住”的义项在 16 世纪 70 年代有记录，把临时停留变成了安家。"},{"era":"DERIVATIVES","en":"Residence and resident are both recorded in the late 14th century, before the verb's 'dwell' sense. Residue, from Latin residuum 'what is left behind', keeps the literal 'remain behind' sense of the same root.","cn":"residence 与 resident 都记录于 14 世纪晚期，早于动词的“居住”义。residue 来自拉丁语 residuum“留在后面的东西”，保留了同一词根字面的“留在后面”之义。"},{"era":"MODERN ENGLISH","en":"Modern English keeps reside as a formal or legal verb; the everyday word is live. The abstract branch 'reside in/with' is now the most productive one, used for rights, causes, qualities and faculties.","cn":"现代英语把 reside 保留为正式或法律动词；日常用词是 live。抽象分支“reside in／with”如今最能产，用于权利、原因、品质与机能。"}]},"similar":{"note":{"en":"The first group separates the family of nouns and adjectives built on the same sitting root; the second compares the everyday verbs of living. Reside is the formal member of that set, and its re- means position, not repetition. Only four of the five words in this batch carry the prefix.","cn":"第一组把建立在同一个“坐”词根上的名词与形容词家族分开；第二组比较日常表示“住”的动词。reside 是这一组里正式的成员，它的 re- 表示位置，而不是重复。本批五个词里只有四个带前缀。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"residence","ipa":"/ˈrezɪdəns/","tag":"derived noun","definition":"the fact of living in a place, or the place itself. It is the noun, while reside is the verb.","definitionCN":"居住在某地的事实，或住所本身。它是名词，而 reside 是动词。"},{"word":"resident","ipa":"/ˈrezɪdənt/","tag":"person or adjective","definition":"a person who lives in a place, or the adjective meaning 'living there'. It names the person, not the act.","definitionCN":"居住在某地的人，或表示“居住的”形容词。它命名人，而不是动作。"},{"word":"residential","ipa":"/ˌrezɪˈdenʃl/","tag":"derived adjective","definition":"used for or consisting of homes rather than offices or industry. It describes the character of an area, not a person's act of living.","definitionCN":"用于住宅或由住宅构成的，而非办公或工业用途。它描述一个区域的性质，而不是个人的居住行为。"},{"word":"residue","ipa":"/ˈrezɪdjuː/","tag":"same root, different meaning","definition":"what is left behind after a part is taken or used. It keeps the literal Latin sense 'remain behind' of residere, but has nothing to do with living.","definitionCN":"一部分被取走或用掉之后剩下的东西。它保留了 residere 字面的“留在后面”之义，但与居住无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"live","ipa":"/lɪv/","tag":"everyday verb","definition":"to have one's home in a place. It is the plain everyday verb, while reside is formal and often legal or official.","definitionCN":"在某地安家。它是最朴素的日常动词，而 reside 正式，常带法律或官方色彩。"},{"word":"dwell","ipa":"/dwel/","tag":"literary or formal","definition":"to live in a place, often used in literature or descriptions of houses. It is more static and literary than reside, and rarely appears in official forms.","definitionCN":"居住在某地，常用于文学或房屋描写。它比 reside 更静止、更文学化，很少出现在正式表格里。"},{"word":"stay","ipa":"/steɪ/","tag":"temporary","definition":"to remain in a place for a short time as a guest or visitor. It stresses the temporary visit, while reside can mean a permanent or legal home.","definitionCN":"作为客人或访客在某地短期停留。它强调临时到访，而 reside 可以指永久或法定的家。"},{"word":"sojourn","ipa":"/ˈsɒdʒən/","tag":"formal temporary stay","definition":"to stay in a place temporarily, especially as a traveller. It is formal and clearly temporary, while reside is settled and official.","definitionCN":"临时住在某地，尤指作为旅居者。它正式且明确是临时的，而 reside 是安顿下来的、官方的。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: re- 'back' plus sedere 'to sit', the residence family, the residue branch from the same root, and the *sed- relatives sediment, session and preside.","cn":"只用真实成分与真实同族词：re-“回”加 sedere“坐”、residence 词族、同根但意义不同的 residue 分支，以及 *sed- 的同族词 sediment、session、preside。"},"normal":[{"en":"re- is 'back' and sedere is 'to sit'. Reside is to sit down in a place and stay there.","cn":"re- 是“回”，sedere 是“坐”。reside 就是在一个地方坐下来并待在那里。"},{"en":"The same *sed- root gives sediment (what settles), session (a sitting), preside (sit in front) and saddle (a seat).","cn":"同一 *sed- 词根给出 sediment（沉下来的东西）、session（一次坐会）、preside（坐在前面）、saddle（座位）。"},{"en":"residence, resident and residential are the noun and adjective family; reside is the formal verb behind them.","cn":"residence、resident、residential 是名词与形容词家族；reside 是它们背后那个正式的动词。"},{"en":"Residue comes from the same root's 'remain behind' sense, which is why it means what is left over, not where someone lives.","cn":"residue 来自同一词根“留在后面”的义项，所以它指剩下的东西，而不是某人住在哪里。"},{"en":"For everyday speech use live; for forms, law and diplomacy use reside.","cn":"日常口语用 live；表格、法律与外交场合用 reside。"}],"abstract":[{"en":"Picture a chair placed in a room. Reside is the act of sitting down on it and not moving away.","cn":"想象房间里摆着一把椅子。reside 就是坐上去并且不再离开的动作。"},{"en":"Move that chair inside a person or a thing, and power, causes and qualities begin to 'sit' there: sovereignty resides with the people.","cn":"把椅子搬进一个人或一件东西内部，权力、原因与品质就开始“坐”在那里：主权 reside 于人民。"},{"en":"The word is a legal seat, not a daily address: it tells you where someone is officially planted.","cn":"这个词是一个法律上的座位，而不是日常住址：它告诉你某人在官方意义上被安置在哪里。"}]},"examples":[{"en":"Only about two hundred people reside on the island all year.","cn":"全年只有大约两百人居住在这座岛上。"},{"en":"Under the treaty, the right to fish resides with the coastal villages.","cn":"根据条约，捕鱼权归于沿海村庄。"},{"en":"The real strength of the design resides in its simplicity.","cn":"这个设计真正的力量在于它的简洁。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「瑞塞得」——瑞把行李塞进屋里，坐下就不走了 → reside 居住；定居（只借音，不表词源）","word":"reside"},"root":"源自拉丁语 residere“坐下、留下”，re- 表示“回、在后”，sedere 是“坐”，核心是“在一个地方坐下来、一直待在那里”。","sensesIntro":{"en":"Eight senses of reside, all one posture: a body sits down in a place and stays. The place can be a room, a legal district, a post, a holder of power, a cause, an object, or an organ.","cn":"reside 的八个义项都来自同一个姿态：一具身体在某个位置坐下来并待着。这个位置可以是房间、法定辖区、任所、权力持有者、原因、物体或器官。"},"semanticMap":{"core":{"en":"CORE IMAGE: someone sits down in a place and remains seated there.","cn":"核心意象：某人在一个地方坐下，并一直坐在那里。"},"chain":["SIT DOWN","STAY IN PLACE","MAKE IT HOME","REGISTER THE ADDRESS","THE SEAT BECOMES ABSTRACT","THE QUALITY SITS INSIDE"],"branches":[{"senses":"S1 · S2","en":"STAYING AND DWELLING: the physical posture first means remaining, then means having a home.","cn":"停留与定居：身体姿态先表示“留下”，再表示“安家”。"},{"senses":"S3 · S4","en":"OFFICIAL SEATS: law registers the address, and a post assigns the seat as part of the duty.","cn":"官方座位：法律登记住址，职务则把座位作为职责的一部分分配下来。"},{"senses":"S5","en":"POWER: a right sits inside the person or body that legitimately holds it.","cn":"权力：权利坐在合法持有它的个人或机构内部。"},{"senses":"S6 · S7","en":"CAUSES AND QUALITIES: a problem or a charm is given a seat in the one element that produces it.","cn":"原因与品质：问题或魅力被安置在产生它的那个要素里。"},{"senses":"S8","en":"THE BODY: anatomy gives the abstract seat a physical organ to sit in.","cn":"身体：解剖学给这个抽象的座位一个可以坐进去的实体器官。"}]},"affixes":{"intro":{"en":"Reside is re- plus the Latin sitting root sed-. English adds -ence, -ent, -ial and -cy to build the family, while the same root reaches English through residue, sediment, session and preside. The re- here marks position, not repetition.","cn":"reside 是 re- 加拉丁语“坐”的词根 sed-。英语加 -ence、-ent、-ial、-cy 构成词族，同一词根还通过 residue、sediment、session、preside 进入英语。这里的 re- 标记位置，而不是重复。"},"latinIntro":{"en":"Latin sedere 'to sit' has the agent noun sedes 'a seat' and the prefixed verb residere 'sit down, remain behind'. The PIE root *sed- is one of the oldest and most productive roots about resting on a surface.","cn":"拉丁语 sedere“坐”有施动名词 sedes“座位”，以及加前缀的动词 residere“坐下、留在后面”。原始印欧语词根 *sed- 是关于“停在表面上”的最古老、最能产的词根之一。"},"items":[{"word":"reside","structure":"re- (back) + sedere (to sit)","meaning":"to sit down and remain in a place","meaningCN":"在一个地方坐下并留下（re- 回 + sedere 坐）","example":"The bishop resides in the cathedral close.","exampleCN":"主教住在教堂庭院内。"},{"word":"residence","structure":"reside + -ence (noun of state)","meaning":"the state of living somewhere, or the place itself","meaningCN":"居住状态；住所（-ence 构成状态名词）","example":"The police searched his residence on the hill.","exampleCN":"警方搜查了他山上的住所。"},{"word":"resident","structure":"reside + -ent (person or adjective)","meaning":"a person who lives in a place; living there","meaningCN":"居民；居住的（-ent 构成人或形容词）","example":"Local residents opposed the new road.","exampleCN":"当地居民反对这条新路。"},{"word":"residential","structure":"resident + -ial (adjective)","meaning":"consisting of or used for homes","meaningCN":"住宅的；居住用的（-ial 构成形容词）","example":"The street is purely residential, with no shops.","exampleCN":"这条街纯属住宅区，没有店铺。"},{"word":"residency","structure":"resident + -cy (noun of status)","meaning":"the right to live in a country, or a period of supervised training","meaningCN":"居留权；住院医师培训期（-cy 构成身份名词）","example":"She applied for permanent residency after five years.","exampleCN":"五年之后她申请了永久居留权。"},{"word":"residue","structure":"Latin residuum, from residere (remain behind)","meaning":"what is left behind","meaningCN":"剩余物；残渣（拉丁语 residuum“留在后面的东西”）","example":"Wash the residue out of the tank with clean water.","exampleCN":"用清水把罐里的残渣冲掉。"},{"word":"residual","structure":"residue + -al (adjective)","meaning":"remaining after the main part is gone","meaningCN":"残留的；剩余的（-al 构成形容词）","example":"Tests found residual sugar in the wine.","exampleCN":"检测发现酒里还有残留糖分。"},{"word":"sediment","structure":"sedi- (sedere, sit) + -ment (result)","meaning":"material that settles at the bottom of a liquid","meaningCN":"沉积物；沉淀（sedi- 坐 + -ment 结果）","example":"A layer of sediment covered the river bed.","exampleCN":"一层沉积物覆盖了河床。"},{"word":"session","structure":"sess- (sedere, sit) + -ion (noun of action)","meaning":"a period of sitting together for work or discussion","meaningCN":"会议；一段时间（sess- 坐 + -ion 行为名词）","example":"The committee held a long session on the budget.","exampleCN":"委员会就预算开了一次长会。"},{"word":"preside","structure":"pre- (before) + sedere (to sit)","meaning":"to sit in the leading position and run a meeting","meaningCN":"主持；担任主席（pre- 在前 + sedere 坐）","example":"The mayor presided over the opening ceremony.","exampleCN":"市长主持了开幕仪式。"},{"word":"president","structure":"preside + -ent (person who does)","meaning":"the person who presides over a body or state","meaningCN":"总统；主席；行长（-ent 表示行为者）","example":"The president addressed the assembly at noon.","exampleCN":"总统在中午向大会发表讲话。"},{"word":"saddle","structure":"English word from the *sed- 'sit' family, not a Latin derivative","meaning":"a seat for a rider on an animal or bicycle","meaningCN":"马鞍；车座（同出 *sed-“坐”词族，并非拉丁语派生）","example":"He tightened the saddle before mounting.","exampleCN":"上马之前他把马鞍系紧了。"}],"latinEntries":[{"word":"sedere","structure":"Latin verb, from PIE *sed- (1) 'to sit'","meaning":"to sit, be seated","meaningCN":"坐；就座"},{"word":"residere","structure":"re- (back) + sedere (sit)","meaning":"to sit down, settle, remain behind","meaningCN":"坐下；安顿；留在后面"},{"word":"sedes","structure":"sed- (sit) + -es (noun of state)","meaning":"a seat, a place to sit","meaningCN":"座位；坐处"}]}}]);
